// Vista → módulo que la habilita. Sirve para ocultarla de la nav y bloquear su acceso si el módulo está apagado (para LEA: inerte, todo ON).
const VIEW_MODULO = { horas:'horas', repricing:'horas', sales:'finanzas', billing:'finanzas', cobranza:'finanzas', conciliacion:'finanzas', anticipos:'finanzas', presupuestoOficina:'finanzas', expenses:'gastos', cajachica:'gastos', cartera:'proyectos', inteligencia:'bi', bi:'bi', portal:'portal' }
// Fecha breve '15 jun' (omite el año si es el actual; muestra '15 jun 24' si es otro año). Para botones-calendario compactos.
const fechaBreve = d => { if(!d) return ''; const p=String(d).slice(0,10).split('-'); if(p.length!==3) return String(d); const M=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic']; const cur=new Date().getFullYear(); return `${+p[2]} ${M[+p[1]-1]||p[1]}${+p[0]!==cur?` ${p[0].slice(2)}`:''}` }
// Fecha breve SIEMPRE con año ('19 jun 26'). Para campos donde el año importa.
const fechaConAnio = d => { if(!d) return ''; const p=String(d).slice(0,10).split('-'); if(p.length!==3) return String(d); const M=['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic']; return `${+p[2]} ${M[+p[1]-1]||p[1]} ${p[0].slice(2)}` }
// ¿Marcar esta factura como pagada quedaría SIN respaldo bancario? True SOLO en discrepancia real:
// la cartola YA cubre esa fecha de pago pero ningún movimiento del banco la respalda. (Pago reciente = pendiente cartola → NO avisa; histórico → NO avisa; ya conciliada → NO avisa.)
function sinRespaldoAlPagar(b, fechaPago, respaldoMap={}, cartolaHasta=null){
  if(!b || (b.billing_type||'')==='reembolso') return false
  const monto=b.amount||0, aplicado=respaldoMap[b.id]||0
  const fp=String(fechaPago||'').slice(0,10)
  if(!(monto>0) || aplicado>=monto) return false          // ya conciliada (total)
  if(fp && fp<RESPALDO_CUTOFF) return false                // histórica (sin banco esperado)
  if(!cartolaHasta || !fp || fp>cartolaHasta) return false // pago reciente / sin datos de cartola = pendiente cartola
  return true                                              // cartola cubre la fecha y no hay respaldo → discrepancia real
}
const simNombre = (a,b) => { const x=nrmCliente(a),y=nrmCliente(b); if(!x||!y) return 0; if(x===y) return 1; return 1 - _lev(x,y)/Math.max(x.length,y.length) }
// Motivos de rechazo de una propuesta ("por qué perdimos"): picklist canónico; "Otro" agrega texto libre y se aprende.
const MOTIVOS_RECHAZO = ['Precio / honorarios','Se fue con otro estudio','Lo resolvió internamente','Sin respuesta / se enfrió','Lo postergó (timing)','Fuera de nuestra área','Conflicto de interés']
// Factura con folio del SII: nunca se elimina, se anula con nota de crédito (misma regla que el trigger trg_billing_guard_folio_delete).
const conFolioSII = b => !!String(b?.invoice_no||'').trim()
const MSG_NO_BORRAR_FOLIO = 'Las facturas con folio del SII no se eliminan: se anulan con nota de crédito.'
// Folio SOLO dígitos: para deduplicar facturas sin importar si vienen "318" o "Factura 318" (causa de duplicados en cargas).
const folioDigits = no => String(no||'').replace(/\D/g,'')
// Buscador de cabecera (mismo lenguaje: fondo suave, sin borde, píldora)
const chipSearch = {height:32,width:'100%',background:C.bgSoft,border:'none',borderRadius:20,fontSize:13,padding:'0 14px',color:C.text,outline:'none',boxSizing:'border-box'}
// Ítems que por defecto son INGRESO (restan al costo, ej. subarriendo recupera parte del arriendo).
const OFICINA_INGRESO_ITEMS = new Set(['Subarriendo'])
// Cobrado del mes (fuente única, = EstadoResultadosModal): facturas con paid_at en el mes, netas de anuladas/reembolsos, vía cobradoBill. Comisión del mes = terceros_pagos pagados en el mes. Ambas reusadas por OficinaHub para no divergir.
const ingresosMesBill = (billing, ym) => (billing||[]).filter(b=>b&&!b.deleted_at&&b.status!=='Anulada'&&b.billing_type!=='reembolso'&&String(b.paid_at||'').startsWith(ym)).reduce((a,b)=>a+cobradoBill(b),0)
const comisionMesTerc = (terceros, ym) => (terceros||[]).filter(t=>t&&t.estado==='pagado'&&String(t.pagado_at||'').startsWith(ym)).reduce((a,t)=>a+(Number(t.monto)||0),0)
function contadoraBancoMes(expenses, clients, ym){ return contadoraBancoItems(expenses,clients,ym).reduce((a,e)=>a+(Number(e.amount)||0),0) }
function gastosVariosOfiMes(expenses, clients, ym){ return gastosVariosOfiItems(expenses,clients,ym).reduce((a,e)=>a+(Number(e.amount)||0),0) }
const facturadoSiiPeriodo = (billing, ym) => (billing||[]).filter(b=> b && !b.deleted_at && b.dte_xml && b.invoice_no && b.status!=='Anulada' && b.billing_type==='honorarios' && String(b.issued_at||'').startsWith(ym)).reduce((a,b)=>a+montoFactura(b),0)
function BitacoraUltima({prefijo, render}){
  const [row,setRow]=useState(undefined)
  useEffect(()=>{ let vivo=true; if(DEMO){ setRow((demoData.historial||[]).filter(r=>String(r.action).startsWith(prefijo)).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)))[0]||null); return }
    supabase.from('activity_log').select('id,action,created_at').like('action',prefijo+'%').order('created_at',{ascending:false}).limit(1)
      .then(({data})=>{ if(vivo) setRow((data||[])[0]||null) }).catch(()=>{ if(vivo) setRow(null) })
    return ()=>{ vivo=false } },[prefijo])
  return render(row)
}

// Bitácora de cargas del SII (sii_import_batches): TODA carga deja registro (XML lo hace vía ensureBatch; PDF/Drive/Excel pasan por aquí). Nunca bloquea.
async function logCargaSII({tipo, n=0, user, period=null, files=[]}){
  if(DEMO) return
  try{ await supabase.from('sii_import_batches').insert({ created_by:user?.name||null, period, docs_total:n, skipped:0, files, counts:n?{cre:n}:{}, tipo }) }catch(e){registrarError({origen:'accion',vista:'sii_import_batches',err:e})}
}

// CORTE DE APERTURA: lo anterior al corte se resume en UN movimiento "Saldo de apertura" (category 'Apertura': fondo si queda
// a favor del cliente, gasto si nos debe, $0 = cerrado) y los movimientos de antes quedan con apertura_id = esa fila → siguen
// visibles e intactos, pero ya no suman al saldo ni se rinden. Deshacer = borrar la apertura (apertura_id vuelve a null).
const CORTE_APERTURA = '2026-06-01'
const DaysBadge = ({due,status}) => {
  const u=urgency(due,status); if(u==='done') return null
  const d=daysLeft(due); if(d===null) return null
  const label=d<0?`${Math.abs(d)}d vencido`:d===0?'hoy':`${d}d`
  return <span style={{fontSize:10,fontWeight:600,color:urgencyColor(due,status),whiteSpace:'nowrap'}}>{label}</span>
}
// Logo de marca FirmDesk. variant: primary (tile azul) | mono (F azul sobre claro) | accent (tile verde)
const FirmDeskMark = ({size=40,variant='primary'}) => {
  const tile = variant==='accent'?C.normal:variant==='mono'?'#FFFFFF':C.accent
  const letter = variant==='primary'?'#F2F2F0':variant==='accent'?'#FFFFFF':C.accent
  const desk = variant==='accent'?C.accent:C.normal
  return (
    <svg width={size} height={size} viewBox='0 0 56 56' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='FirmDesk'>
      <rect x={variant==='mono'?0.5:0} y={variant==='mono'?0.5:0} width={variant==='mono'?55:56} height={variant==='mono'?55:56} rx='15' fill={tile} stroke={variant==='mono'?'#E4E2DD':'none'}/>
      <rect x='20' y='14' width='5' height='25' fill={letter}/>
      <rect x='20' y='14' width='18' height='5' fill={letter}/>
      <rect x='20' y='23.5' width='12' height='5' fill={letter}/>
      <rect x='16' y='40' width='24' height='4' rx='2' fill={desk}/>
    </svg>
  )
}
// Lockup horizontal marca + wordmark FirmDesk
const FirmDeskLockup = ({mark=30,font=19,gap=10}) => (
  <span style={{display:'inline-flex',alignItems:'center',gap}}>
    <FirmDeskMark size={mark}/>
    <span style={{fontFamily:"'Hanken Grotesk',system-ui,sans-serif",fontSize:font,fontWeight:600,letterSpacing:-.5,color:C.accent,lineHeight:1}}>Firm<span style={{color:C.normal}}>Desk</span></span>
  </span>
)
const BanIcon = ({size=15,color}) => (
  <svg width={size} height={size} viewBox='0 0 24 24' fill='none' stroke={color||C.overdue} strokeWidth='2' strokeLinecap='round'><circle cx='12' cy='12' r='9'/><line x1='5.6' y1='5.6' x2='18.4' y2='18.4'/></svg>
)
function DialogHost(){
  const [q,setQ] = useState(null); const [val,setVal] = useState('')
  useEffect(()=>{ setDialogHost((o)=> new Promise(resolve=>{ setVal(o.def||''); setQ({...o, resolve}) })); return ()=>{ setDialogHost(null) } },[])
  if(!q) return null
  const done = v => { const r=q.resolve; setQ(null); r(v) }
  const isAlert=q.kind==='alert', isPrompt=q.kind==='prompt'
  return <Modal topmost title={q.title||(isAlert?'Aviso':'Confirmar')} onClose={()=>done(isAlert?true:(isPrompt?null:false))} closeOnBackdrop={false}>
    <div style={{fontSize:14,color:C.text,lineHeight:1.55,whiteSpace:'pre-wrap',marginBottom:isPrompt?12:18}}>{q.message}</div>
    {isPrompt && <input autoFocus value={val} onChange={e=>setVal(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')done(val)}} style={{width:'100%',border:`1px solid ${C.border}`,borderRadius:8,padding:'9px 11px',fontSize:14,color:C.text,outline:'none',boxSizing:'border-box',marginBottom:18,fontFamily:'inherit'}}/>}
    <div style={{display:'flex',gap:10,justifyContent:'flex-end'}}>
      {!isAlert && <button onClick={()=>done(isPrompt?null:false)} style={{background:'none',border:`1px solid ${C.border}`,borderRadius:10,padding:'8px 16px',fontSize:13,color:C.muted,cursor:'pointer',fontFamily:'inherit'}}>{q.cancelText||'Cancelar'}</button>}
      <button onClick={()=>done(isPrompt?val:true)} style={{background:C.accent,border:'none',borderRadius:10,padding:'8px 18px',fontSize:13,fontWeight:600,color:'#fff',cursor:'pointer',fontFamily:'inherit'}}>{q.confirmText||(isAlert?'Entendido':isPrompt?'Guardar':'Confirmar')}</button>
    </div>
  </Modal>
}

function LoginScreen({loading, denied, onRetry}) {
  // Pantalla de acceso = marca del PRODUCTO (FirmDesk, dirección "Ledger"), no del estudio.
  // Colores propios de FirmDesk (fuera de la paleta C del tenant, a propósito). El ingreso sigue siendo Google corporativo, sin cambios.
  const sm = typeof window!=='undefined' && window.innerWidth < 600
  const INK='#101418', GRN='#12A150', GREY='#5B6570', MONO="'Space Mono',ui-monospace,SFMono-Regular,Menlo,monospace"
  const [mlEmail,setMlEmail]=useState(''); const [mlSent,setMlSent]=useState(false); const [mlBusy,setMlBusy]=useState(false); const [mlErr,setMlErr]=useState(''); const [mlOpen,setMlOpen]=useState(false)
  const enviarLink=async()=>{ const em=mlEmail.trim().toLowerCase()
    if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)){ setMlErr('Ingresa un correo válido'); return }
    setMlBusy(true); setMlErr(''); onRetry&&onRetry()
    try{ const {error}=await signInWithMagicLink(em); if(error) throw error; setMlSent(true) }
    catch(e){ setMlErr(e?.message||'No se pudo enviar. Reintenta.') }
    setMlBusy(false) }
  return (
    <div style={{height:'100dvh',minHeight:'100svh',background:C.bg,position:'relative',display:'flex',flexDirection:'column',alignItems:'center',justifyContent:'center',boxSizing:'border-box',overflow:'hidden',padding:'20px 32px'}}>
      <div style={{width:sm?54:60,height:sm?54:60,borderRadius:'22%',background:INK,display:'flex',flexDirection:'column',justifyContent:'center',gap:'14%',padding:sm?14:16,marginBottom:16}}>
        <span style={{display:'block',height:'11%',width:'100%',borderRadius:4,background:GRN}}/>
        <span style={{display:'block',height:'11%',width:'68%',borderRadius:4,background:GREY}}/>
        <span style={{display:'block',height:'11%',width:'84%',borderRadius:4,background:GREY}}/>
      </div>
      <div style={{fontFamily:MONO,fontWeight:700,fontSize:sm?27:31,letterSpacing:'-.02em',color:INK}}>Firm<span style={{color:GRN}}>Desk</span></div>
      <div style={{fontFamily:MONO,fontSize:12,color:'#95A0A2',marginTop:8,marginBottom:denied?20:38}}>Every number, in its place.</div>
      {denied&&<div style={{maxWidth:320,background:'#FDECEA',border:'1px solid #F3C9C4',borderRadius:12,padding:'11px 15px',fontSize:13,color:'#A3312B',marginBottom:22,lineHeight:1.5,textAlign:'center'}}>Tu cuenta no tiene acceso a FirmDesk. Pídele a un administrador de tu oficina que te invite y vuelve a entrar.</div>}
      <button onClick={()=>{ onRetry&&onRetry(); signInWithGoogle() }} disabled={loading} style={{display:'inline-flex',alignItems:'center',justifyContent:'center',gap:9,minWidth:sm?220:240,background:'#fff',border:'1px solid #DADFDE',borderRadius:12,padding:'13px 18px',color:INK,fontSize:14,fontWeight:600,cursor:loading?'default':'pointer'}}>
        {loading?<Spin/>:<>
          <svg width="16" height="16" viewBox="0 0 48 48"><path fill="#4285F4" d="M45 24c0-1.6-.1-2.7-.4-3.9H24v7.1h12c-.2 1.9-1.5 4.7-4.3 6.6l6.6 5.1C42.6 41.6 45 33.6 45 24z"/><path fill="#34A853" d="M24 46c5.9 0 10.8-1.9 14.4-5.3l-6.6-5.1c-1.8 1.2-4.2 2-7.8 2-6 0-11-4-12.8-9.5l-6.8 5.3C7.9 40.9 15.3 46 24 46z"/><path fill="#FBBC05" d="M11.2 28.1c-.5-1.4-.7-2.8-.7-4.1s.3-2.8.7-4.1l-6.8-5.3C3 17.4 2 20.6 2 24s1 6.6 2.4 9.4l6.8-5.3z"/><path fill="#EA4335" d="M24 10.5c3.3 0 5.6 1.4 6.9 2.6l5.8-5.7C33.1 4.1 28.9 2 24 2 15.3 2 7.9 7.1 4.4 14.6l6.8 5.3C13 14.5 18 10.5 24 10.5z"/></svg>
          Continuar con Google
        </>}
      </button>
      {/* Acciones discretas al pie: entrar con correo (magic-link) y ver demo. Ambos íconos sobrios; el correo solo despliega su campo al tocar. */}
      <div style={{marginTop:38,display:'flex',alignItems:'center',gap:20,opacity:.9}}>
        <button onClick={()=>{ setMlSent(false); if(mlErr)setMlErr(''); onRetry&&onRetry(); setMlOpen(o=>!o) }} title="Entrar con tu correo" aria-label="Entrar con tu correo" style={{background:'none',border:'none',cursor:'pointer',padding:7,lineHeight:0}}>
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={mlOpen?GRN:'#C6CCCB'} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="5" width="18" height="14" rx="2.5"/><path d="m3.5 7.5 8.5 6 8.5-6"/></svg>
        </button>
        <button onClick={()=>{ try{ window.location.href='/?demo=1' }catch(_){}}} title="Ver demo" aria-label="Ver demo" style={{background:'none',border:'none',cursor:'pointer',padding:7,lineHeight:0}}>
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#C6CCCB" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><polygon points="6 4 20 12 6 20 6 4"/></svg>
        </button>
      </div>
      {mlOpen && !mlSent && <div style={{marginTop:16,display:'flex',flexDirection:'column',gap:8,width:sm?250:270}}>
        <input type="email" autoFocus value={mlEmail} onChange={e=>{setMlEmail(e.target.value); if(mlErr)setMlErr('')}} onKeyDown={e=>{if(e.key==='Enter')enviarLink()}} placeholder="nombre@tuestudio.cl" autoComplete="email" style={{border:'1px solid #DADFDE',borderRadius:10,padding:'11px 13px',fontSize:14,color:INK,outline:'none',boxSizing:'border-box',textAlign:'center'}}/>
        <button onClick={enviarLink} disabled={mlBusy} style={{background:INK,color:'#fff',border:'none',borderRadius:10,padding:'11px',fontSize:13.5,fontWeight:600,cursor:mlBusy?'default':'pointer'}}>{mlBusy?'Enviando…':'Enviar enlace'}</button>
        {mlErr&&<div style={{fontSize:12,color:'#C0362C',textAlign:'center'}}>{mlErr}</div>}
      </div>}
      {mlSent && <div style={{marginTop:16,maxWidth:280,textAlign:'center',fontSize:13,color:GRN,lineHeight:1.5}}>Te enviamos un enlace a <b style={{color:INK}}>{mlEmail.trim()}</b>. Ábrelo desde este dispositivo.</div>}
    </div>
  )
}

