// ─── CLIENTS VIEW LIMITED ──────────────────────────────────────────────────
// Recuadros de filtro de estado de clientes (Activos / Terminados / Todos) — compartido admin/limited
function ClientStatusTabs({value,onChange,activeN,endedN,prospectoN}){
  return (
    <div style={{display:'flex',gap:6,marginBottom:4}}>
      {[['Activo',`Activos (${activeN})`],['Prospecto',`Prospectos (${prospectoN})`],['Terminado',`Terminados (${endedN})`],['all','Todos']].map(([v,l])=>(
        <button key={v} onClick={()=>onChange(v)} style={{flex:1,padding:'7px 0',borderRadius:8,border:`1px solid ${value===v?C.accent:C.border}`,background:value===v?C.azulBg:'transparent',color:value===v?C.accent:C.muted,fontSize:11,fontWeight:600,cursor:'pointer'}}>{l}</button>
      ))}
    </div>
  )
}

function ClientsViewLimited({onContactos=null,onCausas=null,openFichaId=null,onOpenedFicha=null,onAsociarTrabajo=null,clients,expenses,tasks,clientEntities,rendiciones,sales=[],billing=[],anticipos=[],currentUserName,onEdit,onAdd,onAddTask,onQuickTask,onAddGasto,onAddFondo,onAddSale,onAddBilling,onEditBilling,onNuevoAnticipo,onConciliar,onOpenSale,onAjuste,onAssignSeries,onStatusChange,onEditTask,onEditExpense,onSaveFields,onImportDrive,setExpenses,setRendiciones,setBilling,user,onRendicionComplete}) {
  const [q,setQ] = useState('')
  const [rendicionClient,setRendicionClient] = useState(null), [rendEdit,setRendEdit] = useState(null), [emailRendCV,setEmailRendCV] = useState(null)   // Rendir desde la ficha completa (responsable)
  const [selected,setSelected] = useState(null)
  const isDesktop = useIsDesktop()
  const [confirmEdit,setConfirmEdit] = useState(null)
  const [openRend,setOpenRend] = useState(null)
  const [openEnt,setOpenEnt] = useState(false)   // caja "Razones sociales facturadas", colapsada por defecto
  const [sFilter,setSFilter] = useState('Activo')
  const [ftab,setFtab] = useState('resumen')
  // Salto desde otra vista (tocar el nombre del cliente en Gastos/Tareas): abre su ficha. Los limited ven la ficha sin honorarios (FichaTabs role limited).
  useEffect(()=>{ if(openFichaId){ const c=clients.find(x=>String(x.id)===String(openFichaId)); if(c){ setFtab('resumen'); setSelected(c) } onOpenedFicha&&onOpenedFicha() } },[openFichaId])

  const activeN=clients.filter(c=>!c.is_internal&&(c.status||'Activo')==='Activo').length
  const endedN=clients.filter(c=>!c.is_internal&&c.status==='Terminado').length
  const prospectoN=clients.filter(c=>!c.is_internal&&c.status==='Prospecto').length
  const filtered = clients.filter(c=>{
    if(c.is_internal) return false   // la oficina (Liberona Escala) no es un cliente: los limited no la ven ni sus costos (sueldos/arriendo)
    if(sFilter==='Activo' && (c.status||'Activo')!=='Activo') return false
    if(sFilter==='Terminado' && c.status!=='Terminado') return false
    if(sFilter==='Prospecto' && c.status!=='Prospecto') return false
    if(q.trim() && !_normTxt(c.name).includes(_normTxt(q))) return false
    return true
  }).sort((a,b)=>(a.name||'').localeCompare(b.name||''))


  const Ficha = ({cl}) => {
    // El limited ve la ficha completa (Financiero + Estado de cuenta) solo en los clientes de los que es responsable.
    const esResp = !!currentUserName && (sales||[]).some(s=>s&&String(s.client_id)===String(cl.id))   // sales ya llega filtrado a SUS ventas
    const effTab = (esResp||ftab==='resumen'||ftab==='contacto') ? ftab : 'resumen'
    const clientBilling = (billing||[]).filter(b=>b.client_id===cl.id)
    const clientExpenses = expenses.filter(e=>e.client_id===cl.id).sort((a,b)=>b.date>a.date?1:-1)
    const {fondos,gastos,saldo} = fgCliente(expenses, cl.id)   // fuente única (no duplicar la fórmula de saldo inline)
    const clientTasks = tasks.filter(t=>t.client_id===cl.id&&t.status!=='Terminado')
    const entities = (clientEntities||[]).filter(e=>e.client_id===cl.id)
    const CATS = CAT_COLORS
    const Chev = ({mt=0}) => <span className="lf-chev" aria-hidden="true" style={{fontSize:18,lineHeight:1,flexShrink:0,marginLeft:6,marginTop:mt,fontWeight:400}}><Gl n='chevron'/></span>

    return (
      <div style={{paddingBottom:100}}>
        <div style={{padding:'16px 20px 12px',position:'sticky',top:0,background:C.bgSoft,zIndex:10,borderBottom:'1px solid #E4E8EB'}}>
          <div style={{display:'flex',alignItems:'center',gap:8}}>
            <button onClick={()=>setSelected(null)} style={{background:'none',border:'none',color:C.accent,cursor:'pointer',fontSize:20,padding:'0 4px 0 0'}}><Gl n='chevL'/></button>
            <div style={{flex:1}}>
              <div style={{fontSize:18,fontWeight:700,color:C.text}}>{cl.name}</div>
              <div style={{display:'flex',alignItems:'center',gap:6,flexWrap:'wrap'}}>
                {cl.type&&<span style={{fontSize:11,color:C.muted}}>{cl.type}</span>}
                {cl.abogado_responsable&&(()=>{ const pc=personChip(cl.abogado_responsable); return <span style={{fontSize:11,color:pc.color,fontWeight:700}}>{cl.abogado_responsable}</span> })()}
              </div>
            </div>
            <ActBtn variant='ghost' onClick={()=>onEdit(cl)}>Editar</ActBtn>
          </div>
          <FichaTabs tab={effTab} setTab={setFtab} role={esResp?'admin':'limited'}/>
        </div>

        <div style={{padding:'16px 20px 0',display:effTab==='resumen'?'block':'none'}}>
          {esResp&&<FotoCliente client={cl} sales={sales} billing={billing} expenses={expenses} tasks={tasks} setFtab={setFtab} onRendicion={setRendicionClient?(c=>{setRendEdit(null);setRendicionClient(c)}):undefined} onEditExpense={onEditExpense} onEditBilling={onEditBilling} onEditTask={onEditTask} onAddTask={onAddTask?()=>onAddTask(cl):undefined}/>}

          {entities.length>0&&(
            <div style={{marginBottom:16,padding:'4px 14px',borderRadius:10,background:C.bgSoft,border:'1px solid #E4E8EB'}}>
              <div className="lf-row" onClick={()=>setOpenEnt(o=>!o)} style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8,padding:'8px 0'}}>
                <div style={{display:'flex',alignItems:'center',gap:6,fontSize:10,color:C.muted,textTransform:'uppercase',letterSpacing:.5,fontWeight:600}}>
                  <span aria-hidden="true" style={{display:'inline-block',transform:openEnt?'rotate(90deg)':'none',transition:'transform .12s',fontSize:14,lineHeight:1}}><Gl n='chevron'/></span>
                  Razones sociales facturadas
                </div>
                <span style={{fontSize:9,color:C.muted,fontWeight:700}}>{entities.length}</span>
              </div>
              {openEnt&&entities.map(e=>(
                <div key={e.id} className="lf-row" onClick={()=>setFtab('contacto')} style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8,padding:'6px 0',borderTop:'1px solid #E4E8EB'}}>
                  <div style={{fontSize:12,fontWeight:500,color:C.text,flex:1,minWidth:0,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{rsDisplay(e.name)||'—'}</div>
                  {e.rut&&<Copyable text={e.rut} title='Copiar RUT' style={{fontSize:11,color:C.muted}}>{fmtRutCL(e.rut)}</Copyable>}
                  <Chev/>
                </div>
              ))}
            </div>
          )}

          <div style={{marginBottom:20}}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:8}}>
              <div style={{...SEC_LBL}}>Gastos y Fondos</div>
            </div>
            {(()=>{ const sNeg=saldo<0, sZero=saldo===0
              const bg=sNeg?C.overdueBg:sZero?C.bgWarm:C.greenBg, col=sNeg?C.overdue:sZero?C.grisText:C.greenText, line=sNeg?C.overdue:sZero?C.border:C.normal
              const plus=(onClick,bgc,al)=>(<button onClick={onClick} aria-label={al} style={{width:18,height:18,borderRadius:'50%',background:bgc,border:'none',cursor:'pointer',display:'inline-flex',alignItems:'center',justifyContent:'center',padding:0,flexShrink:0}}><svg width='10' height='10' viewBox='0 0 24 24' fill='none' stroke='#fff' strokeWidth='3.5' strokeLinecap='round'><line x1='12' y1='5' x2='12' y2='19'/><line x1='5' y1='12' x2='19' y2='12'/></svg></button>)
              return (
              <div style={{background:bg,borderRadius:10,padding:'12px 14px',marginBottom:10}}>
                <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',gap:8}}>
                  <div style={{minWidth:0}}>
                    <div style={{...SEC_LBL}}>Saldo{sNeg?' · por reembolsar':saldo>0?' · a favor':''}</div>
                    <div style={{fontSize:21,fontWeight:700,color:col,marginTop:1}}>${saldo.toLocaleString('es-CL')}</div>
                  </div>
                  {saldo>0&&onAddFondo&&<button onClick={()=>onAddFondo(cl,true)} aria-label='Devolver saldo a favor' title='Devolver saldo a favor' style={{flexShrink:0,height:24,padding:'0 11px',borderRadius:8,border:`0.5px solid ${C.normal}`,background:'#fff',color:C.greenText,fontSize:11,fontWeight:600,cursor:'pointer',display:'inline-flex',alignItems:'center',gap:5}}>Devolver<svg width='12' height='12' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='2.5' strokeLinecap='round' strokeLinejoin='round'><line x1='5' y1='12' x2='19' y2='12'/><polyline points='13 6 19 12 13 18'/></svg></button>}
                </div>
                <div style={{display:'flex',gap:18,marginTop:9,paddingTop:9,borderTop:`0.5px solid ${line}`,flexWrap:'wrap'}}>
                  <div style={{display:'flex',alignItems:'center',gap:6}}><span style={{fontSize:11,color:C.muted}}>Fondos</span><span style={{fontSize:12,fontWeight:600,color:C.normal}}>+${fondos.toLocaleString('es-CL')}</span>{plus(()=>onAddFondo(cl),C.normal,'Agregar fondo')}</div>
                  <div style={{display:'flex',alignItems:'center',gap:6}}><span style={{fontSize:11,color:C.muted}}>Gastos</span><span style={{fontSize:12,fontWeight:600,color:C.overdue}}>−${gastos.toLocaleString('es-CL')}</span>{plus(()=>onAddGasto(cl),C.overdue,'Agregar gasto')}</div>
                </div>
              </div>
            )})()}
            {clientExpenses.slice(0,8).map(e=>{
              const isFondo=e.type==='fondo'
              const isDev=isFondo&&((e.amount||0)<0||/^\s*devoluci/i.test(e.concept||''))
              const catBg=CATS[e.category]||CATS['Otro']
              return (
                <div key={e.id} className={onEditExpense?'lf-row':undefined} onClick={onEditExpense?()=>onEditExpense(e):undefined} style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'8px 0',borderBottom:'1px solid #E4E8EB'}}>
                  <div style={{minWidth:0,flex:1,display:'flex',gap:6,alignItems:'center'}}>
                    {!isFondo&&e.category&&<span style={{fontSize:9.5,padding:'2px 8px',borderRadius:20,background:catBg,color:C.muted,fontWeight:700,flexShrink:0,whiteSpace:'nowrap'}}>{e.category}</span>}
                    {isFondo&&<span style={{fontSize:9.5,padding:'2px 8px',borderRadius:20,background:isDev?C.azulBg:C.greenBg,color:isDev?C.azulInfo:C.normal,fontWeight:700,flexShrink:0,whiteSpace:'nowrap'}}>{isDev?'Devolución':'Fondo'}</span>}
                    <span style={{fontSize:12,color:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{e.concept||'—'}</span>
                  </div>
                  <div style={{fontSize:12,fontWeight:600,color:isDev?C.muted:isFondo?C.normal:C.overdue,flexShrink:0,marginLeft:8}}>{isDev?'−$'+Math.abs(e.amount).toLocaleString('es-CL'):(isFondo?'+':'-')+'$'+e.amount.toLocaleString('es-CL')}</div>
                  {onEditExpense&&<Chev/>}
                </div>
              )
            })}
          </div>

          {(()=>{
            const rends=(rendiciones||[]).filter(r=>r.client_id===cl.id&&r.tipo==='cliente').sort((a,b)=>b.created_at>a.created_at?1:-1)
            if(!rends.length) return null
            return (
              <div style={{marginBottom:20}}>
                <div style={{...SEC_LBL,marginBottom:8}}>Rendiciones realizadas</div>
                {rends.map(r=>{
                  const isOpen=openRend===r.id
                  const det=expenses.filter(e=>e.client_render_id===r.id).sort((a,b)=>b.date>a.date?1:-1)
                  return (
                    <div key={r.id} style={{borderBottom:'1px solid #E4E8EB'}}>
                      <div onClick={()=>setOpenRend(isOpen?null:r.id)} style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'8px 0',cursor:'pointer'}}>
                        <div style={{display:'flex',alignItems:'center',gap:10,minWidth:0,flex:1}}>
                          {bigDate(r.created_at)}
                          <div style={{minWidth:0}}>
                          <div style={{fontSize:12,fontWeight:600,color:C.text}}>{r.periodo}</div>
                          <div style={{fontSize:10,color:C.muted}}>{r.n_gastos} gasto{r.n_gastos!==1?'s':''}{r.user_name?` · ${r.user_name}`:''}</div>
                          </div>
                        </div>
                        <div style={{display:'flex',alignItems:'center',gap:8,flexShrink:0}}>
                          <div style={{fontSize:12,fontWeight:700,color:C.overdue}}>-${(r.total||0).toLocaleString('es-CL')}</div>
                          <span style={{fontSize:11,color:C.muted,transform:isOpen?'rotate(180deg)':'none',display:'inline-block',transition:'transform .2s'}}><Gl n='chevD'/></span>
                        </div>
                      </div>
                      {isOpen&&(
                        <div style={{padding:'2px 0 10px 4px'}}>
                          {det.length===0&&<div style={{fontSize:11,color:C.muted,padding:'4px 0'}}>Sin detalle disponible</div>}
                          {det.map(e=>(
                            <div key={e.id} style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'5px 0',borderBottom:'1px solid #E4E8EB'}}>
                              <div style={{minWidth:0,flex:1,display:'flex',gap:6,alignItems:'center'}}>
                                {e.category&&<span style={{fontSize:9.5,padding:'2px 8px',borderRadius:20,background:CATS[e.category]||CATS['Otro'],color:C.muted,fontWeight:700,flexShrink:0,whiteSpace:'nowrap'}}>{e.category}</span>}
                                <span style={{fontSize:12,color:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{e.concept||'—'}</span>
                              </div>
                              <div style={{fontSize:11,color:C.muted,flexShrink:0,marginLeft:8}}>{fmtFechaDMY(e.date)}</div>
                              <div style={{fontSize:12,fontWeight:600,color:C.overdue,flexShrink:0,marginLeft:8}}>-${(e.amount||0).toLocaleString('es-CL')}</div>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  )
                })}
              </div>
            )
          })()}

          <div style={{marginBottom:20}}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:8}}>
              <div style={{fontSize:11,fontWeight:600,color:C.muted,textTransform:'uppercase',letterSpacing:.5}}>Tareas</div>
              <button onClick={()=>onAddTask(cl)} style={chipBtn('soft')}>+ Tarea</button>
            </div>
            {onQuickTask&&<input placeholder='Nueva tarea… (Enter para crear)' onKeyDown={e=>{ const v=e.target.value.trim(); if(e.key==='Enter'&&v){ onQuickTask(cl,v); e.target.value='' } }} style={{width:'100%',height:34,border:`0.5px solid ${C.border}`,borderRadius:8,fontSize:13,padding:'0 11px',boxSizing:'border-box',outline:'none',color:C.text,marginBottom:8}}/>}
            {clientTasks.length===0&&<div style={{fontSize:12,color:C.muted}}>Sin tareas activas</div>}
            {clientTasks.map(t=>(
              <div key={t.id} className={onEditTask?'lf-row':undefined} onClick={onEditTask?()=>onEditTask(t):undefined} style={{display:'flex',alignItems:'center',gap:8,padding:'9px 0',borderBottom:'1px solid #E4E8EB'}}>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontSize:13,color:C.text,fontWeight:500}}>{t.title}</div>
                  {t.due&&<div style={{fontSize:11,color:C.muted,marginTop:2}}>Vence: {fmtFechaDMY(t.due)}</div>}
                </div>
                {onEditTask&&<Chev/>}
              </div>
            ))}
          </div>

        </div>
        {effTab==='contacto'&&<ContactoTab client={cl} entities={entities} onSaveFields={onSaveFields}/>}
        {esResp&&effTab==='financiero'&&<FinancieroTab client={cl} clientBilling={clientBilling} entities={entities} sales={sales} anticipos={(anticipos||[]).filter(a=>a.client_id===cl.id)} billing={billing} onNuevoAnticipo={()=>onNuevoAnticipo&&onNuevoAnticipo(cl)} onSaveFields={onSaveFields} onEditBilling={onEditBilling} onAddBilling={()=>onAddBilling&&onAddBilling(cl)} onConciliar={()=>onConciliar&&onConciliar(cl)} onAssignSeries={onAssignSeries} onStatusChange={onStatusChange}/>}
        {esResp&&effTab==='documentos'&&<EstadoCuentaTab onAsociarTrabajo={onAsociarTrabajo} client={cl} clientBilling={clientBilling} sales={sales} anticipos={(anticipos||[]).filter(a=>a.client_id===cl.id)} expenses={expenses} clientEntities={entities} onEditExpense={onEditExpense} onEditBilling={onEditBilling} onOpenSale={onOpenSale} onAjuste={onAjuste}/>}
      </div>
    )
  }

  const listInner = (<>
      <div style={{padding:'20px 20px 10px',position:'sticky',top:0,background:C.bgSoft,zIndex:10}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:10,flexWrap:'wrap',gap:8}}>
          <div style={{fontSize:20,fontWeight:600,color:C.text,fontFamily:"'DM Sans',sans-serif",letterSpacing:-.4}}>Clientes</div>
          <div style={{display:'flex',gap:8,alignItems:'center'}}>
            {onImportDrive&&<button onClick={onImportDrive} title='Importar desde Drive' style={driveBtn}><DriveIcon size={20}/></button>}
            {onContactos&&<button onClick={onContactos} style={{...chipBtn('soft'),color:C.accent}}>Contactos</button>}
            {onCausas&&<button onClick={onCausas} style={{...chipBtn('soft'),color:C.accent}}>Causas</button>}
            {onAdd&&<button onClick={onAdd} style={chipBtn('primary')}>+ Cliente</button>}
          </div>
        </div>
        <ChipSearch value={q} onChange={e=>setQ(e.target.value)} placeholder='Buscar cliente…' style={{marginBottom:8}}/>
        <ClientStatusTabs value={sFilter} onChange={setSFilter} activeN={activeN} endedN={endedN} prospectoN={prospectoN}/>
      </div>
      <div style={{padding:'4px 20px 100px'}}>
        {filtered.length===0&&<div style={{color:C.muted,textAlign:'center',padding:40}}>Sin clientes</div>}
        {filtered.length>0&&(()=>{
          // Directorio A-Z (mismo patrón que la vista admin): inicial + avatar empresa/persona del color del responsable + índice lateral, sin cifras.
          const norm=s=>(s||'').trim().toUpperCase()
          const letterOf=cl=>{ const ch=norm(cl.name)[0]||'#'; return /[A-ZÑ]/.test(ch)?ch:'#' }
          const byLetter={}; filtered.forEach(cl=>{ const L=letterOf(cl); (byLetter[L]=byLetter[L]||[]).push(cl) })
          const letters=Object.keys(byLetter).sort((a,b)=>a.localeCompare(b,'es'))
          const idFor=L=>'climl-letter-'+(L==='#'?'num':L)
          const card=cl=>{
            const ended=cl.status==='Terminado'
            const resp=cl.abogado_responsable; const pc=resp?personChip(resp):{bg:C.bgWarm,color:C.textSoft}
            const esEmpresa=/\b(spa|s\.?p\.?a|ltda|limitada|s\.?a|sociedad|inversiones|comercial|constructora|consultores|holding|cia|cía|asociados|partners)\b/i.test(cl.name||'')||/empresa|corp|sociedad/i.test(cl.type||'')
            const tareasC=(tasks||[]).filter(t=>t.client_id===cl.id&&t.status!=='Terminado').length
            const rs=rsLabel(cl.id,clients,clientEntities)
            const sub=rs.multi?`${rs.multi} razones sociales`:(rs.name&&rs.name!==cl.name?rsDisplay(rs.name):(cl.type||''))
            return (
              <div key={cl.id} onClick={()=>{setFtab('resumen');setSelected(cl)}} style={{background:'#fff',borderRadius:12,padding:'10px 12px',marginBottom:6,border:`1px solid ${C.border}`,opacity:ended?.55:1,cursor:'pointer',display:'flex',alignItems:'center',gap:11}}>
                <span style={{width:38,height:38,borderRadius:10,background:pc.bg,display:'flex',alignItems:'center',justifyContent:'center',flexShrink:0}}><SIcon n={esEmpresa?'building':'user'} s={18} c={pc.color}/></span>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{...NOMBRE_CLI}}>{cl.name}{tareasC>0&&<span style={{fontSize:9.5,fontWeight:700,color:C.soonText,background:C.soonBg,borderRadius:20,padding:'2px 8px',marginLeft:6,whiteSpace:'nowrap'}}>{tareasC} {tareasC===1?'tarea':'tareas'}</span>}</div>
                  {sub&&<div style={{fontSize:10,color:C.muted,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap',marginTop:1}}>{sub}</div>}
                </div>
                {resp&&<span style={{flexShrink:0,fontSize:11,color:pc.color,fontWeight:700,whiteSpace:'nowrap'}}>{resp}</span>}
                <button onClick={ev=>{ev.stopPropagation();onSaveFields&&onSaveFields(cl.id,{status:ended?'Activo':'Terminado'})}} title={ended?'Reactivar cliente':'Archivar cliente'} style={{flexShrink:0,width:24,height:24,borderRadius:6,border:`0.5px solid ${ended?C.normal:C.border}`,background:'transparent',color:ended?C.greenText:C.done,cursor:'pointer',display:'inline-flex',alignItems:'center',justifyContent:'center',padding:0}}>{ended?<svg width='12' height='12' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='2' strokeLinecap='round' strokeLinejoin='round'><path d='M3 7v6h6'/><path d='M3.5 13a9 9 0 1 0 2.5-6.5L3 9'/></svg>:<svg width='12' height='12' viewBox='0 0 24 24' fill='none' stroke='currentColor' strokeWidth='2' strokeLinecap='round' strokeLinejoin='round'><rect x='3' y='4' width='18' height='4' rx='1'/><path d='M5 8v11a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V8'/><line x1='10' y1='12' x2='14' y2='12'/></svg>}</button>
              </div>
            )
          }
          return (<div style={{display:'flex',gap:8}}>
            <div style={{flex:1,minWidth:0}}>
              {letters.map(L=>(<div key={L} id={idFor(L)}>
                <div style={{fontSize:12,fontWeight:700,color:C.textSoft,margin:'9px 2px 5px'}}>{L}</div>
                {byLetter[L].slice().sort((a,b)=>(a.name||'').localeCompare(b.name||'','es')).map(card)}
              </div>))}
            </div>
            <div style={{display:'flex',flexDirection:'column',alignItems:'center',gap:1,flexShrink:0,position:'sticky',top:70,alignSelf:'flex-start'}}>
              {'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(L=>{ const has=!!byLetter[L]; return <span key={L} onClick={has?()=>{const el=document.getElementById(idFor(L));el&&el.scrollIntoView({behavior:'smooth',block:'start'})}:undefined} style={{fontSize:11,fontWeight:has?700:400,color:has?C.accent:'#CBD5DB',cursor:has?'pointer':'default',lineHeight:1.3,padding:'3px 6px'}}>{L}</span> })}
            </div>
          </div>)
        })()}
      </div>
  </>)
  // Rendición y su correo = PÁGINAS (mismo flujo que la ficha de admin): '‹ cliente' vuelve a la ficha.
  if(rendicionClient&&setExpenses){ const cerrar=()=>{setRendicionClient(null);setRendEdit(null)}
    return <FlujoPagina origen={rendicionClient.name||'Clientes'} titulo={rendEdit?'Editar rendición':'Rendición'} onBack={cerrar} maxW={1180}><RendicionModal client={rendicionClient} expenses={expenses} clientEntities={clientEntities} sales={sales} rendiciones={rendiciones} onClose={cerrar} setExpenses={setExpenses} setRendiciones={setRendiciones} billing={billing} setBilling={setBilling} editRend={rendEdit} onRendicionComplete={onRendicionComplete||((r)=>setRendiciones&&setRendiciones(p=>[r,...p]))} onEnviar={r=>{setRendicionClient(null);setRendEdit(null);setEmailRendCV(r)}} asPage/></FlujoPagina> }
  if(emailRendCV){ const cli=clients.find(c=>String(c.id)===String(emailRendCV.client_id))
    return <FlujoPagina origen={cli?.name||'Clientes'} titulo='Enviar rendición' ctx={emailRendCV.correlativo?`N° ${emailRendCV.correlativo}`:null} onBack={()=>setEmailRendCV(null)} maxW={1180}><RendicionEmailModal asPage r={emailRendCV} client={cli} user={user} expenses={expenses} clientEntities={clientEntities} sales={sales} setExpenses={setExpenses} onSent={(id,at,corr)=>setRendiciones&&setRendiciones(p=>p.map(x=>x.id===id?{...x,sent_at:at,correlativo:corr??x.correlativo}:x))} onPatch={(id,patch)=>setRendiciones&&setRendiciones(p=>p.map(x=>x.id===id?{...x,...patch}:x))} onNext={x=>setEmailRendCV(x)} onClose={()=>setEmailRendCV(null)}/></FlujoPagina> }
  if(isDesktop) return (
    <div style={{display:'grid',gridTemplateColumns:'360px 1fr',height:'calc(100vh - 66px)',borderTop:`1px solid ${C.border}`}}>
      <div style={{overflowY:'auto',borderRight:`1px solid ${C.border}`,background:C.bgSoft}}>{listInner}</div>
      <div style={{overflowY:'auto',background:C.bg}}>{selected
        ? <div style={{maxWidth:760,margin:'0 auto'}}><Ficha cl={selected}/></div>
        : <div style={{height:'100%',display:'flex',alignItems:'center',justifyContent:'center',color:C.textSoft,fontSize:13,textAlign:'center',padding:24}}>Elige un cliente para ver su ficha</div>}</div>
    </div>
  )
  if(selected) return (<div style={{maxWidth:900,margin:'0 auto'}}><Ficha cl={selected}/></div>)
  return (<div style={{maxWidth:900,margin:'0 auto'}}>{listInner}</div>)
}


// ─── NUEVO CLIENTE LIMITED (con anti-duplicado) ───────────────────────────
function NuevoClienteLimitedForm({clients,onSave,onClose,saving}) {
  const [name,setName] = useState('')
  const [type,setType] = useState('Corporativo')
  const [rut,setRut] = useState('')
  const [showConfirm,setShowConfirm] = useState(false)

  const similares = useMemo(()=>{
    if(name.trim().length<3) return []
    const q = name.trim().toLowerCase()
    return clients.filter(c=>
      _normTxt(c.name).includes(_normTxt(q)) ||
      _normTxt(q).split(' ').some(w=>w.length>2&&_normTxt(c.name).includes(w))
    ).slice(0,5)
  },[name,clients])

  const handleGuardar = () => {
    if(!name.trim()) return
    if(similares.length>0 && !showConfirm) { setShowConfirm(true); return }
    onSave({name:name.trim(),type,rut:rut.trim()||null,status:'Activo'})
  }

  return (
    <div>
      <div style={{marginBottom:14}}>
        <div style={{fontSize:10,color:C.muted,textTransform:'uppercase',letterSpacing:.5,fontWeight:600,marginBottom:6}}>Nombre del cliente</div>
        <input value={name} onChange={e=>{setName(e.target.value);setShowConfirm(false)}} placeholder='Nombre completo...' autoFocus
          style={{width:'100%',padding:'10px 12px',borderRadius:8,border:'1px solid #E4E8EB',background:C.bgSoft,fontSize:14,boxSizing:'border-box',outline:'none'}}/>
        {similares.length>0&&(
          <div style={{marginTop:8,padding:'10px 12px',borderRadius:8,background:C.ambarBg,border:'1px solid #C77F18'}}>
            <div style={{fontSize:11,fontWeight:700,color:C.soon,marginBottom:6}}>{'\u26a0\ufe0f'} Clientes similares encontrados:</div>
            {similares.map(s=>(
              <div key={s.id} style={{fontSize:12,color:C.soon,padding:'2px 0'}}>{s.name}{s.type?` · ${s.type}`:''}</div>
            ))}
            <div style={{fontSize:11,color:C.soon,marginTop:6}}>Verifica que no sea un duplicado antes de continuar.</div>
          </div>
        )}
      </div>
      <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:10,marginBottom:14}}>
        <div>
          <div style={{fontSize:10,color:C.muted,textTransform:'uppercase',letterSpacing:.5,fontWeight:600,marginBottom:6}}>Tipo</div>
          <select value={type} onChange={e=>setType(e.target.value)}
            style={{width:'100%',padding:'10px 12px',borderRadius:8,border:'1px solid #E4E8EB',background:C.bgSoft,fontSize:13,boxSizing:'border-box'}}>
            {['Corporativo','Tributario','Laboral','Otro'].map(t=><option key={t} value={t}>{t}</option>)}
          </select>
        </div>
        <div>
          <div style={{fontSize:10,color:C.muted,textTransform:'uppercase',letterSpacing:.5,fontWeight:600,marginBottom:6}}>RUT (opcional)</div>
          <input value={rut} onChange={e=>setRut(e.target.value)} placeholder='12.345.678-9'
            style={{width:'100%',padding:'10px 12px',borderRadius:8,border:'1px solid #E4E8EB',background:C.bgSoft,fontSize:13,boxSizing:'border-box',outline:'none'}}/>
        </div>
      </div>

      {showConfirm&&(
        <div style={{padding:'12px 14px',borderRadius:8,background:C.overdueBg,border:'1px solid #E24B4A',marginBottom:14}}>
          <div style={{fontSize:12,fontWeight:700,color:C.overdue,marginBottom:4}}>{'\u00bf'}Confirmas que este cliente NO es un duplicado?</div>
          <div style={{fontSize:11,color:C.overdue}}>Hay nombres similares. Si es nuevo, confirma para continuar.</div>
        </div>
      )}

      <div style={{display:'flex',gap:8,marginTop:4}}>
        <button onClick={onClose} style={{flex:1,padding:'9px 14px',borderRadius:10,border:'1px solid #E4E8EB',background:'#fff',color:C.muted,fontSize:13,fontWeight:600,cursor:'pointer'}}>Cancelar</button>
        <button disabled={saving||!name.trim()} onClick={handleGuardar}
          style={{flex:2,padding:'9px 14px',borderRadius:10,border:'none',background:showConfirm?C.overdue:C.accent,color:'#fff',fontSize:13,fontWeight:700,cursor:'pointer',opacity:(!name.trim())?.6:1}}>
          {saving?'Guardando...':(showConfirm?'Sí, crear de todas formas':'Guardar cliente')}
        </button>
      </div>
    </div>
  )
}

// Blindaje general (main.jsx): un error fuera de una pestaña (una página superpuesta, el menú) ya no deja la pantalla en negro.
export class AppErrorBoundary extends Component {
  constructor(p){ super(p); this.state={err:null} }
  static getDerivedStateFromError(err){ return {err} }
  componentDidCatch(err,info){ try{ console.error('App con error:', err, info) }catch(_){} registrarError({origen:'app', err, stack:`${err?.stack||''}\n${info?.componentStack||''}`}) }
  render(){
    if(this.state.err) return (
      <div style={{padding:'24px 18px',maxWidth:460,margin:'80px auto 0',textAlign:'center',fontFamily:'system-ui,sans-serif'}}>
        <div style={{fontSize:15,fontWeight:700,color:C.overdueText,marginBottom:8}}>La app tuvo un problema</div>
        <div style={{fontSize:13,color:C.muted,lineHeight:1.5,marginBottom:18}}>El error quedó registrado. Al recargar vuelves a la app.</div>
        <button onClick={()=>location.reload()} style={{background:C.accent,color:'#fff',border:'none',borderRadius:10,padding:'10px 18px',fontSize:13,fontWeight:600,cursor:'pointer'}}>Recargar</button>
      </div>
    )
    return this.props.children
  }
}
// ─── Notificaciones en este dispositivo (Web Push): activar, probar y desactivar. Avisos internos: tareas y pagos recibidos. ──
// En el iPhone solo funcionan con la app agregada a la pantalla de inicio (Safari › Compartir › Agregar a inicio).
const _b64aBytes = b64 => { const p='='.repeat((4-b64.length%4)%4); const raw=atob((b64+p).replace(/-/g,'+').replace(/_/g,'/')); return Uint8Array.from([...raw].map(c=>c.charCodeAt(0))) }
function NotificacionesPagina({user, isAdmin}){
  const soporta = typeof window!=='undefined' && 'serviceWorker' in navigator && 'PushManager' in window && 'Notification' in window
  const ios = typeof navigator!=='undefined' && /iPhone|iPad|iPod/.test(navigator.userAgent||'')
  const instalada = typeof window!=='undefined' && (window.navigator.standalone===true || window.matchMedia?.('(display-mode: standalone)').matches)
  const [estado,setEstado] = useState('cargando')   // cargando | activas | inactivas | bloqueadas | sin-soporte | instalar
  const [msg,setMsg] = useState(null)               // {tipo:'ok'|'error', texto}
  const [trabajando,setTrabajando] = useState(false)
  const [tiposOff,setTiposOff] = useState([])   // tipos de aviso apagados en este dispositivo (push_suscripciones.tipos_off)
  const [endpoint,setEndpoint] = useState(null)
  const leerEstado = useCallback(async()=>{
    if(DEMO){ setEstado('inactivas'); return }
    if(ios && !instalada){ setEstado('instalar'); return }
    if(!soporta){ setEstado('sin-soporte'); return }
    if(Notification.permission==='denied'){ setEstado('bloqueadas'); return }
    try{ const reg=await navigator.serviceWorker.ready; const sub=await reg.pushManager.getSubscription(); setEstado(sub&&Notification.permission==='granted'?'activas':'inactivas')
      if(sub){ setEndpoint(sub.endpoint); const {data}=await supabase.from('push_suscripciones').select('tipos_off').eq('endpoint',sub.endpoint).maybeSingle(); setTiposOff(data?.tipos_off||[]) } }catch(_){ setEstado('inactivas') }
  },[soporta,ios,instalada])
  useEffect(()=>{ leerEstado() },[leerEstado])
  const probar = async()=>{ const {data,error}=await supabase.functions.invoke('push',{body:{action:'probar'}}); if(error||data?.error) throw new Error(data?.error||error.message)
    return data?.enviados||0 }
  const activar = async()=>{ setTrabajando(true); setMsg(null)
    try{
      if(DEMO){ setEstado('activas'); setMsg({tipo:'ok',texto:'Notificación de prueba enviada a este dispositivo.'}); return }
      const perm = await Notification.requestPermission()
      if(perm!=='granted'){ setEstado(perm==='denied'?'bloqueadas':'inactivas'); return }
      const {data,error}=await supabase.functions.invoke('push',{body:{action:'clave'}}); if(error||!data?.clave) throw new Error(data?.error||error?.message||'Sin clave del servidor')
      const reg=await navigator.serviceWorker.ready
      const sub=(await reg.pushManager.getSubscription()) || await reg.pushManager.subscribe({userVisibleOnly:true, applicationServerKey:_b64aBytes(data.clave)})
      const j=sub.toJSON(); setEndpoint(j.endpoint)
      const {error:e2}=await supabase.from('push_suscripciones').upsert({email:user?.email, endpoint:j.endpoint, p256dh:j.keys?.p256dh, auth:j.keys?.auth, dispositivo:String(navigator.userAgent||'').slice(0,200), activo:true},{onConflict:'endpoint'})
      if(e2) throw e2
      setEstado('activas')
      const n=await probar()
      setMsg({tipo:'ok',texto:n?'Notificación de prueba enviada a este dispositivo.':'Activadas. La notificación de prueba no llegó: revisa que el teléfono permita avisos de FirmDesk.'})
    }catch(e){ setMsg({tipo:'error',texto:'No se pudieron activar: '+(e.message||e)}) }
    finally{ setTrabajando(false) }
  }
  const desactivar = async()=>{ setTrabajando(true); setMsg(null)
    try{ if(!DEMO){ const reg=await navigator.serviceWorker.ready; const sub=await reg.pushManager.getSubscription()
        if(sub){ await supabase.from('push_suscripciones').update({activo:false}).eq('endpoint',sub.endpoint); await sub.unsubscribe() } }
      setEstado('inactivas'); setMsg({tipo:'ok',texto:'Desactivadas en este dispositivo.'}) }
    catch(e){ setMsg({tipo:'error',texto:'No se pudieron desactivar: '+(e.message||e)}) }
    finally{ setTrabajando(false) }
  }
  const enviarPrueba = async()=>{ setTrabajando(true); setMsg(null)
    try{ const n=DEMO?1:await probar(); setMsg(n?{tipo:'ok',texto:'Notificación de prueba enviada a este dispositivo.'}:{tipo:'error',texto:'No llegó a ningún dispositivo: vuelve a activarlas.'}) }
    catch(e){ setMsg({tipo:'error',texto:'No se pudo enviar: '+(e.message||e)}) }
    finally{ setTrabajando(false) }
  }
  const CHIP = { activas:['Activadas en este dispositivo',C.greenText,C.greenBg], inactivas:['Desactivadas',C.muted,C.bgSoft], bloqueadas:['Bloqueadas en el navegador',C.overdueText,C.overdueBg],
    'sin-soporte':['No disponibles en este navegador',C.muted,C.bgSoft], instalar:['Falta agregar la app al inicio',C.soonText,C.soonBg], cargando:['Revisando…',C.muted,C.bgSoft] }[estado]
  const btn = (txt,on,principal)=><button onClick={on} disabled={trabajando} style={{height:40,padding:'0 16px',borderRadius:10,border:principal?'none':`1px solid ${C.border}`,background:principal?C.accent:'#fff',color:principal?'#fff':C.accent,fontSize:13,fontWeight:700,cursor:trabajando?'default':'pointer',opacity:trabajando?.6:1}}>{txt}</button>
  // Tipos de aviso (mismos códigos que _shared/push.ts). Cada dispositivo apaga los que no quiere.
  const avisos = [['tareas','Tareas','Asignadas o delegadas a ti, terminadas de las que asignaste y las que vencen hoy.'],['causas','Causas en tabla','Tu causa en la tabla del día y cuando se acerca su turno.'],
    ['fondos','Fondos recibidos','Fondos de tus clientes conciliados desde el banco.'],['notaria','Documentos de la notaría','Escrituras, extractos y cartas de tus clientes.'],
    ['clientes','Remates y Diario Oficial','Remate de la Tesorería o publicación de un cliente tuyo.'],
    ...(isAdmin?[['cajachica','Caja chica','Liquidaciones de caja chica del equipo.'],['pagos','Pagos recibidos','Pagos de clientes conciliados desde el banco.'],['normativa','Normativa del SII','Oficios, circulares y resoluciones nuevas.'],['sistema','Procesos y cartola','Un proceso automático falló o falta la cartola del banco.']]:[])]
  const cambiarTipo = async k=>{ const nv=tiposOff.includes(k)?tiposOff.filter(x=>x!==k):[...tiposOff,k]; setTiposOff(nv)
    if(DEMO||!endpoint) return; const {error}=await supabase.from('push_suscripciones').update({tipos_off:nv}).eq('endpoint',endpoint); if(error){ setTiposOff(tiposOff); setMsg({tipo:'error',texto:'No se pudo guardar: '+error.message}) } }
  return (
    <div style={{display:'flex',flexDirection:'column',gap:12,maxWidth:560}}>
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:'14px 16px',display:'flex',flexDirection:'column',gap:10}}>
        <div style={{display:'flex',alignItems:'center',gap:10,flexWrap:'wrap'}}>
          <span style={{...SEC_LBL,margin:0}}>Este dispositivo</span>
          <span style={{marginLeft:'auto',fontSize:11,fontWeight:700,borderRadius:20,padding:'3px 11px',color:CHIP[1],background:CHIP[2],whiteSpace:'nowrap'}}>{CHIP[0]}</span>
        </div>
        {estado==='instalar'&&<div style={{fontSize:13,color:C.text,lineHeight:1.5}}>En el iPhone los avisos llegan a la app instalada: en Safari toca <b>Compartir</b> › <b>Agregar a inicio</b> y abre FirmDesk desde ese ícono.</div>}
        {estado==='bloqueadas'&&<div style={{fontSize:13,color:C.text,lineHeight:1.5}}>El permiso está bloqueado. Actívalo en los ajustes del navegador o del teléfono para FirmDesk y vuelve a esta página.</div>}
        {estado==='sin-soporte'&&<div style={{fontSize:13,color:C.text,lineHeight:1.5}}>Este navegador no recibe notificaciones. En el computador funcionan en Chrome, Edge o Safari.</div>}
        <div style={{display:'flex',gap:8,flexWrap:'wrap'}}>
          {estado==='inactivas'&&btn('Activar en este dispositivo',activar,true)}
          {estado==='activas'&&btn('Enviar una de prueba',enviarPrueba,true)}
          {estado==='activas'&&btn('Desactivar',desactivar,false)}
        </div>
        {msg&&<div style={{fontSize:12.5,color:msg.tipo==='ok'?C.greenText:C.overdueText}}>{msg.texto}</div>}
      </div>
      <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:'14px 16px'}}>
        <div style={{...SEC_LBL,marginBottom:8}}>Qué avisos llegan</div>
        {avisos.map(([k,t,d],i)=><div key={k} style={{borderTop:i?`1px solid ${C.bgSoft}`:'none',padding:'9px 0',display:'flex',alignItems:'center',gap:12}}>
          <div style={{flex:1,minWidth:0}}><div style={{fontSize:13,fontWeight:700,color:C.accent}}>{t}</div><div style={{fontSize:12,color:C.muted,marginTop:2,lineHeight:1.45}}>{d}</div></div>
          <Switch on={estado==='activas'&&!tiposOff.includes(k)} disabled={estado!=='activas'} onToggle={()=>cambiarTipo(k)}/></div>)}
        <div style={{fontSize:11.5,color:C.muted,marginTop:6}}>De 21:00 a 8:00 no suenan: llegan juntos a las 8:00. Las causas en tabla, al momento.</div>
      </div>
    </div>
  )
}
// Blindaje: si una vista lanza un error de render, mostramos un aviso recuperable en vez de dejar la app en blanco.
class ViewErrorBoundary extends Component {
  constructor(p){ super(p); this.state={err:null} }
  static getDerivedStateFromError(err){ return {err} }
  componentDidCatch(err,info){ try{ console.error('Vista con error:', err, info) }catch(_){} registrarError({origen:'vista', vista:this.props.vista, err, stack:`${err?.stack||''}\n${info?.componentStack||''}`}) }
  render(){
    if(this.state.err) return (
      <div style={{padding:'24px 18px',maxWidth:460,margin:'48px auto 0',textAlign:'center'}}>
        <div style={{fontSize:15,fontWeight:700,color:C.overdueText,marginBottom:8}}>Esta vista tuvo un problema</div>
        <div style={{fontSize:13,color:C.muted,lineHeight:1.5,marginBottom:18}}>Puede ser un dato inesperado en esta sección. El resto de la app funciona normal.</div>
        <button onClick={this.props.onReset} style={{background:C.accent,color:'#fff',border:'none',borderRadius:10,padding:'10px 18px',fontSize:13,fontWeight:600,cursor:'pointer'}}>Ir a Inicio</button>
      </div>
    )
    return this.props.children
  }
}
// SideNav (escritorio): barra lateral fija que reusa TABS_ADMIN/LIMITED + moduloOn. Oculta bajo 1024px por CSS (.sidenav).
// ── NOVEDADES de la app: al entrar, lo nuevo que le sirve a cada persona (tabla `novedades`, por estudio).
// El equipo ve las de su rol; los socios ven todas (las del equipo rotuladas «también al equipo»). «Ya vista» = learnings novedades_vista (key = email, value = ISO).
const NOV_DEMO = [
  {id:'nv1', fecha:'2026-10-20', titulo:'Borradores: ahora se editan y se eliminan', area:'Rendir a cliente › Borradores', roles:['admin','limited'], destino:{tab:'expenses',exp:'rendirCli'}, created_at:'2026-10-20T20:00:00Z'},
  {id:'nv2', fecha:'2026-10-20', titulo:'Cada factura tiene su tipo', area:'Facturación › Por clasificar', roles:['admin'], destino:{tab:'billing'}, created_at:'2026-10-20T19:00:00Z'},
  {id:'nv3', fecha:'2026-10-20', titulo:'Comisión por facturar: se cruza con el SII', area:'Banco', roles:['admin'], destino:{tab:'conciliacion'}, created_at:'2026-10-20T19:00:00Z'},
  {id:'nv4', fecha:'2026-10-19', titulo:'El detalle del gasto se corrige tocándolo', area:'Rendir a cliente', roles:['admin','limited'], destino:{tab:'expenses',exp:'rendir'}, created_at:'2026-10-19T19:00:00Z'},
]
const novedadesDe = (rows, rol) => (rows||[]).filter(n=>n&&n.activo!==false&&(rol==='admin'||(n.roles||[]).includes(rol)))
  .sort((a,b)=>String(b.fecha||'').localeCompare(String(a.fecha||''))||String(b.created_at||'').localeCompare(String(a.created_at||'')))
// Sin registro de vista (primera vez): solo lo de las últimas 2 semanas, nunca el historial completo.
const novedadesNoVistas = (items, vista) => { const desde = vista || new Date(Date.now()-14*86400000).toISOString(); return (items||[]).filter(n=>String(n.created_at||'')>String(desde)) }
function NovedadFila({n, isAdmin, onOpen, compact, first, acciones}){
  const equipo = isAdmin && (n.roles||[]).some(r=>r!=='admin')
  return (<div onClick={()=>onOpen&&onOpen(n)} style={{display:'flex',alignItems:'center',gap:compact?9:12,padding:compact?'11px 12px':'11px 18px',borderTop:first?'none':`1px solid ${C.bgSoft}`,cursor:onOpen?'pointer':'default',minWidth:0}}>
    {diaGrande(n.fecha)}
    <div style={{flex:1,minWidth:0}}>
      <div style={{fontSize:compact?13:13.5,fontWeight:600,color:C.text,lineHeight:1.3}}>{n.titulo}</div>
      <div style={{fontSize:11.5,color:C.muted,marginTop:1,whiteSpace:'nowrap',overflow:'hidden',textOverflow:'ellipsis'}}>{[n.area,equipo?'también al equipo':null].filter(Boolean).join(' · ')}</div>
    </div>
    {acciones||(onOpen&&<span style={{color:C.done,display:'flex',flexShrink:0}}><Gl n='chevron'/></span>)}
  </div>)
}
// Aviso al entrar: panel centrado en escritorio, pantalla completa en el celular. «Entendido» las marca vistas.
// Aviso al entrar: solo el número de novedades no vistas, sin la lista (no tapa la pantalla). «Ver novedades» abre la página
// Novedades y «Continuar» lo cierra; en ambos casos quedan vistas. Mismo aviso centrado en escritorio y celular.
function NovedadesAviso({items, isDesktop, onClose, onVerTodas}){
  const n=items.length
  return createPortal(<div onClick={onClose} style={{position:'fixed',inset:0,background:'rgba(4,36,47,.38)',display:'flex',alignItems:'center',justifyContent:'center',zIndex:300,padding:'0 16px'}}>
    <div onClick={e=>e.stopPropagation()} role='dialog' aria-label='Novedades' style={{width:isDesktop?420:'100%',maxWidth:420,background:C.surface,borderRadius:16,boxShadow:'0 18px 50px rgba(0,30,40,.28)',padding:'20px 20px 16px',display:'flex',flexDirection:'column',gap:14}}>
      <div style={{display:'flex',alignItems:'center',gap:12}}>
        <span style={{width:34,height:34,borderRadius:10,background:C.greenBg,color:C.greenText,display:'flex',alignItems:'center',justifyContent:'center',flexShrink:0}}><Gl n='sparkle'/></span>
        <div style={{flex:1,minWidth:0}}><div style={{fontSize:16,fontWeight:700,color:C.accent}}>Novedades</div><div style={{fontSize:13,color:C.text,marginTop:2}}>{`Hay ${n} novedad${n!==1?'es':''} desde tu última visita.`}</div></div>
      </div>
      <div style={{display:'flex',gap:10,justifyContent:'flex-end'}}>
        <button onClick={onVerTodas} style={{fontSize:13,fontWeight:700,color:C.accent,background:C.surface,border:`1px solid ${C.border}`,borderRadius:10,padding:'9px 18px',cursor:'pointer',minHeight:38}}>Ver novedades</button>
        <button onClick={onClose} style={{fontSize:13,fontWeight:700,color:'#fff',background:C.accent,border:'none',borderRadius:10,padding:'9px 18px',cursor:'pointer',minHeight:38}}>Continuar</button>
      </div>
    </div>
  </div>, document.body)
}
// Menú › Novedades: historial por semana (esta, la anterior) y luego por mes. Los socios pueden editar el texto o quitar una novedad.
function NovedadesView({items, isDesktop, isAdmin, onOpen, onBack, origen, onEditar, onQuitar}){
  const [ed,setEd]=useState(null), [txt,setTxt]=useState('')
  const lun=lunesSemanaISO(), lunAnt=(()=>{ const d=new Date(lun+'T12:00'); d.setDate(d.getDate()-7); return isoLocal(d.getTime()) })()
  const grupoDe=n=>{ const f=String(n.fecha||''); return f>=lun?'Esta semana':f>=lunAnt?'Semana anterior':mesTitulo(f+'T12:00') }
  const grupos=[]; items.forEach(n=>{ const g=grupoDe(n); let x=grupos.find(y=>y.g===g); if(!x){ x={g,ns:[]}; grupos.push(x) } x.ns.push(n) })
  const btn={fontSize:11.5,fontWeight:700,border:`1px solid ${C.border}`,borderRadius:8,padding:'4px 10px',background:C.surface,cursor:'pointer'}
  return (<div style={{padding:isDesktop?'4px 22px 100px':'4px 12px 100px',...(isDesktop?{maxWidth:760,margin:'0 auto'}:{})}}>
    <div style={{display:'flex',alignItems:'center',gap:10,margin:'4px 0 12px'}}><BackBtn onBack={onBack} origen={origen}/><span style={{color:C.done}}>|</span><span style={{fontSize:17,fontWeight:700,color:C.accent}}>Novedades</span></div>
    {!items.length&&<div style={{fontSize:13,color:C.muted,padding:'20px 4px'}}>Aún no hay novedades.</div>}
    {grupos.map(g=>(<div key={g.g} style={{marginBottom:14}}>
      <div style={{...SEC_LBL,margin:'0 2px 6px'}}>{g.g}</div>
      <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:12,overflow:'hidden'}}>
        {g.ns.map((n,i)=> ed===n.id
          ? <div key={n.id} style={{display:'flex',gap:8,alignItems:'center',padding:'10px 12px',borderTop:i?`1px solid ${C.bgSoft}`:'none',flexWrap:'wrap'}}>
              <input value={txt} onChange={e=>setTxt(e.target.value)} onKeyDown={e=>{ if(e.key==='Enter'&&txt.trim()){ onEditar(n,txt.trim()); setEd(null) } if(e.key==='Escape') setEd(null) }} autoFocus style={{flex:'1 1 220px',minWidth:0,fontSize:13,padding:'7px 9px',border:`1px solid ${C.border}`,borderRadius:8}}/>
              <button onClick={()=>{ if(txt.trim()){ onEditar(n,txt.trim()); setEd(null) } }} style={{...btn,background:C.accent,color:'#fff',border:'none'}}>Guardar</button>
              <button onClick={()=>setEd(null)} style={{...btn,color:C.muted}}>Cancelar</button>
            </div>
          : <NovedadFila key={n.id} n={n} isAdmin={isAdmin} onOpen={onOpen} compact={!isDesktop} first={i===0}
              acciones={isAdmin?<span onClick={e=>e.stopPropagation()} style={{display:'flex',gap:6,flexShrink:0}}><button onClick={()=>{ setEd(n.id); setTxt(n.titulo||'') }} style={{...btn,color:C.accent}}>Editar</button><button onClick={()=>onQuitar(n)} style={{...btn,color:C.overdueText}}>Quitar</button></span>:null}/>)}
      </div>
    </div>))}
  </div>)
}

function SideNav({tab,setTab,userRole,onCopiloto,onPalette,onPrioridades,prioActive}){
  const sp = {fill:'none',stroke:'currentColor',strokeWidth:1.8,strokeLinecap:'round',strokeLinejoin:'round'}
  const I = {
    grid:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><rect x="3" y="3" width="7.5" height="7.5" rx="1.5"/><rect x="13.5" y="3" width="7.5" height="7.5" rx="1.5"/><rect x="3" y="13.5" width="7.5" height="7.5" rx="1.5"/><rect x="13.5" y="13.5" width="7.5" height="7.5" rx="1.5"/></svg>,
    trending:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><path d="M3 17l6-6 4 4 8-8"/><path d="M16 7h5v5"/></svg>,
    receipt:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><path d="M5 3v18l2-1.2 2 1.2 2-1.2 2 1.2 2-1.2 2 1.2V3l-2 1.2-2-1.2-2 1.2-2-1.2-2 1.2z"/><line x1="8.5" y1="8.5" x2="15.5" y2="8.5"/><line x1="8.5" y1="12.5" x2="15.5" y2="12.5"/></svg>,
    card:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>,
    idcard:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><rect x="4" y="3" width="16" height="18" rx="2"/><circle cx="12" cy="10" r="2.5"/><path d="M8.5 17a3.5 3.5 0 0 1 7 0"/></svg>,
    coins:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><ellipse cx="12" cy="6.5" rx="7" ry="3"/><path d="M5 6.5v5c0 1.7 3.1 3 7 3s7-1.3 7-3v-5"/><path d="M5 11.5v5c0 1.7 3.1 3 7 3s7-1.3 7-3v-5"/></svg>,
    check:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><path d="M4 12l5 5L20 6"/></svg>,
    folder:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>,
    clock:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><circle cx="12" cy="12" r="9"/><path d="M12 7.5V12l3 2"/></svg>,
    building:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><path d="M3 21h18"/><path d="M5 21V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v16"/><path d="M9 7h1M14 7h1M9 11h1M14 11h1M9 15h1M14 15h1"/></svg>,
    bank:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><line x1="3" y1="21" x2="21" y2="21"/><line x1="3" y1="10" x2="21" y2="10"/><polyline points="5 6 12 3 19 6"/><line x1="4" y1="10" x2="4" y2="21"/><line x1="20" y1="10" x2="20" y2="21"/><line x1="8" y1="14" x2="8" y2="17"/><line x1="12" y1="14" x2="12" y2="17"/><line x1="16" y1="14" x2="16" y2="17"/></svg>,
    chart:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><path d="M3 3v18h18"/><rect x="7" y="10" width="3" height="8"/><rect x="12" y="6" width="3" height="12"/><rect x="17" y="13" width="3" height="5"/></svg>,
    send:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg>,
    pct:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><line x1="19" y1="5" x2="5" y2="19"/><circle cx="6.5" cy="6.5" r="2.5"/><circle cx="17.5" cy="17.5" r="2.5"/></svg>,
    tag:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><path d="M20.6 13.4 12 22l-9-9V4h9z"/><circle cx="7.5" cy="7.5" r="1.2" fill="currentColor" stroke="none"/></svg>,
    alert:<svg width="18" height="18" viewBox="0 0 24 24" {...sp}><path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/><line x1="12" y1="9" x2="12" y2="13.5"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>,
  }
  const secciones = userRole==='admin'
    ? [ {cap:null, items:[
          {id:'dashboard',label:'Inicio',ic:'grid',mod:'nucleo'},
          {id:'sales',label:'Ventas',ic:'trending',mod:'finanzas'},
          {id:'billing',label:'Facturación',ic:'receipt',mod:'finanzas'},
          {id:'expenses',label:'Gastos',ic:'card',mod:'gastos'},
          {id:'clients',label:'Clientes',ic:'idcard',mod:'nucleo'},
          {id:'tasks',label:'Tareas',ic:'check',mod:'nucleo'},
        ]},
        {cap:'Finanzas', items:[
          {id:'conciliacion',label:'Banco',ic:'bank',mod:'finanzas'},
          {id:'proveedores',label:'Comisiones',ic:'pct',mod:'finanzas'},
          {id:'presupuestoOficina',label:'Oficina',ic:'building',mod:'finanzas'},
          {id:'cobranza',label:'Cobranza',ic:'send',mod:'finanzas'},
          {id:'horas',label:'Horas',ic:'clock',mod:'horas'},
          {id:'inteligencia',label:'Inteligencia',ic:'chart',mod:'nucleo'},
        ]} ]
    : [ {cap:null, items:(TABS_LIMITED.map(t=>({id:t.id,label:t.label,ic:t.icon,mod:t.mod})))} ]
  const item = t => moduloOn(t.mod) && (()=>{ const act = t.active||tab===t.id; return (
    <button key={t.id} onClick={t.onClick||(()=>setTab(t.id))} style={{display:'flex',alignItems:'center',gap:11,padding:'8px 11px',borderRadius:8,border:'none',background:act?'rgba(255,255,255,.12)':'transparent',color:act?'#fff':'#a8c2ca',fontSize:13,fontWeight:act?700:500,cursor:'pointer',width:'100%',textAlign:'left',fontFamily:'inherit'}}>
      <span style={{display:'flex',flexShrink:0,opacity:act?1:.85}}>{I[t.ic]||I.grid}</span>{t.label}
    </button>
  )})()
  return (
    <aside className='sidenav' style={{position:'fixed',left:0,top:0,bottom:0,width:212,background:'#04242F',padding:'16px 12px',display:'none',flexDirection:'column',gap:2,zIndex:40,overflowY:'auto'}}>
      <div style={{padding:'4px 8px 16px',display:'flex',justifyContent:'center'}}>
        {/* Logo real del estudio (blanco sobre el sidebar oscuro); si el estudio no tiene logo cargado, cae al monograma. La atribución 'con tecnología FirmDesk' se movió al pie. */}
        {BRAND?.logo?.blanco
          ? <img src={BRAND.logo.blanco} alt={BRAND?.nombre||'FirmDesk'} style={{height:22,width:'auto',maxWidth:'100%',objectFit:'contain',objectPosition:'center',display:'block'}}/>
          : <div style={{display:'flex',alignItems:'center',gap:9}}><span style={{width:26,height:26,borderRadius:8,background:'#12A150',display:'flex',alignItems:'center',justifyContent:'center',color:'#fff',fontWeight:800,fontSize:13}}>{(BRAND?.nombre||'L')[0]}</span><span style={{fontSize:14,fontWeight:800,color:'#fff',letterSpacing:-.2,lineHeight:1.15}}>{BRAND?.nombre||'FirmDesk'}</span></div>}
      </div>
      {secciones.map((s,i)=>(<div key={i} style={{display:'flex',flexDirection:'column',gap:1}}>
        {s.cap&&<div style={{fontSize:9,fontWeight:800,textTransform:'uppercase',letterSpacing:'.06em',color:'#5a808c',margin:'12px 10px 4px'}}>{s.cap}</div>}
        {s.items.map(item)}
      </div>))}
      <div style={{marginTop:'auto',display:'flex',flexDirection:'column',gap:7,paddingTop:10}}>
        {/* Copiloto: la IA del estudio → protagonista al pie (full-width, destacado). Buscar queda secundario. */}
        <button onClick={onCopiloto} title='Counsel AI' style={{display:'flex',alignItems:'center',justifyContent:'center',gap:7,padding:'10px',borderRadius:10,border:'1px solid rgba(159,225,203,.35)',background:'rgba(159,225,203,.12)',color:'#fff',fontSize:13,fontWeight:700,cursor:'pointer',fontFamily:'inherit'}}><svg width="16" height="16" viewBox="0 0 24 24" fill="#9FE1CB"><path d="M12 2l1.6 5.2L19 9l-5.4 1.8L12 16l-1.6-5.2L5 9l5.4-1.8z"/></svg>Counsel AI</button>
        <button onClick={onPalette} title='Buscar (⌘K)' style={{display:'flex',alignItems:'center',justifyContent:'center',gap:6,padding:'7px',borderRadius:8,border:'1px solid rgba(255,255,255,.14)',background:'transparent',color:'#a8c2ca',fontSize:12,cursor:'pointer',fontFamily:'inherit'}}><svg width="13" height="13" viewBox="0 0 24 24" {...sp}><circle cx="11" cy="11" r="7"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>Buscar</button>
        <div style={{textAlign:'center',fontSize:8,fontWeight:600,color:'#6f9aa6',letterSpacing:.3,paddingTop:5}}>con tecnología FirmDesk</div>
      </div>
    </aside>
  )
}

