function parseInvoice(raw) {
  // pdfjs entrega texto plano sin saltos reales
  const t = raw.replace(/\r?\n/g,' ').replace(/\s{2,}/g,' ')
  // DEBUG temporal: ver el texto real extraido
  // Folio
  const folioM = t.match(/N[\xba\xb0o]?\s*(\d{3,7})/)
  const folio = folioM ? folioM[1] : null

  // Receptor
  const receptorM = t.match(/SE[N\u00d1]OR(?:\(ES\))?:?\s*(.+?)\s*R\.?U\.?T\.?:/)
  const cliente = receptorM ? receptorM[1].trim() : null

  // RUT receptor
  const rutZone = t.match(/SE[N\u00d1]OR(?:\(ES\))?:?.+?R\.?U\.?T\.?:?\s*([\d\.]{7,11}\s*[-\u2013]\s*[\dkK])/)
  const rut = rutZone ? rutZone[1].replace(/\s/g,'') : null

  // Fecha
  let issued_at = null
  const fechaM = t.match(/(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)\s+de[l]?\s+(\d{4})/i)
  if(fechaM) {
    const dia = parseInt(fechaM[1])
    const mes = MESES[fechaM[2].toLowerCase()]
    const anio = parseInt(fechaM[3])
    if(mes) issued_at = `${anio}-${String(mes).padStart(2,'0')}-${String(dia).padStart(2,'0')}`
  }

  // Glosa
  let concepto = null
  const gM = t.match(/Valor\s*[-\u2013]\s*(.+?)\s+1\s+[\d][\d\.]{3,}/)
  if(gM) concepto = gM[1].replace(/\s+/g,' ').trim()
  if(!concepto){const gM2 = t.match(/[-\u2013]\s+([A-Za-z\u00c0-\u00ff].{8,90}?)\s+1\s+[\d][\d\.]{3,}/);if(gM2) concepto = gM2[1].replace(/\s+/g,' ').trim()}

  // Total
  const totalM = t.match(/TOTAL\s*\$?\s*([\d\.]{4,12})/)
  const total = totalM ? parseInt(totalM[1].replace(/\./g,'')) : null

  return { folio, cliente, rut, issued_at, concepto, total }
}
const CLIENTES_ROOT='19JsFeh9icekmXMKyubkbLxfXVujmc3eh'
const CLIENTES_TERMINADOS_ROOT='1_wi0td0ib9QlBLjUvDkr6QzdLn1sPwGX'
// Tras emitir un DTE: reusa el PDF ya definido (facturaDtePdfBase64, con logo+timbre) y la carpeta de facturación de
// Drive (folders.facturas) — mismo camino que procesarRespaldoSII — para subir PDF + XML y adjuntarlos a la factura
// (billing_attachments) → verlos desde Facturación y la ficha. No bloquea la emisión: si Drive no está conectado
// devuelve {sinDrive}. Idempotente por nombre (no re-sube si ya está adjunto).
async function subirFacturaADrive(billId, dteXml){
  try{
    const doc = splitSetDTE(dteXml)[0]; if(!doc) return {ok:false}
    const token = await driveToken(); if(!token) return {ok:false, sinDrive:true}
    const fEmis=(doc.match(/<FchEmis>([^<]+)<\/FchEmis>/)||[])[1]||''
    const carpeta = await driveCarpetaFacturacion(token, fEmis)   // Facturación → Año → Mes de emisión
    const r = await facturaDtePdfBase64(doc)
    const rs = String(r.rznR||'').replace(/[\/\\:*?"<>|]/g,'').slice(0,45)
    const baseName = 'Factura '+r.folio+(rs?' - '+rs:'')
    const { data:ex } = await supabase.from('billing_attachments').select('id,name').eq('billing_id',billId)
    const has = n => (ex||[]).some(a=>a.name===n)
    const rows=[]
    const adjuntar = async(file, name)=>{
      if(has(name)) return
      const up = await driveUpload(token, carpeta, file, name)
      const { data:ins } = await supabase.from('billing_attachments').insert({ billing_id:billId, drive_file_id:up.id, name:up.name||name, url:up.webViewLink||null, uploaded_by:'Emisión SII' }).select('id,billing_id').single()
      if(ins) rows.push(ins)
    }
    const bin=atob(r.base64); const u8=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) u8[i]=bin.charCodeAt(i)
    await adjuntar(new File([u8], baseName+'.pdf', {type:'application/pdf'}), baseName+'.pdf')
    await adjuntar(new File([dteXml], baseName+'.xml', {type:'application/xml'}), baseName+'.xml')
    return {ok:rows.length>0, rows}
  }catch(e){ return {ok:false, err:e.message} }
}
function ClienteDriveImporter({clients,onImported,onClose,onChanged}){
  const [step,setStep]=useState('loading')
  const [token,setToken]=useState(null)
  const [newClients,setNewClients]=useState([])
  const [terminados2024,setTerminados2024]=useState([])
  const [terminados2025,setTerminados2025]=useState([])
  const [selected,setSelected]=useState({})
  const [saving,setSaving]=useState(false)
  const [log,setLog]=useState([])
  const addLog=msg=>setLog(p=>[...p,msg])
  // Sincronización automática (cron / al abrir) de incorporación de clientes nuevos desde Drive.
  const [autoOn,setAutoOn]=useState(false)
  const [syncing,setSyncing]=useState(false)
  const [syncMsg,setSyncMsg]=useState(null)
  const [lastSync,setLastSync]=useState(null)

  useEffect(()=>{init();cargarSync()},[])

  async function cargarSync(){
    if(DEMO){ setLastSync({at:new Date().toISOString(),addedN:2}); setAutoOn(false); return }
    try{ const {data:cfg}=await supabase.from('learnings').select('value').eq('kind','config').eq('key','clientes_drive_sync').order('updated_at',{ascending:false}).limit(1).maybeSingle(); setAutoOn((cfg?.value||'off').trim()==='on') }catch(_){}
    try{ const {data:ls}=await supabase.from('learnings').select('value').eq('kind','config').eq('key','clientes_drive_sync_last').order('updated_at',{ascending:false}).limit(1).maybeSingle(); if(ls?.value) setLastSync(JSON.parse(ls.value)) }catch(_){}
  }
  const syncNow=async()=>{
    setSyncing(true); setSyncMsg(null)
    if(DEMO){ await new Promise(r=>setTimeout(r,700)); setSyncMsg('Demo: +2 nuevos incorporados, 3 archivados.'); setSyncing(false); return }
    try{
      // 1) Previa (dryRun): NO escribe. Muestra qué incorporaría y qué archivaría → corrida supervisada.
      const {data:prev,error:pe}=await supabase.functions.invoke('clientes-drive-sync',{body:{dryRun:true}})
      if(pe) throw pe
      if(prev?.error) throw new Error(prev.error)
      const addN=prev.wouldAddN||0, termN=prev.wouldTerminateN||0, revN=prev.needsReviewN||0
      if(!addN && !termN && !revN){ setSyncMsg('Todo al día: no hay nada nuevo que incorporar ni archivar.'); setSyncing(false); return }
      const lista=(arr,n)=>{ const a=(arr||[]).slice(0,12); return a.join(', ')+(n>a.length?` y ${n-a.length} más`:'') }
      const partes=[]
      if(addN) partes.push(`Incorporar ${addN} cliente${addN!==1?'s':''} nuevo${addN!==1?'s':''}: ${lista(prev.wouldAdd,addN)}`)
      if(termN) partes.push(`Archivar ${termN} cliente${termN!==1?'s':''} movido${termN!==1?'s':''} a Terminados: ${lista(prev.wouldTerminate,termN)}`)
      // Near-dup: carpetas que se parecen a un cliente ya existente (typo). NO se crean; se resuelven a mano abajo, en la lista de nuevos.
      if(revN){ const rl=(prev.needsReview||[]).slice(0,8).map(r=>`"${r.folder}" ≈ ${r.maybe}`).join('; '); partes.push(`OJO · ${revN} carpeta${revN!==1?'s':''} se parece${revN!==1?'n':''} a un cliente existente y NO se crearán (revísalas abajo): ${rl}${revN>8?'…':''}`) }
      if(!addN && !termN){ setSyncMsg(`Nada que incorporar ni archivar. ${revN} carpeta(s) parecida(s) a un cliente existente quedaron para revisar abajo (no se crean duplicados).`); setSyncing(false); return }
      if(!await appConfirm(`Drive propone:\n\n${partes.join('\n\n')}\n\n¿Confirmar los cambios? Es reversible.`)){ setSyncMsg('Cancelado — no se cambió nada.'); setSyncing(false); return }
      // 2) Aplicar de verdad.
      const {data,error}=await supabase.functions.invoke('clientes-drive-sync',{body:{}})
      if(error) throw error
      if(data?.error) throw new Error(data.error)
      setSyncMsg(`Listo: ${data.addedN||0} nuevo(s) incorporado(s), ${data.terminatedN||0} archivado(s).`+((data.needsReviewN||0)?` ${data.needsReviewN} parecida(s) a un cliente existente NO se crearon — revísalas abajo.`:''))
      await cargarSync(); await init(); onChanged&&onChanged()
    }catch(e){ setSyncMsg('Error al sincronizar: '+(e.message||e)) }
    setSyncing(false)
  }
  const toggleAuto=async()=>{
    const nv=!autoOn; setAutoOn(nv)
    if(DEMO) return
    try{ await setLearningKV('config','clientes_drive_sync',nv?'on':'off') }catch(_){ setAutoOn(!nv) }
  }
  // Compuerta fuzzy: la carpeta se parece a un cliente existente → vincular (aprende alias, no crea) o marcar como nuevo.
  const vincularFolder = async (f) => {
    if(!f._maybe) return
    try{ await supabase.from('learnings').insert({kind:'cliente_folder',key:nrmCliente(f.name),value:f._maybe.id}) }catch(e){registrarError({origen:'accion',vista:'learnings',err:e})}
    setNewClients(list=>list.filter(x=>x.id!==f.id))
    setSyncMsg(`"${f.name}" vinculada a ${f._maybe.name} — no se crea duplicado. La app lo recuerda.`)
  }
  const marcarNuevo = (f) => setNewClients(list=>list.map(x=>x.id===f.id?{...x,_maybe:null}:x))

  async function init(){
    setStep('loading')
    let t=localStorage.getItem('drive_token')
    if(!t){try{t=await getDriveToken()}catch(e){}}
    if(!t){setStep('notoken');return}
    setToken(t)
    try{
      // Clientes activos
      const resActivos=await driveGet(t,`https://www.googleapis.com/drive/v3/files?q='${CLIENTES_ROOT}'+in+parents+and+mimeType='application/vnd.google-apps.folder'+and+trashed=false&orderBy=name&fields=files(id,name)`)
      // Dedup ROBUSTO = mismo criterio que el edge function clientes-drive-sync: colapsa espacios y quita acentos.
      // (Antes .toLowerCase().trim() dejaba pasar "Fernando  Oliver" vs "Fernando Oliver" y "Survias" vs "Survías" → duplicados.)
      const activos=(resActivos.files||[]).filter(f=>!f.name.startsWith('1. CLIENTES'))
      const existingNames=new Set(clients.map(c=>nrmCliente(c.name)))
      // Alias aprendidos (folder→cliente): no volver a proponer lo que ya vinculaste.
      let aliasSet=new Set()
      try{ const {data:al}=await supabase.from('learnings').select('key').eq('kind','cliente_folder'); aliasSet=new Set((al||[]).map(r=>nrmCliente(r.key))) }catch(_){}
      const noExactos=activos.filter(f=>!existingNames.has(nrmCliente(f.name)) && !aliasSet.has(nrmCliente(f.name)))
      // Fuzzy: si se parece mucho a un cliente existente (typo), marcarlo como POSIBLE duplicado (compuerta), no crear a ciegas.
      const vivos=clients.filter(c=>c.status!=='Terminado')
      const nuevos=noExactos.map(f=>{ let best=null; for(const c of vivos){ const s=simNombre(f.name,c.name); if(s>=0.82 && s<1 && (!best||s>best.ratio)) best={id:c.id,name:c.name,ratio:Math.round(s*100)} } return best?{...f,_maybe:best}:f })
      setNewClients(nuevos)

      // Clientes terminados - buscar subcarpetas 2024 y 2025
      const resTerminados=await driveGet(t,`https://www.googleapis.com/drive/v3/files?q='${CLIENTES_TERMINADOS_ROOT}'+in+parents+and+mimeType='application/vnd.google-apps.folder'+and+trashed=false&orderBy=name&fields=files(id,name)`)
      const yearFolders=resTerminados.files||[]

      for(const yf of yearFolders){
        const resYear=await driveGet(t,`https://www.googleapis.com/drive/v3/files?q='${yf.id}'+in+parents+and+mimeType='application/vnd.google-apps.folder'+and+trashed=false&orderBy=name&fields=files(id,name)`)
        const yearClients=(resYear.files||[]).filter(f=>!existingNames.has(nrmCliente(f.name)))
        if(yf.name.includes('2024')) setTerminados2024(yearClients)
        if(yf.name.includes('2025')) setTerminados2025(yearClients)
      }
      setStep('review')
    }catch(e){setStep('error');addLog('Error: '+e.message)}
  }

  const toggle=(id)=>setSelected(p=>({...p,[id]:!p[id]}))
  const toggleAll=(list)=>{
    const allSelected=list.every(f=>selected[f.id])
    const upd={...selected}
    list.forEach(f=>{upd[f.id]=!allSelected})
    setSelected(upd)
  }

  const saveSelected=async()=>{
    const toImport=[...newClients,...terminados2024,...terminados2025].filter(f=>selected[f.id])
    if(!toImport.length) return
    setSaving(true);setStep('saving')
    let imported=0
    for(const f of toImport){
      const t2024=terminados2024.find(x=>x.id===f.id), t2025=terminados2025.find(x=>x.id===f.id)
      const isTerminado=t2024||t2025
      // El estado va en `status` (la tabla clients NO tiene columna `area`); los terminados quedan con fecha de término del año de su carpeta.
      const payload={name:f.name, status:isTerminado?'Terminado':'Activo'}
      if(isTerminado) payload.ended_at = (t2024?'2024':'2025')+'-12-31'
      const {error}=await supabase.from('clients').insert(payload)
      if(!error){imported++;addLog(`${f.name}`)}
      else addLog(`Error: ${f.name}: ${error.message}`)
    }
    addLog(`─────────────────`)
    addLog(`${imported} clientes importados`)
    setStep('done')
    onImported()
    setSaving(false)
  }

  const allNew=[...newClients,...terminados2024,...terminados2025]
  const selectedCount=allNew.filter(f=>selected[f.id]).length

  return (
    <div>
      {/* Sincronización con Drive: interruptor del cron + corrida manual + última corrida */}
      <div style={{background:C.bgSoft,borderRadius:10,padding:'12px 14px',marginBottom:14}}>
        <div style={{display:'flex',alignItems:'center',gap:10,marginBottom:8}}>
          <div style={{flex:1,minWidth:0}}>
            <div style={{fontSize:13,fontWeight:700,color:C.accent}}>Sincronización automática</div>
            <div style={{fontSize:11,color:C.muted}}>Al abrir la app y cada 2h: incorpora los nuevos y archiva los que mueves a "1. CLIENTES TERMINADOS". Drive manda.</div>
          </div>
          <div onClick={toggleAuto} style={{width:40,height:23,borderRadius:12,background:autoOn?C.normal:C.done,position:'relative',cursor:'pointer',transition:'.15s',flexShrink:0}}>
            <div style={{position:'absolute',top:2,left:autoOn?19:2,width:19,height:19,borderRadius:'50%',background:'#fff',transition:'.15s',boxShadow:'0 1px 2px rgba(0,0,0,.2)'}}/>
          </div>
        </div>
        <div style={{display:'flex',alignItems:'center',gap:10}}>
          <button onClick={syncNow} disabled={syncing} style={{height:24,padding:'0 16px',background:syncing?C.done:C.accent,color:'#fff',border:'none',borderRadius:8,fontSize:13,fontWeight:600,cursor:syncing?'default':'pointer',flexShrink:0}}>{syncing?'Sincronizando…':'Sincronizar ahora'}</button>
          <div style={{flex:1,fontSize:11,color:syncMsg&&syncMsg.startsWith('Error')?C.overdue:C.muted}}>
            {syncMsg ? syncMsg : lastSync ? `Última: ${new Date(lastSync.at).toLocaleString('es-CL',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})} · +${lastSync.addedN||0} nuevos${lastSync.terminatedN?`, ${lastSync.terminatedN} archivados`:''}` : 'Aún no se ha sincronizado.'}
          </div>
        </div>
      </div>
      {step==='loading'&&<div style={{textAlign:'center',padding:20}}><Spin/><p style={{fontSize:13,color:C.muted,marginTop:12}}>Conectando con Drive...</p></div>}
      {step==='notoken'&&<div style={{textAlign:'center',padding:20}}><p style={{fontSize:13,marginBottom:16}}>Necesitas autorizar Drive.</p><button onClick={()=>getDriveToken().then(t=>{setToken(t);init()})} style={{padding:'10px 20px',borderRadius:8,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:600,cursor:'pointer'}}>Autorizar Drive</button></div>}
      {step==='error'&&<div style={{padding:20}}>{log.map((l,i)=><div key={i} style={{fontSize:12,color:C.overdue}}>{l}</div>)}</div>}
      {(step==='review'||step==='saving')&&(
        <div>
          {/* Posibles duplicados (compuerta fuzzy): la carpeta se parece a un cliente que ya existe → vincular o marcar nuevo */}
          {newClients.some(f=>f._maybe)&&(
            <div style={{marginBottom:16}}>
              <div style={{fontSize:12,fontWeight:700,color:C.soonText,textTransform:'uppercase',letterSpacing:.5,marginBottom:8}}>Posibles duplicados ({newClients.filter(f=>f._maybe).length})</div>
              {newClients.filter(f=>f._maybe).map(f=>(
                <div key={f.id} style={{border:`1px solid ${C.soon}`,borderRadius:10,padding:'10px 11px',marginBottom:7,background:C.soonBg}}>
                  <div style={{fontSize:13,fontWeight:700,color:C.soonText}}>{f.name}</div>
                  <div style={{fontSize:11,color:C.text,margin:'3px 0 8px'}}>Se parece a <b>{f._maybe.name}</b> ({f._maybe.ratio}%). ¿Es el mismo cliente?</div>
                  <div style={{display:'flex',gap:7}}>
                    <button onClick={()=>vincularFolder(f)} style={{flex:1,padding:'7px 10px',borderRadius:8,border:'none',background:C.accent,color:'#fff',fontSize:12,fontWeight:700,cursor:'pointer'}}>Es el mismo · vincular</button>
                    <button onClick={()=>marcarNuevo(f)} style={{padding:'7px 12px',borderRadius:8,border:`1px solid ${C.border}`,background:'#fff',color:C.muted,fontSize:12,fontWeight:600,cursor:'pointer'}}>Es nuevo</button>
                  </div>
                </div>
              ))}
            </div>
          )}
          {/* Clientes nuevos (sin parecido, o ya marcados como nuevos) */}
          {newClients.some(f=>!f._maybe)&&(
            <div style={{marginBottom:16}}>
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:8}}>
                <div style={{fontSize:12,fontWeight:700,color:C.accent,textTransform:'uppercase',letterSpacing:.5}}>Clientes nuevos ({newClients.filter(f=>!f._maybe).length})</div>
                <button onClick={()=>toggleAll(newClients.filter(f=>!f._maybe))} style={{fontSize:11,color:C.accent,background:'none',border:'none',cursor:'pointer',fontWeight:600}}>{newClients.filter(f=>!f._maybe).every(f=>selected[f.id])?'Deseleccionar todos':'Seleccionar todos'}</button>
              </div>
              {newClients.filter(f=>!f._maybe).map(f=>(
                <div key={f.id} onClick={()=>toggle(f.id)} style={{display:'flex',alignItems:'center',gap:10,padding:'8px 10px',borderRadius:8,marginBottom:4,background:selected[f.id]?C.azulBg:C.bgSoft,cursor:'pointer',border:`1px solid ${selected[f.id]?C.accent:C.border}`}}>
                  <div style={{width:16,height:16,borderRadius:4,border:`2px solid ${selected[f.id]?C.accent:C.border}`,background:selected[f.id]?C.accent:'transparent',display:'flex',alignItems:'center',justifyContent:'center',flexShrink:0}}>
                    {selected[f.id]&&<span style={{color:'#fff',fontSize:10,fontWeight:700}}><Gl n='tick'/></span>}
                  </div>
                  <span style={{fontSize:13,color:C.text}}>{f.name}</span>
                </div>
              ))}
            </div>
          )}
          {/* Terminados 2024 */}
          {terminados2024.length>0&&(
            <div style={{marginBottom:16}}>
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:8}}>
                <div style={{fontSize:12,fontWeight:700,color:C.muted,textTransform:'uppercase',letterSpacing:.5}}>Terminados 2024 ({terminados2024.length})</div>
                <button onClick={()=>toggleAll(terminados2024)} style={{fontSize:11,color:C.muted,background:'none',border:'none',cursor:'pointer',fontWeight:600}}>{terminados2024.every(f=>selected[f.id])?'Deseleccionar todos':'Seleccionar todos'}</button>
              </div>
              {terminados2024.map(f=>(
                <div key={f.id} onClick={()=>toggle(f.id)} style={{display:'flex',alignItems:'center',gap:10,padding:'8px 10px',borderRadius:8,marginBottom:4,background:selected[f.id]?'#F7F2EC':C.bgSoft,cursor:'pointer',border:`1px solid ${selected[f.id]?C.soon:C.border}`}}>
                  <div style={{width:16,height:16,borderRadius:4,border:`2px solid ${selected[f.id]?C.soon:C.border}`,background:selected[f.id]?C.soon:'transparent',display:'flex',alignItems:'center',justifyContent:'center',flexShrink:0}}>
                    {selected[f.id]&&<span style={{color:'#fff',fontSize:10,fontWeight:700}}><Gl n='tick'/></span>}
                  </div>
                  <span style={{fontSize:13,color:C.text}}>{f.name}</span>
                  <span style={{fontSize:10,color:C.soon,fontWeight:600,marginLeft:'auto'}}>2024</span>
                </div>
              ))}
            </div>
          )}
          {/* Terminados 2025 */}
          {terminados2025.length>0&&(
            <div style={{marginBottom:16}}>
              <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:8}}>
                <div style={{fontSize:12,fontWeight:700,color:C.muted,textTransform:'uppercase',letterSpacing:.5}}>Terminados 2025 ({terminados2025.length})</div>
                <button onClick={()=>toggleAll(terminados2025)} style={{fontSize:11,color:C.muted,background:'none',border:'none',cursor:'pointer',fontWeight:600}}>{terminados2025.every(f=>selected[f.id])?'Deseleccionar todos':'Seleccionar todos'}</button>
              </div>
              {terminados2025.map(f=>(
                <div key={f.id} onClick={()=>toggle(f.id)} style={{display:'flex',alignItems:'center',gap:10,padding:'8px 10px',borderRadius:8,marginBottom:4,background:selected[f.id]?'#F7F2EC':C.bgSoft,cursor:'pointer',border:`1px solid ${selected[f.id]?C.soon:C.border}`}}>
                  <div style={{width:16,height:16,borderRadius:4,border:`2px solid ${selected[f.id]?C.soon:C.border}`,background:selected[f.id]?C.soon:'transparent',display:'flex',alignItems:'center',justifyContent:'center',flexShrink:0}}>
                    {selected[f.id]&&<span style={{color:'#fff',fontSize:10,fontWeight:700}}><Gl n='tick'/></span>}
                  </div>
                  <span style={{fontSize:13,color:C.text}}>{f.name}</span>
                  <span style={{fontSize:10,color:C.soon,fontWeight:600,marginLeft:'auto'}}>2025</span>
                </div>
              ))}
            </div>
          )}
          {newClients.length===0&&terminados2024.length===0&&terminados2025.length===0&&(
            <div style={{textAlign:'center',padding:40,color:C.muted,fontSize:13}}>Todos los clientes de Drive ya están en la app</div>
          )}
          <div style={{display:'flex',gap:8,marginTop:8,position:'sticky',bottom:0,background:C.bg,paddingBottom:8}}>
            <button onClick={onClose} style={{flex:1,padding:'9px 14px',borderRadius:10,border:`1px solid ${C.border}`,background:'transparent',color:C.muted,fontSize:13,fontWeight:600,cursor:'pointer'}}>Cancelar</button>
            <button onClick={saveSelected} disabled={saving||selectedCount===0} style={{flex:2,padding:'9px 14px',borderRadius:10,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:700,cursor:'pointer',opacity:selectedCount===0?.5:1}}>
              {saving?'Importando...':`Importar ${selectedCount} cliente${selectedCount!==1?'s':''}`}
            </button>
          </div>
        </div>
      )}
      {step==='done'&&(
        <div>
          <div style={{background:C.bgSoft,borderRadius:8,padding:'10px 12px',maxHeight:200,overflowY:'auto',fontSize:12,fontFamily:'monospace',color:C.text,lineHeight:1.7,marginBottom:12}}>
            {log.map((l,i)=><div key={i}>{l}</div>)}
          </div>
          <button onClick={onClose} style={{width:'100%',padding:11,borderRadius:10,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:600,cursor:'pointer'}}>Cerrar</button>
        </div>
      )}
    </div>
  )
}

function DriveImporter({clients,billing,onImported,onClose,clientEntities}){
  const [step,setStep]=useState('init')
  const [token,setToken]=useState(null)
  const [years,setYears]=useState([])
  const [months,setMonths]=useState([])
  const [selYear,setSelYear]=useState(null)
  const [unmatched,setUnmatched]=useState([])
  const [assignments,setAssignments]=useState({})
  const [savingA,setSavingA]=useState(false)
  const [log,setLog]=useState([])
  const [progress,setProgress]=useState({done:0,total:0})
  const addLog=msg=>setLog(p=>[...p,msg])
  useEffect(()=>{init()},[])
  async function init(){
    setStep('loading')
    let t=localStorage.getItem('drive_token')
    if(!t){try{t=await getDriveToken()}catch(e){}}
    if(!t){setStep('notoken');return}
    setToken(t)
    try{
      const q0=encodeURIComponent(`'${FACTURACION_ROOT}' in parents and mimeType='application/vnd.google-apps.folder' and trashed=false`)
      const res=await driveGet(t,`https://www.googleapis.com/drive/v3/files?q=${q0}&orderBy=name&fields=files(id,name)`)
      setYears(res.files||[]);setStep('selectMonth')
    }catch(e){setStep('error')}
  }
  async function loadMonths(yearId){
    setSelYear(yearId)
    const res=await driveGet(token,`https://www.googleapis.com/drive/v3/files?q='${yearId}'+in+parents+and+mimeType='application/vnd.google-apps.folder'+and+trashed=false&orderBy=name&fields=files(id,name)`)
    setMonths(res.files||[])
  }
  async function importMonth(monthId,monthName){
    setStep('importing');setLog([`Importando ${monthName}...`])
    const t=token
    const res=await driveGet(t,`https://www.googleapis.com/drive/v3/files?q='${monthId}'+in+parents+and+mimeType='application/pdf'+and+trashed=false&fields=files(id,name)`)
    const pdfs=res.files||[];setProgress({done:0,total:pdfs.length});addLog(`${pdfs.length} PDFs encontrados`)
    const results={imported:0,skipped:0,errors:0,rows:[]}
    for(let i=0;i<pdfs.length;i++){
      const pdf=pdfs[i]
      try{
        const binRes=await fetch(`https://www.googleapis.com/drive/v3/files/${pdf.id}?alt=media`,{headers:{Authorization:`Bearer ${t}`}})
        const arrayBuf=await binRes.arrayBuffer()
        let raw=''
        try{
          const pdfDoc=await (await cargarPdfjs()).getDocument({data:arrayBuf}).promise
          for(let p=1;p<=pdfDoc.numPages;p++){const page=await pdfDoc.getPage(p);const tc=await page.getTextContent();raw+=tc.items.map(i=>i.str).join(' ')+'\n'}
        }catch(e){raw=new TextDecoder('latin1').decode(arrayBuf)}
        const parsed=parseInvoice(raw)
        const exists=billing.some(b=>folioN(b.invoice_no)===folioN(parsed.folio)&&folioN(parsed.folio)!=='')
        if(exists){results.skipped++;addLog(`skip ${pdf.name}`);setProgress(p=>({...p,done:p.done+1}));continue}
        let mc=null
        // 1. Buscar en clientEntities por RUT (aprendizaje previo)
        if(parsed.rut){
          const ce=clientEntities.find(e=>normRut(e.rut)===normRut(parsed.rut))
          if(ce) mc=clients.find(c=>c.id===ce.client_id)
        }
        // 2. Buscar en clientEntities por nombre
        if(!mc&&parsed.cliente){
          const ce=clientEntities.find(e=>e.name?.toLowerCase()===parsed.cliente?.toLowerCase())
          if(ce) mc=clients.find(c=>c.id===ce.client_id)
        }
        // 3. Buscar en clients por rut directo
        if(!mc&&parsed.rut)mc=clients.find(c=>normRut(c.rut)===normRut(parsed.rut))
        // 4. Buscar en clients por nombre
        if(!mc&&parsed.cliente)mc=clients.find(c=>c.name?.toLowerCase()===parsed.cliente?.toLowerCase())
        if(parsed.folio&&parsed.total){
          if(!mc){
            // Sin cliente: guardar en Supabase sin client_id y agregar a review
            try{
              await upsertBilling({client_id:null,concept:parsed.concepto||'Sin descripción',receptor_name:parsed.cliente||null,receptor_rut:parsed.rut||null,amount:parsed.total,status:'Pendiente',invoice_no:parsed.folio,issued_at:parsed.issued_at,due:dueFromIssued(parsed.issued_at),notes:null})
            }catch(e){
              if(!e.message?.includes('duplicate')) addLog(`error guardando ${pdf.name}: ${e.message}`)
            }
            results.unmatched = results.unmatched||[]
            results.unmatched.push({id:parsed.folio,folio:parsed.folio,rut:parsed.rut,cliente:parsed.cliente,amount:parsed.total,issued_at:parsed.issued_at,concepto:parsed.concepto})
            addLog(`Aviso: ${pdf.name} — sin cliente (${parsed.cliente||'?'})`)
          } else {
            // Con cliente: guardar con client_id y aprendizaje
            try{
              await upsertBilling({client_id:mc.id,concept:parsed.concepto||'Sin descripción',receptor_name:parsed.cliente||null,receptor_rut:parsed.rut||null,amount:parsed.total,status:'Pendiente',invoice_no:parsed.folio,issued_at:parsed.issued_at,due:dueFromIssued(parsed.issued_at),notes:null})
              await reconcileProgramada(mc.id, parsed.total, parsed.issued_at)
              if(parsed.rut){
                await supabase.from('client_entities').upsert({client_id:mc.id,rut:parsed.rut,name:parsed.cliente||null},{onConflict:'rut',ignoreDuplicates:true})
              }
            }catch(e){
              if(!e.message?.includes('duplicate')) addLog(`error guardando ${pdf.name}: ${e.message}`)
            }
            results.rows.push({...parsed,clientMatch:mc,fileName:pdf.name});results.imported++
            addLog(`ok ${pdf.name} — ${parsed.cliente||'?'} · $${parsed.total?.toLocaleString('es-CL')||'?'}`)
          }
        }
      }catch(e){results.errors++;addLog(`error ${pdf.name}: ${e.message}`)}
      setProgress(p=>({...p,done:p.done+1}))
    }
    addLog('—————————————————————————')
    addLog(`${results.imported} procesadas · ${results.skipped} ya existian · ${results.errors} errores${results.unmatched?.length?` · ${results.unmatched.length} sin cliente`:''}`)
    if(results.unmatched?.length>0){
      setUnmatched(results.unmatched)
      setStep('review')
    } else {
      setStep('done');onImported(results.rows)
    }
  }
  const saveAssignmentsDrive = async() => {
    if(savingA) return
    setSavingA(true)
    for(const inv of unmatched){
      const clientId = assignments[inv.id]
      if(!clientId) continue
      await supabase.from('billing').update({client_id:clientId}).eq('invoice_no',inv.folio)
      await reconcileProgramada(clientId, inv.amount, inv.issued_at)
      if(inv.rut||inv.cliente) await aprenderRS(clientId, inv.rut||null, inv.cliente||null, clientEntities)   // fuente única: dedup por RUT si hay; por nombre dentro del cliente si no (el upsert con rut:null nunca deduplicaba → creaba duplicados)
    }
    setStep('done');onImported([])
  }

  return (
    <div>
      {step==='loading'&&<div style={{textAlign:'center',padding:20}}><Spin/><p style={{fontSize:13,color:C.muted,marginTop:12}}>Conectando...</p></div>}
      {step==='notoken'&&<div style={{textAlign:'center',padding:20}}><p style={{fontSize:13,marginBottom:16}}>Necesitas autorizar Drive.</p><button onClick={connectDrive} style={{padding:'10px 20px',borderRadius:8,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:600,cursor:'pointer'}}>Autorizar Drive</button></div>}
      {step==='selectMonth'&&(
        <div>
          <p style={{fontSize:13,color:C.muted,marginBottom:12}}>Selecciona año y mes:</p>
          <div style={{display:'flex',gap:8,flexWrap:'wrap',marginBottom:16}}>
            {years.map(y=><button key={y.id} onClick={()=>loadMonths(y.id)} style={{padding:'6px 14px',borderRadius:8,border:`1px solid ${selYear===y.id?C.accent:C.border}`,background:selYear===y.id?C.azulBg:'#fff',color:selYear===y.id?C.accent:C.text,fontSize:13,fontWeight:600,cursor:'pointer'}}>{y.name}</button>)}
          </div>
          {months.length>0&&<div style={{display:'flex',gap:6,flexWrap:'wrap'}}>{months.map(m=><button key={m.id} onClick={()=>importMonth(m.id,m.name)} style={{padding:'6px 14px',borderRadius:8,border:`1px solid ${C.border}`,background:'#fff',color:C.text,fontSize:13,cursor:'pointer'}}>{m.name}</button>)}</div>}
        </div>
      )}
      {step==='review'&&(
        <div>
          <div style={{background:C.bgSoft,borderRadius:8,padding:'10px 12px',maxHeight:120,overflowY:'auto',fontSize:12,fontFamily:'monospace',color:C.text,lineHeight:1.7,marginBottom:14}}>
            {log.map((l,i)=><div key={i}>{l}</div>)}
          </div>
          <div style={{fontSize:13,fontWeight:600,color:C.text,marginBottom:4}}>Asignar clientes</div>
          <div style={{fontSize:11,color:C.muted,marginBottom:12}}>No se asociaron solas. Asígnalas una vez y el RUT queda guardado.</div>
          {unmatched.map(inv=>(
            <InvoiceClientPicker key={inv.id} inv={inv} clients={clients} assigned={clients.find(c=>c.id===assignments[inv.id])} onAssign={clientId=>setAssignments(p=>({...p,[inv.id]:clientId}))}/>
          ))}
          <div style={{display:'flex',gap:8,marginTop:4}}>
            <button onClick={()=>{setStep('done');onImported([])}} style={{flex:1,padding:'9px 14px',borderRadius:10,border:`1px solid ${C.border}`,background:'transparent',color:C.muted,fontSize:13,fontWeight:600,cursor:'pointer'}}>Omitir</button>
            <button onClick={saveAssignmentsDrive} disabled={savingA} style={{flex:2,padding:'9px 14px',borderRadius:10,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:700,cursor:savingA?'default':'pointer',opacity:savingA?.6:1}}>{savingA?'Guardando…':'Guardar asignaciones'}</button>
          </div>
        </div>
      )}
      {(step==='importing'||step==='done')&&(
        <div>
          {step==='importing'&&<div style={{display:'flex',alignItems:'center',gap:8,marginBottom:12}}><Spin/><span style={{fontSize:13,color:C.muted}}>{progress.done}/{progress.total}</span></div>}
          <div style={{background:C.bgSoft,borderRadius:8,padding:'10px 12px',maxHeight:260,overflowY:'auto',fontSize:12,fontFamily:'monospace',color:C.text,lineHeight:1.6}}>
            {log.map((l,i)=><div key={i}>{l}</div>)}
          </div>
          {step==='done'&&<button onClick={onClose} style={{marginTop:14,width:'100%',padding:11,borderRadius:10,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:600,cursor:'pointer'}}>Cerrar</button>}
        </div>
      )}
      {step==='error'&&<div style={{color:C.overdue,fontSize:13,textAlign:'center',padding:20}}>Error al conectar con Drive.</div>}
    </div>
  )
}

// ─── PDF UPLOADER ─────────────────────────────────────────────────────────────
function InvoiceClientPicker({inv,clients,assigned,onAssign}) {
  const [q,setQ] = useState('')
  const matches = useMemo(()=>{
    if(!q.trim()) return []
    return clients.filter(c=>_normTxt(c.name).includes(_normTxt(q))).sort((a,b)=>(a.name||'').localeCompare(b.name||'','es')).slice(0,6)
  },[q,clients])
  return (
    <div style={{background:C.card,borderRadius:10,padding:'12px 14px',marginBottom:8,border:`1px solid ${assigned?C.accent:C.border}`}}>
      <div style={{display:'flex',justifyContent:'space-between',marginBottom:8}}>
        <div>
          <div style={{fontSize:13,fontWeight:600,color:C.text}}>Factura N° {inv.folio}</div>
          <div style={{fontSize:11,color:C.muted}}>{inv.cliente||inv.fileName}{inv.rut?` · RUT: ${fmtRutCL(inv.rut)}`:''}</div>
          {inv.concepto&&<div style={{fontSize:11,color:C.muted,fontStyle:'italic'}}>{inv.concepto}</div>}
        </div>
        <div style={{fontSize:13,fontWeight:600,color:C.text,flexShrink:0,marginLeft:8}}>{fmt(inv.amount)}</div>
      </div>
      {assigned?(
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'8px 12px',borderRadius:8,background:C.azulBg,border:`1px solid ${C.accent}`}}>
          <span style={{fontSize:13,fontWeight:600,color:C.accent}}>{assigned.name}</span>
          <button onClick={()=>{onAssign('');setQ('')}} style={{background:'none',border:'none',color:C.muted,fontSize:12,cursor:'pointer'}}>Cambiar</button>
        </div>
      ):(
        <div style={{position:'relative'}}>
          <input value={q} onChange={e=>setQ(e.target.value)} placeholder='Buscar cliente…'
            style={{width:'100%',padding:'8px 12px',borderRadius:8,border:`1px solid ${C.border}`,background:C.bgSoft,color:C.text,fontSize:13,boxSizing:'border-box',outline:'none'}}/>
          {matches.length>0&&(
            <div style={{position:'absolute',top:'100%',left:0,right:0,background:'#fff',border:`1px solid ${C.border}`,borderRadius:8,boxShadow:'0 4px 16px rgba(0,0,0,.12)',zIndex:100,marginTop:4,maxHeight:200,overflowY:'auto'}}>
              {matches.map(c=>(
                <div key={c.id} onMouseDown={()=>{onAssign(c.id);setQ('')}}
                  style={{padding:'9px 14px',cursor:'pointer',borderBottom:`1px solid ${C.border}`,fontSize:13}}
                  onMouseEnter={e=>e.currentTarget.style.background=C.bgSoft}
                  onMouseLeave={e=>e.currentTarget.style.background='#fff'}>
                  <div style={{fontWeight:500}}>{c.name}</div>
                  {c.rut&&<div style={{fontSize:11,color:C.muted}}>{fmtRutCL(c.rut)}</div>}
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

function PDFUploader({clients,billing,onImported,onClose,onClientsUpdate,clientEntities}) {
  const [step,setStep] = useState('select') // select | processing | review | done
  const [log,setLog] = useState([])
  const [progress,setProgress] = useState({done:0,total:0})
  const [unmatched,setUnmatched] = useState([]) // [{invoiceId, folio, rut, cliente, amount, issued_at, concepto}]
  const [assignments,setAssignments] = useState({}) // {invoiceId: clientId}
  const [savingA,setSavingA] = useState(false)
  const fileRef = useRef(null)
  const addLog = msg => setLog(p=>[...p,msg])

  const readPdfText = (file) => new Promise((resolve)=>{
    const reader = new FileReader()
    reader.onload = async(e)=>{
      try {
        const typedArr = new Uint8Array(e.target.result)
        const pdfDoc = await (await cargarPdfjs()).getDocument({data:typedArr}).promise
        let text = ''
        for(let p=1;p<=pdfDoc.numPages;p++){
          const page = await pdfDoc.getPage(p)
          const tc = await page.getTextContent()
          text += tc.items.map(i=>i.str).join(' ') + '\n'
        }
        resolve(text)
      } catch(err) {
        const r2 = new FileReader()
        r2.onload = e2 => resolve(e2.target.result)
        r2.readAsText(file, 'latin1')
      }
    }
    reader.readAsArrayBuffer(file)
  })

  const processFiles = async(files) => {
    if(!files.length) return
    setStep('processing')
    setLog([`${files.length} archivo${files.length!==1?'s':''} seleccionado${files.length!==1?'s':''}`])
    setProgress({done:0,total:files.length})
    const results = {imported:0,skipped:0,errors:0}
    const pendingReview = []

    for(let i=0;i<files.length;i++){
      const file = files[i]
      try {
        const raw = await readPdfText(file)
        const parsed = parseInvoice(raw)
        // Verificar duplicado en DB directamente (más confiable que el estado en memoria)
        const {data:existing} = await supabase.from('billing').select('id').eq('invoice_no',parsed.folio).maybeSingle()
        if(existing){ results.skipped++; addLog(`Omitido: ${file.name} — ya existe (N° ${parsed.folio})`); setProgress(p=>({...p,done:p.done+1})); continue }

        // Match por RUT: primero en client_entities (aprendizaje previo), luego en clients.rut, luego por nombre
        let matchedClient = null
        if(parsed.rut) {
          const rutClean = parsed.rut.replace(/[.\-\s]/g,'')
          const entity = (clientEntities||[]).find(e=>e.rut&&e.rut.replace(/[.\-\s]/g,'')===rutClean)
          if(entity) matchedClient = clients.find(c=>c.id===entity.client_id)
          if(!matchedClient) matchedClient = clients.find(c=>c.rut&&c.rut.replace(/[.\-\s]/g,'')===rutClean)
        }
        if(!matchedClient&&parsed.cliente) matchedClient = clients.find(c=>c.name?.toLowerCase()===parsed.cliente?.toLowerCase())

        if(parsed.folio&&parsed.total){
          try {
            await upsertBilling({
              client_id: matchedClient?.id||null,
              concept: parsed.concepto||'Sin descripción',
              receptor_name: parsed.cliente||null,
              receptor_rut: parsed.rut||null,
              amount: parsed.total,
              status: 'Pendiente',
              invoice_no: parsed.folio,
              issued_at: parsed.issued_at,
              due: dueFromIssued(parsed.issued_at),
              notes: null,
            })
            if(matchedClient) await reconcileProgramada(matchedClient.id, parsed.total, parsed.issued_at)
            results.imported++
            if(matchedClient){
              addLog(`${file.name} — ${matchedClient.name}${parsed.concepto?' · '+parsed.concepto:''} · ${fmt(parsed.total)}`)
            } else {
              addLog(`Aviso: ${file.name} — ${parsed.cliente||'sin cliente'} · ${fmt(parsed.total)}`)
              if(parsed.folio) pendingReview.push({
                id: parsed.folio,
                folio: parsed.folio,
                rut: parsed.rut,
                cliente: parsed.cliente,
                amount: parsed.total,
                issued_at: parsed.issued_at,
                concepto: parsed.concepto,
                fileName: file.name
              })
            }
          } catch(e){ addLog(`Error: ${file.name} — ${e.message}`) }
        } else {
          addLog(`Aviso: ${file.name} — no se pudo leer (folio: ${parsed.folio||'?'}, monto: ${parsed.total||'?'})`)
        }
      } catch(e){
        results.errors++
        addLog(`Error: ${file.name} — ${e.message}`)
      }
      setProgress(p=>({...p,done:p.done+1}))
    }

    addLog('─────────────────────────')
    addLog(`${results.imported} importadas · ${results.skipped} ya existían · ${results.errors} errores`)

    if(pendingReview.length>0){
      setUnmatched(pendingReview)
      setStep('review')
    } else {
      setStep('done')
      onImported([])
    }
  }

  const saveAssignments = async() => {
    if(savingA) return
    setSavingA(true)
    for(const inv of unmatched){
      const clientId = assignments[inv.id]
      if(!clientId) continue
      // Actualizar el cobro con el cliente
      await supabase.from('billing').update({client_id:clientId}).eq('invoice_no',inv.folio)
      await reconcileProgramada(clientId, inv.amount, inv.issued_at)
      // Guardar en client_entities para match automático futuro
      if(inv.rut){
        await supabase.from('client_entities').upsert({client_id:clientId, rut:inv.rut, name:inv.cliente||null},{onConflict:'rut',ignoreDuplicates:true})
        if(onClientsUpdate) onClientsUpdate()
      }
    }
    setStep('done')
    onImported([])
  }

  return (
    <div>
      {step==='select'&&(
        <div>
          <p style={{fontSize:13,color:C.muted,marginBottom:16,lineHeight:1.5}}>
            Selecciona uno o varios PDFs de facturas. Se importarán automáticamente y se asociarán al cliente por RUT.
          </p>
          <input ref={fileRef} type='file' accept='.pdf,application/pdf' multiple style={{display:'none'}} onChange={e=>processFiles(Array.from(e.target.files))}/>
          <button onClick={()=>fileRef.current?.click()} style={{width:'100%',padding:'14px',borderRadius:10,border:`2px dashed ${C.accent}`,background:C.bgSoft,color:C.accent,fontSize:14,fontWeight:600,cursor:'pointer',marginBottom:8}}>
            ↑ Seleccionar PDFs
          </button>
          <p style={{fontSize:11,color:C.muted,textAlign:'center'}}>Puedes seleccionar múltiples archivos a la vez</p>
        </div>
      )}

      {(step==='processing')&&(
        <div>
          <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:12}}>
            <Spin/>
            <span style={{fontSize:13,color:C.muted}}>{progress.done}/{progress.total} archivos procesados…</span>
          </div>
          <div style={{background:C.bgSoft,borderRadius:8,padding:'10px 12px',maxHeight:200,overflowY:'auto',fontSize:12,fontFamily:'monospace',color:C.text,lineHeight:1.7}}>
            {log.map((l,i)=><div key={i}>{l}</div>)}
          </div>
        </div>
      )}

      {step==='review'&&(
        <div>
          <div style={{background:C.bgSoft,borderRadius:8,padding:'10px 12px',maxHeight:160,overflowY:'auto',fontSize:12,fontFamily:'monospace',color:C.text,lineHeight:1.7,marginBottom:14}}>
            {log.map((l,i)=><div key={i}>{l}</div>)}
          </div>
          <div style={{fontSize:13,fontWeight:600,color:C.text,marginBottom:4}}>Asignar clientes</div>
          <div style={{fontSize:11,color:C.muted,marginBottom:12}}>No se asociaron solas. Asígnalas una vez y el RUT queda guardado.</div>
          {unmatched.map(inv=>(
            <InvoiceClientPicker key={inv.id} inv={inv} clients={clients} assigned={clients.find(c=>c.id===assignments[inv.id])} onAssign={clientId=>setAssignments(p=>({...p,[inv.id]:clientId}))}/>
          ))}
          <div style={{display:'flex',gap:8,marginTop:4}}>
            <button onClick={()=>{setStep('done');onImported([])}} style={{flex:1,padding:'9px 14px',borderRadius:10,border:`1px solid ${C.border}`,background:'transparent',color:C.muted,fontSize:13,fontWeight:600,cursor:'pointer'}}>Omitir</button>
            <button onClick={saveAssignments} disabled={savingA} style={{flex:2,padding:'9px 14px',borderRadius:10,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:700,cursor:savingA?'default':'pointer',opacity:savingA?.6:1}}>{savingA?'Guardando…':'Guardar asignaciones'}</button>
          </div>
        </div>
      )}

      {step==='done'&&(
        <div>
          <div style={{background:C.bgSoft,borderRadius:8,padding:'10px 12px',maxHeight:200,overflowY:'auto',fontSize:12,fontFamily:'monospace',color:C.text,lineHeight:1.7,marginBottom:12}}>
            {log.map((l,i)=><div key={i}>{l}</div>)}
          </div>
          <div style={{display:'flex',gap:8}}>
            <button onClick={()=>{setStep('select');setLog([]);setProgress({done:0,total:0});setUnmatched([]);setAssignments({})}} style={{flex:1,padding:'9px 14px',borderRadius:10,border:`1px solid ${C.border}`,background:'transparent',color:C.muted,fontSize:13,fontWeight:600,cursor:'pointer'}}>Subir más</button>
            <button onClick={onClose} style={{flex:2,padding:'9px 14px',borderRadius:10,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:600,cursor:'pointer'}}>Cerrar</button>
          </div>
        </div>
      )}
    </div>
  )
}


// ─── REPORT BUILDER ──────────────────────────────────────────────────────────
function ReportBuilder({sales,billing,clients,expenses,tasks,terceros=[],onClose}) {
  const {uf:ufHoy} = useUF()
  // Misma fuente de verdad que el Dashboard: ventaUF anualiza recurrentes y convierte CLP→UF.
  const ufRef = ufHoy || sales.find(s=>s.uf_value>0)?.uf_value || UF_FALLBACK
  const esRec = s => esRecurrente(s)
  // Comisiones en UF de la venta — fuente única comisionesVenta (registradas; si no hay, el costo pactado).
  const costoVentaUF = s => { const u=parseFloat(s.uf_value)||ufRef; return u>0 ? comisionesVenta(s,terceros,billing,ufRef).anual/u : 0 }
  const [sections,setSections] = useState({ventas:true,cobranza:true,gastos:true,tareas:false})
  const [period,setPeriod] = useState('month')
  const [selYear,setSelYear] = useState(String(currentYear))
  const [selMonth,setSelMonth] = useState(String(currentMonth))
  const MONTHS=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre']
  // Años normalizados a string (sales.year es número y billing da string → evita el año duplicado en el dropdown)
  const years=[...new Set([...sales.map(s=>s.year?String(s.year):null),...billing.map(b=>b.issued_at?.slice(0,4))].filter(Boolean))].sort((a,b)=>Number(b)-Number(a))
  if(!years.includes(String(currentYear))) years.unshift(String(currentYear))
  const toggle=k=>setSections(p=>({...p,[k]:!p[k]}))
  const getPeriodLabel=()=>period==='year'?`Año ${selYear}`:`${MONTHS[parseInt(selMonth)-1]} ${selYear}`

  const filterByPeriod=(items,dateField)=>items.filter(item=>{
    const d=item[dateField]; if(!d) return false
    if(period==='year') return d.startsWith(selYear)
    return d.startsWith(`${selYear}-${String(selMonth).padStart(2,'0')}`)
  })

  // buildHtml = FUENTE ÚNICA del reporte: la misma página alimenta la vista previa (iframe) y la impresión.
  const buildHtml=()=>{
    const label=getPeriodLabel()
    const now=new Date().toLocaleDateString('es-CL',{day:'2-digit',month:'long',year:'numeric'})
    const A='#003C50', A2='#537281', A3='#99ABB4', A4='#E4E8EB', G='#3D3D3D'
    const fmtN=fmt
    const fmtUFN=fmtUF

    let html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
<title>Reporte LE — ${label}</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700&display=swap');
  *{margin:0;padding:0;box-sizing:border-box}
  body{font-family:'DM Sans',sans-serif;color:${G};background:#fff;font-size:11px}
  @page{size:letter portrait;margin:18mm 18mm 18mm 18mm}
  @media print{
    .no-print{display:none}
    body{-webkit-print-color-adjust:exact;print-color-adjust:exact}
    .page-break{page-break-before:always}
  }
  .header{background:${A};color:#fff;padding:24px 28px;margin-bottom:24px;border-radius:0}
  .header-top{display:flex;justify-content:space-between;align-items:flex-start}
  .firma-name{font-size:20px;font-weight:700;letter-spacing:-.5px;margin-bottom:2px}
  .firma-sub{font-size:10px;opacity:.75;letter-spacing:.5px;text-transform:uppercase}
  .firma-logo{height:34px;width:auto;display:block;margin-bottom:4px}
  .report-title{text-align:right}
  .report-title h1{font-size:16px;font-weight:600;margin-bottom:4px}
  .report-title p{font-size:10px;opacity:.8}
  .firma-sub-url{font-size:10px;opacity:.7;text-transform:lowercase;margin-top:2px}
  .section{margin-bottom:28px}
  .section-title{font-size:13px;font-weight:700;color:${A};text-transform:uppercase;letter-spacing:.8px;border-bottom:2px solid ${A};padding-bottom:6px;margin-bottom:14px}
  .kpi-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:16px}
  .kpi{background:${A4};border-radius:6px;padding:12px 14px}
  .kpi-label{font-size:9px;color:${A2};text-transform:uppercase;letter-spacing:.6px;margin-bottom:4px;font-weight:600}
  .kpi-value{font-size:16px;font-weight:700;color:${A}}
  .kpi-sub{font-size:9px;color:${A2};margin-top:2px}
  .progress-bar{height:8px;background:#F5F7F9;border-radius:4px;overflow:hidden;margin:6px 0 2px}
  .progress-fill{height:100%;background:${A};border-radius:4px}
  table{width:100%;border-collapse:collapse;font-size:10px}
  thead tr{background:${A};color:#fff}
  thead th{padding:7px 10px;text-align:left;font-weight:600;font-size:9px;text-transform:uppercase;letter-spacing:.4px}
  tbody tr:nth-child(even){background:${A4}}
  tbody tr:nth-child(odd){background:#fff}
  tbody td{padding:6px 10px;color:${G};border-bottom:1px solid ${A4}}
  tfoot tr{background:${A4};font-weight:700}
  tfoot td{padding:7px 10px;border-top:2px solid ${A3}}
  .badge{display:inline-block;padding:2px 7px;border-radius:10px;font-size:9px;font-weight:700}
  .badge-pending{background:#E6EEF1;color:${A}}
  .badge-overdue{background:#FCEBEB;color:#E24B4A}
  .badge-paid{background:#E1F5EE;color:#1D9E75}
  .badge-area{background:${A4};color:${A2}}
  .who-section{margin-bottom:16px}
  .who-title{font-size:11px;font-weight:700;color:${A2};text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;padding:4px 0;border-bottom:1px solid ${A4}}
  .footer{margin-top:32px;padding-top:12px;border-top:1px solid ${A4};display:flex;justify-content:space-between;font-size:9px;color:${A3}}
  .print-btn{position:fixed;bottom:24px;right:24px;background:${A};color:#fff;border:none;padding:12px 24px;border-radius:8px;font-size:13px;font-weight:600;cursor:pointer;font-family:'DM Sans',sans-serif;box-shadow:0 4px 16px rgba(0,60,80,.3)}
</style></head><body>`

    // Header
    html+=`<div class="header">
      <div class="header-top">
        <div>
          <img src="data:image/png;base64," alt="${BRAND.nombre}" class="firma-logo"/>
        </div>
        <div class="report-title">
          <h1>Reporte de Gestión</h1>
          <p>${label} · Generado ${now}</p>
          <p class="firma-sub-url">${BRAND.web}</p>
        </div>
      </div>
    </div>`

    // ── VENTAS
    if(sections.ventas){
      const ss=filterByPeriod(sales.filter(s=>s.status!=='Borrador'&&s.status!=='Propuesta'&&s.status!=='Rechazada'&&!esSubarriendo(s)).map(s=>({...s,date:`${s.year}-${String(s.month||1).padStart(2,'0')}-01`})),'date')
      const brutoUF=ss.reduce((a,s)=>a+ventaUF(s,ufRef),0)
      const costoUF=ss.reduce((a,s)=>a+costoVentaUF(s),0)
      const netoUF=brutoUF-costoUF
      // En modo mes la barra compara contra la meta MENSUAL (META_UF/12), no la anual (si no, un mes siempre marca ~8%).
      const metaRef = period==='year' ? META_UF : META_UF/12
      const metaTxt = period==='year' ? `meta anual UF ${META_UF.toLocaleString('es-CL')}` : `meta mensual UF ${Math.round(META_UF/12).toLocaleString('es-CL')}`
      const pct=metaRef>0?Math.min(100,Math.round((netoUF/metaRef)*100)):0
      html+=`<div class="section">
        <div class="section-title">Ventas</div>
        <div class="kpi-grid">
          <div class="kpi"><div class="kpi-label">Bruto</div><div class="kpi-value">${fmtUFN(brutoUF)}</div></div>
          <div class="kpi"><div class="kpi-label">Costo terceros</div><div class="kpi-value" style="color:#E24B4A">${costoUF>0?fmtUFN(costoUF):'—'}</div></div>
          <div class="kpi"><div class="kpi-label">Neto</div><div class="kpi-value" style="color:#1D9E75">${fmtUFN(netoUF)}</div></div>
        </div>
        <div style="margin-bottom:16px;padding:10px 14px;background:${A4};border-radius:6px">
          <div style="display:flex;justify-content:space-between;margin-bottom:4px">
            <span style="font-size:10px;font-weight:600;color:${A}">Avance ${metaTxt}</span>
            <span style="font-size:13px;font-weight:700;color:${A}">${pct}%</span>
          </div>
          <div class="progress-bar"><div class="progress-fill" style="width:${pct}%"></div></div>
        </div>`
      if(ss.length>0){
        html+=`<table><thead><tr><th>Cliente</th><th>Proyecto</th><th>Área</th><th>Estado</th><th style="text-align:right">UF Bruto</th><th style="text-align:right">UF Costo</th><th style="text-align:right">UF Neto</th></tr></thead><tbody>`
        ss.forEach(s=>{
          const c=clients.find(x=>x.id===s.client_id)
          const bru=ventaUF(s,ufRef), cos=costoVentaUF(s), neto=bru-cos
          html+=`<tr><td>${c?.name||'—'}</td><td>${s.title||'—'}</td><td><span class="badge badge-area">${s.area||'—'}</span></td><td>${s.status||'—'}</td><td style="text-align:right">${fmtUFN(bru)}</td><td style="text-align:right;color:#E24B4A">${cos>0?fmtUFN(cos):'—'}</td><td style="text-align:right;color:#1D9E75;font-weight:600">${fmtUFN(neto)}</td></tr>`
        })
        html+=`</tbody><tfoot><tr><td colspan="4">TOTAL</td><td style="text-align:right">${fmtUFN(brutoUF)}</td><td style="text-align:right;color:#E24B4A">${fmtUFN(costoUF)}</td><td style="text-align:right;color:#1D9E75">${fmtUFN(netoUF)}</td></tr></tfoot></table>`
      } else {
        html+=`<p style="color:${A3};font-style:italic;text-align:center;padding:16px">Sin ventas en este período</p>`
      }
      html+=`</div>`
    }

    // ── COBRANZA
    if(sections.cobranza){
      const bb=filterByPeriod(billing,'issued_at').filter(b=>b.billing_type!=='reembolso'&&['Pendiente','Vencido','Pagado'].includes(b.status))
      const pending=bb.filter(b=>b.status==='Pendiente').reduce((a,b)=>a+saldoBill(b),0)   // saldo real (descuenta abonos parciales), no el monto total
      const overdue=bb.filter(b=>b.status==='Vencido').reduce((a,b)=>a+saldoBill(b),0)
      const paid=bb.filter(b=>b.status==='Pagado').reduce((a,b)=>a+montoFactura(b),0)   // autoridad DTE
      html+=`<div class="section${sections.ventas?' page-break':''}">
        <div class="section-title">Cobranza</div>
        <div class="kpi-grid">
          <div class="kpi"><div class="kpi-label">Por cobrar</div><div class="kpi-value">${fmtN(pending)}</div></div>
          <div class="kpi"><div class="kpi-label">Vencido</div><div class="kpi-value" style="color:#E24B4A">${fmtN(overdue)}</div></div>
          <div class="kpi"><div class="kpi-label">Cobrado</div><div class="kpi-value" style="color:#1D9E75">${fmtN(paid)}</div></div>
        </div>`
      if(bb.length>0){
        html+=`<table><thead><tr><th>Cliente</th><th>Concepto</th><th>N° Factura</th><th>Emisión</th><th>Estado</th><th style="text-align:right">Monto</th><th>Antigüedad</th></tr></thead><tbody>`
        bb.sort((a,b)=>(a.status==='Vencido'?0:1)-(b.status==='Vencido'?0:1)).forEach(b=>{
          const c=clients.find(x=>x.id===b.client_id)
          const dias=b.due?Math.round((new Date()-new Date(b.due+'T12:00'))/86400000):null
          const badgeClass=b.status==='Pagado'?'badge-paid':b.status==='Vencido'?'badge-overdue':'badge-pending'
          const diasStr=dias!==null&&dias>0?`${dias}d vencido`:dias!==null&&dias<0?`${Math.abs(dias)}d restantes`:'—'
          html+=`<tr><td>${c?.name||'—'}</td><td style="max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${b.concept||'—'}</td><td style="font-family:monospace">${b.invoice_no||'—'}</td><td>${b.issued_at||'—'}</td><td><span class="badge ${badgeClass}">${b.status}</span></td><td style="text-align:right;font-weight:600">${fmtN(montoFactura(b))}</td><td style="color:${dias>0?C.overdue:A2}">${diasStr}</td></tr>`
        })
        html+=`</tbody><tfoot><tr><td colspan="5">TOTAL</td><td style="text-align:right">${fmtN(pending+overdue+paid)}</td><td></td></tr></tfoot></table>`
      } else {
        html+=`<p style="color:${A3};font-style:italic;text-align:center;padding:16px">Sin cobros en este período</p>`
      }
      html+=`</div>`
    }

    // ── GASTOS (híbrido: movimientos DEL PERÍODO + saldo acumulado a la fecha de fin del período)
    if(sections.gastos){
      const periodEnd = period==='year' ? `${selYear}-12-31` : `${selYear}-${String(selMonth).padStart(2,'0')}-31`
      const inPeriod = d => d && (period==='year' ? d.startsWith(selYear) : d.startsWith(`${selYear}-${String(selMonth).padStart(2,'0')}`))
      const acc={}
      expenses.forEach(e=>{
        if(!acc[e.client_id]) acc[e.client_id]={fMes:0,gMes:0,fAcc:0,gAcc:0}
        const a=acc[e.client_id]
        if(inPeriod(e.date)){ e.type==='fondo'?a.fMes+=(e.amount||0):a.gMes+=(e.amount||0) }
        // saldo a la fecha: movimientos con fecha <= fin del período (sin fecha se incluyen, para no perder plata)
        if(!e.date || e.date<=periodEnd){ e.type==='fondo'?a.fAcc+=(e.amount||0):a.gAcc+=(e.amount||0) }
      })
      // Solo clientes con movimiento EN el período
      const filas=clients.filter(c=>acc[c.id]&&(acc[c.id].fMes||acc[c.id].gMes))
      html+=`<div class="section page-break">
        <div class="section-title">Gastos y Fondos · ${label}</div>
        <table style="margin-bottom:16px"><thead><tr><th>Cliente</th><th style="text-align:right">Fondos (período)</th><th style="text-align:right">Gastos (período)</th><th style="text-align:right">Saldo a la fecha</th></tr></thead><tbody>`
      if(filas.length){
        filas.forEach(c=>{ const a=acc[c.id]; const sal=a.fAcc-a.gAcc
          html+=`<tr><td>${c.name}</td><td style="text-align:right;color:#1D9E75">${fmtN(a.fMes)}</td><td style="text-align:right;color:#E24B4A">${fmtN(a.gMes)}</td><td style="text-align:right;font-weight:700;color:${sal<0?C.overdue:C.normal}">${fmtN(sal)}</td></tr>`
        })
      } else {
        html+=`<tr><td colspan="4" style="color:${A3};font-style:italic;text-align:center;padding:16px">Sin movimientos de gastos en este período</td></tr>`
      }
      html+=`</tbody></table></div>`
    }

    // ── TAREAS
    if(sections.tareas){
      const activeTasks=tasks.filter(t=>t.status==='Activo')
      const WHO=['Cristóbal','Martín','Martina','Erasmo','Rodrigo']
      html+=`<div class="section page-break"><div class="section-title">Tareas Activas</div>`
      WHO.forEach(who=>{
        const mine=activeTasks.filter(t=>isAssignee(t,who)).sort((a,b)=>(daysLeft(a.due)||999)-(daysLeft(b.due)||999))
        if(!mine.length) return
        html+=`<div class="who-section"><div class="who-title">${who} · ${mine.length} tarea${mine.length!==1?'s':''}</div>
        <table><thead><tr><th>Cliente</th><th>Proyecto</th><th>Tarea</th><th>Plazo</th><th>Estado</th></tr></thead><tbody>`
        mine.forEach(t=>{
          const c=clients.find(x=>x.id===t.client_id)
          const u=urgency(t.due,t.status)
          const color=u==='overdue'?C.overdue:u==='urgent'?C.soon:u==='soon'?C.soon:C.normal
          const dias=t.due?daysLeft(t.due):null
          const diasStr=dias!==null?(dias<0?`${Math.abs(dias)}d vencido`:dias===0?'hoy':`${dias}d`):''
          html+=`<tr><td>${c?.name||'—'}</td><td>${t.project||'—'}</td><td>${t.title}</td><td>${t.due||'—'}</td><td style="color:${color};font-weight:600">${diasStr}</td></tr>`
        })
        html+=`</tbody></table></div>`
      })
      html+=`</div>`
    }

    // Footer
    html+=`<div class="footer"><span>${BRAND.nombre} · ${BRAND.web}</span><span>Reporte ${label} · ${now}</span><span>CONFIDENCIAL</span></div>`
    html+=`<button class="print-btn no-print" onclick="window.print()">Imprimir / Guardar PDF</button>`
    html+=`</body></html>`
    return html
  }
  const generatePDF=()=>{
    const html=buildHtml()
    const win=window.open('','_blank')
    win.document.write(html)
    win.document.close()
    setTimeout(()=>win.focus(),300)
    logActividad('reporte.generado',{detalle:{title:`${getPeriodLabel()} · ${Object.entries(sections).filter(([,v])=>v).map(([k])=>k).join(', ')}`}})
  }
  const isDesk=useIsDesktop()

  const anySelected=Object.values(sections).some(Boolean)

  const preview=anySelected?buildHtml():null
  return (
    <div style={isDesk?{display:'flex',alignItems:'flex-start',gap:18}:undefined}>
    <div style={isDesk?{width:360,flexShrink:0}:undefined}>
      <div style={{marginBottom:16}}>
        <Lbl>Período</Lbl>
        <div style={{display:'flex',gap:6,marginBottom:10}}>
          {[['month','Por mes'],['year','Por año']].map(([v,l])=>(
            <button key={v} onClick={()=>setPeriod(v)} style={{flex:1,padding:'8px',borderRadius:8,border:`1px solid ${period===v?C.accent:C.border}`,background:period===v?C.azulBg:'transparent',color:period===v?C.accent:C.muted,fontSize:12,fontWeight:600,cursor:'pointer'}}>{l}</button>
          ))}
        </div>
        <div style={{display:'grid',gridTemplateColumns:period==='month'?'1fr 1fr':'1fr',gap:8}}>
          <select value={selYear} onChange={e=>setSelYear(e.target.value)} style={{padding:'10px 12px',borderRadius:8,border:`1px solid ${C.border}`,background:C.bgSoft,color:C.text,fontSize:13}}>
            {years.map(y=><option key={y} value={y}>{y}</option>)}
          </select>
          {period==='month'&&(
            <select value={selMonth} onChange={e=>setSelMonth(e.target.value)} style={{padding:'10px 12px',borderRadius:8,border:`1px solid ${C.border}`,background:C.bgSoft,color:C.text,fontSize:13}}>
              {MONTHS.map((m,i)=><option key={i+1} value={i+1}>{m}</option>)}
            </select>
          )}
        </div>
      </div>

      <div style={{marginBottom:20}}>
        <Lbl>Secciones a incluir</Lbl>
        {[
          ['ventas','Ventas','Meta, proyectos, bruto/costo/neto'],
          ['cobranza','Cobranza','Facturas, estado y antigüedad'],
          ['gastos','Gastos y Fondos','Saldos por cliente'],
          ['tareas','Tareas activas','Por responsable con urgencia'],
        ].map(([k,label,desc])=>(
          <div key={k} onClick={()=>toggle(k)} style={{display:'flex',gap:12,alignItems:'flex-start',padding:'10px 14px',borderRadius:10,border:`1px solid ${sections[k]?C.accent:C.border}`,background:sections[k]?C.azulBg:'#fff',marginBottom:8,cursor:'pointer'}}>
            <div style={{width:20,height:20,borderRadius:6,border:`2px solid ${sections[k]?C.accent:C.border}`,background:sections[k]?C.accent:'transparent',display:'flex',alignItems:'center',justifyContent:'center',flexShrink:0,marginTop:1}}>
              {sections[k]&&<span style={{color:'#fff',fontSize:11,fontWeight:700}}><Gl n='tick'/></span>}
            </div>
            <div>
              <div style={{fontSize:13,fontWeight:600,color:sections[k]?C.accent:C.text}}>{label}</div>
              <div style={{fontSize:11,color:C.muted,marginTop:2}}>{desc}</div>
            </div>
          </div>
        ))}
      </div>

      {anySelected&&(
        <div style={{background:C.bgSoft,borderRadius:8,padding:'10px 14px',marginBottom:16,fontSize:12,color:C.muted}}>
          {Object.entries(sections).filter(([,v])=>v).length} sección{Object.entries(sections).filter(([,v])=>v).length!==1?'es':''} · {getPeriodLabel()} · Tamaño carta vertical
        </div>
      )}

      <div style={{display:'flex',gap:8}}>
        <button onClick={onClose} style={{flex:1,padding:'9px 14px',borderRadius:10,border:`1px solid ${C.border}`,background:'transparent',color:C.muted,fontSize:13,fontWeight:600,cursor:'pointer'}}>Cancelar</button>
        <button disabled={!anySelected} onClick={generatePDF} style={{flex:2,padding:'9px 14px',borderRadius:10,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:700,cursor:'pointer',opacity:!anySelected?.6:1}}>
          Imprimir / Guardar PDF
        </button>
      </div>
      <div style={{marginTop:12}}><BitacoraLista prefijo='reporte.' titulo='Reportes generados' etiquetas={{'reporte.generado':'Reporte generado'}} limite={8}/></div>
    </div>
    {preview&&<div style={{flex:1,minWidth:0,marginTop:isDesk?0:14}}>
      <div style={{...SEC_LBL,marginBottom:6}}>Vista previa</div>
      <iframe title='Vista previa del reporte' srcDoc={preview} style={{width:'100%',height:isDesk?'calc(100vh - 190px)':520,border:`1px solid ${C.border}`,borderRadius:12,background:'#fff'}}/>
    </div>}
    </div>
  )
}


// ─── TASKS ONLY VIEW (para usuarios limited) ──────────────────────────────────
function printTasks(tasks, clients, filterLabel) {
  const today = new Date().toLocaleDateString('es-CL',{weekday:'long',day:'numeric',month:'long',year:'numeric'})
  const rows = tasks.map(t=>{
    const client = clients.find(c=>c.id===t.client_id)
    const due = t.due ? fmtFechaDMY(t.due) : '—'
    const urgent = t.due && daysLeft(t.due)<0 ? 'color:#E24B4A;font-weight:600' : ''
    return `<tr>
      <td style="padding:8px 10px;border-bottom:1px solid ${C.border};font-size:12px">${t.title}</td>
      <td style="padding:8px 10px;border-bottom:1px solid ${C.border};font-size:11px;color:${C.muted}">${client?.name||'—'}</td>
      <td style="padding:8px 10px;border-bottom:1px solid ${C.border};font-size:11px;color:${C.muted}">${t.project||'—'}</td>
      <td style="padding:8px 10px;border-bottom:1px solid ${C.border};font-size:11px;${urgent}">${due}</td>
      <td style="padding:8px 10px;border-bottom:1px solid ${C.border};font-size:11px;color:${C.muted}">${taskAssignees(t).join(', ')||'—'}</td>
    </tr>`
  }).join('')
  const html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
  <title>Tareas pendientes</title>
  <style>
    @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700&display=swap');
    body{font-family:'DM Sans',Helvetica,Arial,sans-serif;margin:0;padding:24px;color:#3D3D3D}
    h1{font-size:18px;font-weight:700;color:#003C50;margin:0 0 4px}
    .sub{font-size:11px;color:#99ABB4;margin-bottom:20px}
    table{width:100%;border-collapse:collapse}
    thead tr{background:#003C50;color:#fff}
    th{padding:8px 10px;text-align:left;font-size:11px;font-weight:600;letter-spacing:.5px;text-transform:uppercase}
    @media print{body{padding:0}}
  </style></head><body>
  <h1>Tareas pendientes${filterLabel?' — '+filterLabel:''}</h1>
  <div class="sub">${BRAND.nombre} · ${today} · ${tasks.length} tarea${tasks.length!==1?'s':''}</div>
  <table><thead><tr><th>Tarea</th><th>Cliente</th><th>Proyecto</th><th>Vence</th><th>Responsable</th></tr></thead>
  <tbody>${rows}</tbody></table>
  <script>window.onload=()=>{window.print()}<\/script>
  </body></html>`
  const w = window.open('','_blank')
  w.document.write(html)
  w.document.close()
}

// Vista previa de solo lectura de una tarea (se abre al click en una tarjeta)
// Estados de cierre de una tarea (canon color+icono). Completada = verde; el resto avisa que algo quedó pendiente.
const CIERRE_ESTADOS = [
  {id:'Completada', label:'Completada', bg:C.greenBg, fg:C.greenText, bd:C.normal},
  {id:'Parcial',    label:'Avance parcial', bg:C.soonBg, fg:C.soonText, bd:C.soonText},
  {id:'Derivada',   label:'Derivada', bg:C.azulBg, fg:C.accent, bd:C.accent},
  {id:'No se pudo', label:'No se pudo', bg:C.overdueBg, fg:C.overdueText, bd:C.overdueText},
]

// Cierre de tarea con REPORTE obligatorio — solo lo ven los usuarios limited (Martín/Martina).
// Exige el detalle de la gestión + estado; permite adjuntar documentos. El detalle y los adjuntos
// viajan en el correo "Tarea terminada" que le llega a quien asignó la tarea. Se guarda en la tarea.
function CierreTareaModal({task, clients=[], saving, onConfirm, onClose}){
  const [estado,setEstado] = useState(task.completion_status||'Completada')
  const [detalle,setDetalle] = useState(task.completion_note||'')
  const [files,setFiles] = useState([])   // [{name,base64,mime,size}]
  const [err,setErr] = useState('')
  const client = clients.find(c=>c.id===task.client_id)
  const PLACEHOLDER = 'Ej: revisé el borrador, envié observaciones al cliente y quedó para firma el jueves…'
  const addFiles = async (fileList)=>{
    for(const f of Array.from(fileList||[])){
      if(f.size > 8*1024*1024){ setErr(`"${f.name}" supera 8 MB`); continue }
      const base64 = await new Promise(res=>{ const r=new FileReader(); r.onload=()=>res(String(r.result).split(',')[1]||''); r.onerror=()=>res(''); r.readAsDataURL(f) })
      if(base64) setFiles(p=>[...p,{name:f.name, base64, mime:f.type||'application/octet-stream', size:f.size}])
    }
  }
  const guardar = ()=>{
    if(!detalle.trim()){ setErr('Escribe el detalle de la gestión realizada.'); return }
    onConfirm({estado, detalle:detalle.trim(), files})
  }
  return (
    <>
      <div style={{fontSize:13,color:C.muted,marginBottom:14,lineHeight:1.4}}>{task.title}{client?.name?<> · <span style={{color:C.accent,fontWeight:600}}>{client.name}</span></>:null}</div>
      <div style={{...SEC_LBL,marginBottom:6}}>Estado del cierre</div>
      <div style={{display:'flex',flexWrap:'wrap',gap:6,marginBottom:16}}>
        {CIERRE_ESTADOS.map(e=>{ const on=estado===e.id; return (
          <button key={e.id} onClick={()=>setEstado(e.id)} style={{padding:'6px 12px',borderRadius:14,border:`1px solid ${on?e.bd:C.border}`,background:on?e.bg:'transparent',color:on?e.fg:C.muted,fontSize:12,fontWeight:on?700:500,cursor:'pointer'}}>{e.label}</button>
        )})}
      </div>
      <div style={{fontSize:10,fontWeight:700,color:C.accent,textTransform:'uppercase',letterSpacing:.5,marginBottom:6}}>Detalle de la gestión realizada *</div>
      <textarea value={detalle} onChange={e=>{setDetalle(e.target.value);if(err)setErr('')}} placeholder={PLACEHOLDER} rows={4} autoFocus style={{width:'100%',boxSizing:'border-box',padding:'10px 12px',borderRadius:10,border:`1px solid ${err&&!detalle.trim()?C.overdueText:C.border}`,fontSize:13,color:C.text,resize:'vertical',fontFamily:'inherit',lineHeight:1.45,outline:'none'}}/>
      <div style={{display:'flex',alignItems:'center',gap:10,margin:'12px 0 0',flexWrap:'wrap'}}>
        <label style={{fontSize:12,fontWeight:600,color:C.accent,cursor:'pointer',display:'inline-flex',alignItems:'center',gap:6,padding:'6px 12px',borderRadius:10,border:`1px dashed ${C.muted}`}}>
          + Adjuntar documento
          <input type='file' multiple onChange={e=>{addFiles(e.target.files);e.target.value=''}} style={{display:'none'}}/>
        </label>
        {files.length>0&&<span style={{fontSize:11,color:C.muted}}>{files.length} archivo{files.length>1?'s':''}</span>}
      </div>
      {files.length>0&&(
        <div style={{display:'flex',flexDirection:'column',gap:4,marginTop:8}}>
          {files.map((f,i)=>(
            <div key={i} style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:8,background:C.bgSoft,borderRadius:8,padding:'6px 10px'}}>
              <span style={{fontSize:12,color:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{f.name}</span>
              <span onClick={()=>setFiles(p=>p.filter((_,j)=>j!==i))} title='Quitar' style={{fontSize:17,color:C.muted,cursor:'pointer',lineHeight:1,flexShrink:0}}><Gl n='x'/></span>
            </div>
          ))}
        </div>
      )}
      {err&&<div style={{fontSize:12,color:C.overdueText,marginTop:8}}>{err}</div>}
      <div style={{fontSize:11,color:C.muted,marginTop:12,lineHeight:1.4}}>El detalle y los documentos le llegan por correo a quien asignó la tarea.</div>
      <div style={{display:'flex',gap:8,marginTop:14}}>
        <button onClick={onClose} disabled={saving} style={{flex:1,padding:'9px 14px',borderRadius:10,border:`1px solid ${C.border}`,background:'transparent',color:C.muted,fontSize:13,fontWeight:600,cursor:'pointer'}}>Cancelar</button>
        <button onClick={guardar} disabled={saving} style={{flex:2,padding:'9px 14px',borderRadius:10,border:'none',background:C.greenText,color:'#fff',fontSize:13,fontWeight:700,cursor:saving?'default':'pointer',opacity:saving?.6:1}}>{saving?'Guardando…':'Terminar y reportar'}</button>
      </div>
    </>
  )
}

// ─── USERS VIEW (gestión de usuarios para admin) ───────────────────────────────
function UsersView({onClose}) {
  const [users,setUsers] = useState([])
  const [loading,setLoading] = useState(true)
  const [saving,setSaving] = useState(false)
  const isDesktop = useIsDesktop()   // escritorio: tabla; móvil: lista
  const [newEmail,setNewEmail] = useState('')
  const [newName,setNewName] = useState('')
  const [newRole,setNewRole] = useState('limited')

  useEffect(()=>{
    supabase.from('user_roles').select('*').order('name').then(({data})=>{ setUsers(data||[]); setLoading(false) })
  },[])

  const saveRole = async(id,role) => {
    if(!okDB(await supabase.from('user_roles').update({role}).eq('id',id),'cambiar el rol')) return
    const em=users.find(u=>u.id===id)?.email   // doble escritura: `miembros` es la fuente tenant-aware que lee el login
    if(em) try{ okDB(await supabase.from('miembros').update({rol:role}).eq('email',em.toLowerCase()),'cambiar el rol del miembro') }catch(e){registrarError({origen:'accion',vista:'miembros',err:e})}
    setUsers(p=>p.map(u=>u.id===id?{...u,role}:u))
  }

  const addUser = async() => {
    if(!newEmail.trim()) return
    setSaving(true)
    const {data,error} = await supabase.from('user_roles').insert({email:newEmail.trim().toLowerCase(),name:newName.trim()||newEmail.split('@')[0],role:newRole}).select().single()
    if(!error) { setUsers(p=>[...p,data]); setNewEmail(''); setNewName('') }
    else appAlert('Error: '+error.message)
    setSaving(false)
  }

  const removeUser = async(id) => {
    if(!await appConfirm('¿Eliminar este usuario?')) return
    const em=users.find(u=>u.id===id)?.email
    if(!okDB(await supabase.from('user_roles').delete().eq('id',id),'quitar al usuario')) return
    if(em) try{ okDB(await supabase.from('miembros').delete().eq('email',em.toLowerCase()),'quitar al miembro') }catch(e){registrarError({origen:'accion',vista:'miembros',err:e})}
    setUsers(p=>p.filter(u=>u.id!==id))
  }

  return (
    <div>
      {loading?<div style={{textAlign:'center',padding:30}}><Spin/></div>:(
        <>
          {isDesktop ? (
            /* Escritorio: tabla Nombre · Email · Rol · quitar (misma data y handlers). Móvil: la lista de abajo, intacta. */
            <div style={{marginBottom:16,overflowX:'auto'}}><table style={{width:'100%',borderCollapse:'collapse',fontSize:12.5}}>
              <thead><tr>{['Nombre','Email','Rol',''].map((h,i)=><th key={i} style={{...TH_BAND,textAlign:'left',padding:'6px 8px',borderBottom:`1px solid ${C.border}`}}>{h}</th>)}</tr></thead>
              <tbody>{users.map(u=>(
                <tr key={u.id}>
                  <td style={{padding:'9px 8px',borderBottom:`0.5px solid ${C.bgSoft}`,fontWeight:600,color:C.text}}>{u.name}</td>
                  <td style={{padding:'9px 8px',borderBottom:`0.5px solid ${C.bgSoft}`,color:C.muted}}>{u.email}</td>
                  <td style={{padding:'9px 8px',borderBottom:`0.5px solid ${C.bgSoft}`}}><select value={u.role} onChange={e=>saveRole(u.id,e.target.value)} style={{padding:'5px 8px',borderRadius:6,border:`1px solid ${C.border}`,background:C.bgSoft,color:C.text,fontSize:12}}>{ROLES_DEF.map(r=><option key={r.id} value={r.id}>{r.label}</option>)}</select></td>
                  <td style={{padding:'9px 8px',borderBottom:`0.5px solid ${C.bgSoft}`,textAlign:'right'}}><button onClick={()=>removeUser(u.id)} title='Quitar' style={{background:'none',border:'none',color:C.muted,cursor:'pointer',fontSize:16}}><Gl n='x'/></button></td>
                </tr>))}</tbody>
            </table></div>
          ) : (
          <div style={{marginBottom:16}}>
            {users.map(u=>(
              <div key={u.id} style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'10px 0',borderBottom:`1px solid ${C.border}`}}>
                <div>
                  <div style={{fontSize:13,fontWeight:600,color:C.text}}>{u.name}</div>
                  <div style={{fontSize:11,color:C.muted}}>{u.email}</div>
                </div>
                <div style={{display:'flex',gap:8,alignItems:'center'}}>
                  <select value={u.role} onChange={e=>saveRole(u.id,e.target.value)} style={{padding:'5px 8px',borderRadius:6,border:`1px solid ${C.border}`,background:C.bgSoft,color:C.text,fontSize:12}}>
                    {ROLES_DEF.map(r=><option key={r.id} value={r.id}>{r.label}</option>)}
                  </select>
                  <button onClick={()=>removeUser(u.id)} style={{background:'none',border:'none',color:C.muted,cursor:'pointer',fontSize:16}}><Gl n='x'/></button>
                </div>
              </div>
            ))}
          </div>)}
          <div style={{background:C.bgSoft,borderRadius:10,padding:'12px 14px'}}>
            <div style={{fontSize:12,fontWeight:600,color:C.text,marginBottom:10}}>Agregar usuario</div>
            <Fld label={`Email (@${BRAND.emailDominio})`}><Inp value={newEmail} onChange={e=>setNewEmail(e.target.value)} placeholder={`nombre@${BRAND.emailDominio}`}/></Fld>
            <Fld label='Nombre'><Inp value={newName} onChange={e=>setNewName(e.target.value)} placeholder='Nombre completo'/></Fld>
            <Fld label='Rol'>
              <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:8}}>
                {ROLES_DEF.map(({id:v,label:l})=>(
                  <button key={v} onClick={()=>setNewRole(v)} style={{padding:'8px',borderRadius:8,border:`2px solid ${newRole===v?C.accent:C.border}`,background:newRole===v?C.azulBg:'transparent',color:newRole===v?C.accent:C.muted,fontSize:12,fontWeight:600,cursor:'pointer'}}>{l}</button>
                ))}
              </div>
              <div style={{fontSize:11,color:C.muted,marginTop:6}}>{rolVe(newRole)}</div>
            </Fld>
            <button disabled={saving||!newEmail.trim()} onClick={addUser} style={{width:'100%',padding:11,borderRadius:10,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:700,cursor:'pointer',marginTop:8,opacity:!newEmail.trim()?.6:1}}>
              {saving?'Guardando...':'Agregar usuario'}
            </button>
          </div>
        </>
      )}
    </div>
  )
}

// ─── IMPORTAR FACTURAS DESDE EXCEL (antiguas, con fecha de pago) — con preview y pre-confirmación ──
function ImportFacturasExcel({clients=[],clientEntities=[],billing=[],onImported,onClose}) {
  const [rows,setRows] = useState(null)
  const [fileName,setFileName] = useState('')
  const [cargando,setCargando] = useState(false)
  const [importando,setImportando] = useState(false)
  const [resultado,setResultado] = useState(null)
  const [editRow,setEditRow] = useState(null)   // id de fila en modo "asignar cliente"
  const [q,setQ] = useState('')
  const [iaBusy,setIaBusy] = useState(false)
  const [iaReport,setIaReport] = useState(null)   // auditoría de Opus 4.8 antes de importar
  const norm = s => String(s??'').toLowerCase().trim()
  const normRut = crNormRut   // normalizador único de RUT
  const inp = {width:'100%',height:36,border:`0.5px solid ${C.border}`,borderRadius:8,fontSize:13,padding:'0 11px',color:C.text,background:'#fff',outline:'none',boxSizing:'border-box'}
  const fmt0 = n => fmt(Number(n)||0)   // formateador CLP único (global fmt): redondeo y signo -$ correctos
  const fmtD = iso => { if(!iso) return '—'; const p=String(iso).slice(0,10).split('-'); return p.length===3?`${p[2]}-${p[1]}-${p[0]}`:String(iso) }
  const dueFromIssued = iso => ultimoDiaHabilMesEmision(iso)   // último día hábil del mes de emisión (regla del estudio)
  // Pagada sin fecha de pago: se asume pagada a los 20 días de emitida (criterio del estudio).
  const pagoInferido = iso => { if(!iso) return null; const d=new Date(iso+'T12:00'); d.setDate(d.getDate()+20); return d.toISOString().slice(0,10) }
  const parseMonto = v => { if(v==null||v==='') return null; if(typeof v==='number') return Math.round(v); let s=String(v).replace(/[^\d,.-]/g,''); if(s.includes(',')&&s.includes('.')) s=s.replace(/\./g,'').replace(',','.'); else if(s.includes(',')) s=s.replace(',','.'); const n=parseFloat(s); return isNaN(n)?null:Math.round(n) }
  const parseFecha = v => { if(!v) return null; if(v instanceof Date && !isNaN(v)) { const d=new Date(v.getTime()-v.getTimezoneOffset()*60000); return d.toISOString().slice(0,10) } const s=String(v).trim(); let m=s.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})/); if(m) return `${m[1]}-${String(m[2]).padStart(2,'0')}-${String(m[3]).padStart(2,'0')}`; m=s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/); if(m){ let[,d,mo,y]=m; if(y.length===2) y='20'+y; return `${y}-${String(mo).padStart(2,'0')}-${String(d).padStart(2,'0')}` } return null }
  const COL = {
    cliente:['cliente','nombre','razon social','razón social','receptor','señor','señores','razon','cliente/receptor','nombre cliente','razon social a facturar'],
    rut:['rut','r.u.t','rut receptor','rut cliente'],
    factura:['n° factura','factura','folio','nro','numero','número','n factura','n°','nº','documento','doc','numero factura','n de factura','nro factura'],
    monto:['monto','total','valor','neto','importe','monto total','bruto','monto bruto','monto neto','honorarios','monto honorarios'],
    emision:['emision','emisión','fecha emision','fecha emisión','fecha','fecha factura','fecha doc','fecha de emision','fecha de emisión'],
    pago:['fecha pago','pago','pagado','fecha de pago','fecha pagada','fecha cobro','cobrado','fecha de cobro'],
    estado:['estado','status','estado factura','estado pago'],
    concepto:['concepto','glosa','detalle','descripcion','descripción','observacion','observación','servicio'],
  }
  const mapEstado = raw => { const k=norm(raw); if(!k) return null; if(/(pagad|cobrad)/.test(k)) return 'Pagado'; if(/(anulad)/.test(k)) return 'Anulada'; if(/(vencid)/.test(k)) return 'Vencido'; if(/(pendiente|por cobrar|emitid)/.test(k)) return 'Pendiente'; return null }
  const descargarPlantilla = async()=>{
    try{
      const XLSX = await import('https://cdn.sheetjs.com/xlsx-0.20.1/package/xlsx.mjs')
      const header=['Cliente','RUT','N° factura','Monto','Fecha emisión','Fecha pago','Estado','Concepto']
      const ej=[['Ejemplo S.A.','76.123.456-7','1234','1500000','01-03-2026','15-03-2026','Pagada','Asesoría tributaria'],
                ['Otro Cliente SpA','77.987.654-3','1235','800000','05-03-2026','','Pendiente','Honorarios']]
      const ws=XLSX.utils.aoa_to_sheet([header,...ej]); const wb=XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb,ws,'Facturas')
      XLSX.writeFile(wb,'Plantilla_facturas.xlsx')
    }catch(e){ appAlert('No se pudo generar la plantilla: '+e.message) }
  }
  const matchClient = (nombre,rut) => {
    const rn=normRut(rut)
    if(rn){ const c=clients.find(x=>normRut(x.rut)===rn); if(c) return {client:c,ent:null}
      const ce=(clientEntities||[]).find(e=>normRut(e.rut)===rn); if(ce){ const c2=clients.find(x=>String(x.id)===String(ce.client_id)); if(c2) return {client:c2,ent:ce} } }
    const nn=norm(nombre)
    if(nn){ const c=clients.find(x=>norm(x.name)===nn); if(c) return {client:c,ent:null}
      const ce=(clientEntities||[]).find(e=>norm(e.name)===nn); if(ce){ const c2=clients.find(x=>String(x.id)===String(ce.client_id)); if(c2) return {client:c2,ent:ce} }
      if(nn.length>3){ const c2=clients.find(x=>norm(x.name).includes(nn)||nn.includes(norm(x.name))); if(c2) return {client:c2,ent:null,fuzzy:true} } }
    return {client:null,ent:null}
  }
  const onFile = async(e) => {
    const file=e.target.files?.[0]; if(!file) return
    setFileName(file.name); setCargando(true)
    try{
      const XLSX = await import('https://cdn.sheetjs.com/xlsx-0.20.1/package/xlsx.mjs')
      const wb = XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true})
      const sheet = wb.Sheets[wb.SheetNames[0]]
      const objs = XLSX.utils.sheet_to_json(sheet,{defval:''})
      const getField = (o,field) => { for(const k of Object.keys(o)){ if(COL[field].includes(norm(k))) return o[k] } return '' }
      const build = (g,idx) => {
        const rut=String(g('rut')||'').trim(), nombre=String(g('cliente')||'').trim()
        const factura=String(g('factura')||'').trim().replace(/\.0$/,'')
        const concepto=String(g('concepto')||'').trim()||'Honorarios'
        const emision=parseFecha(g('emision')), pago=parseFecha(g('pago')), monto=parseMonto(g('monto'))
        if(!rut&&!nombre&&!factura&&monto==null) return null
        const m=matchClient(nombre,rut)
        const estadoCol=mapEstado(g('estado'))
        const status = estadoCol || (pago?'Pagado':'Pendiente')
        let error=null
        if(monto==null) error='Monto inválido'; else if(monto<=0) error='Monto debe ser > 0'
        // dedupe por folio NORMALIZADO (soporta "340" == "Factura 340" == "340.0"); evita la doble carga que duplicó facturas.
        const _nf = v => folioN(String(v||'').replace(/\.0$/,'')).toLowerCase()
        const dup = factura && _nf(factura)!=='' && (billing||[]).some(b=>_nf(b.invoice_no)===_nf(factura))
        // Pagada sin fecha → se infiere emisión + 20 días (criterio del estudio); se marca como estimada.
        const pagoFinal = pago || (status==='Pagado'&&emision?pagoInferido(emision):null)
        const pagoEstimado = !pago && !!pagoFinal
        return {id:idx, rut, nombre, factura, concepto, emision, pago:pagoFinal, pagoEstimado, monto, status,
          client_id:m.client?.id||null, clientName:m.client?.name||null, entity_id:m.ent?.id||null,
          receptor_name:(m.ent?.name)||nombre||null, receptor_rut:(m.ent?.rut)||rut||null, fuzzy:!!m.fuzzy, error, dup}
      }
      let parsed=[]
      objs.forEach(o=>{ const r=build(f=>getField(o,f), parsed.length); if(r) parsed.push(r) })
      // Dedup dentro del MISMO archivo: la 2ª aparición de un N° de factura se marca como duplicada.
      const vistos=new Set()
      parsed.forEach(r=>{ if(r.factura){ if(vistos.has(r.factura)) r.dup=true; else vistos.add(r.factura) } })
      if(parsed.length===0){ appAlert('No se encontraron filas. El Excel debe tener al menos columnas de Cliente (o RUT), Monto y Fecha. Tip: agrega una columna "Fecha pago" para que entren como pagadas.'); setRows(null); setCargando(false); return }
      setRows(parsed)
    }catch(err){ appAlert('Error al leer el Excel: '+err.message) }
    setCargando(false)
  }
  const asignar = async (rowId, clientId) => {
    const c=clients.find(x=>String(x.id)===String(clientId))
    const ents=(clientEntities||[]).filter(e=>String(e.client_id)===String(clientId))
    const row=(rows||[]).find(r=>r.id===rowId)
    const rut=row?.rut?String(row.rut).trim():''
    // Aprende: guarda el RUT como razón social del cliente para que próximas importaciones lo reconozcan solas (no repetir el trabajo).
    if(rut){
      await aprenderRS(clientId, rut, row?.nombre||c?.name, clientEntities)   // fuente única (dedup por RUT)
    }
    // Aplica el cliente a TODAS las filas con el mismo RUT que aún no lo tienen (no asignar a mano una por una).
    setRows(p=>p.map(r=>(r.id===rowId || (rut && String(r.rut).trim()===rut && !r.client_id))
      ? {...r,client_id:clientId,clientName:c?.name||null,entity_id:ents.length===1?ents[0].id:r.entity_id,fuzzy:false}
      : r))
    setEditRow(null); setQ('')
  }
  const toggleEx = id => setRows(p=>p.map(r=>r.id===id?{...r,_skip:!r._skip}:r))
  const importar = async() => {
    const aImportar = (rows||[]).filter(r=>!r.error&&!r.dup&&!r._skip)
    if(aImportar.length===0){ appAlert('No hay filas válidas para importar.'); return }
    setImportando(true)
    // Fila por fila: si un N° de factura ya existe (incl. borradas, que igual ocupan el número único), se omite esa sola y sigue.
    let ok=0, dups=0, errs=0, lastErr=''
    for(const r of aImportar){
      const _yImp = r.emision ? new Date(r.emision).getFullYear() : (r.pago ? new Date(r.pago).getFullYear() : null)
      const payload={client_id:r.client_id||null, entity_id:r.entity_id||null, concept:r.concepto, amount:r.monto, status:r.status,
        invoice_no:r.factura||null, issued_at:r.emision||null, due:r.emision?dueFromIssued(r.emision):null, paid_at:r.pago||null,
        sale_year:(_yImp>1990&&_yImp<2100)?_yImp:null,
        receptor_name:r.receptor_name||null, receptor_rut:r.receptor_rut||null, billing_type:'honorarios', updated_at:new Date().toISOString()}
      const {error}=await supabase.from('billing').insert(payload)
      if(error){ if(/duplicate|unique/i.test(error.message)) dups++; else { errs++; lastErr=error.message } } else ok++
    }
    setResultado({n:ok, dups, errs, lastErr})
    onImported&&await onImported()
    setImportando(false)
  }
  // Auditoría con IA (Opus 4.8) ANTES de importar: solo lee y opina, no modifica nada.
  const revisarIA = async() => {
    if(!rows?.length) return
    setIaBusy(true); setIaReport(null)
    try{
      const muestra = rows.map((r,i)=>`${i+1}|${(r.nombre||'').slice(0,40)}|${r.rut||''}|${r.monto??''}|${r.emision||''}|${r.pago||''}|${r.status||''}|${(r.concepto||'').slice(0,45)}|${r.client_id?'match':'SIN'}`).join('\n')
      const prompt = `Eres auditor de datos de facturación de un estudio de abogados chileno. Revisa este lote de facturas ANTES de importarlo y advierte problemas. Cada fila es: idx|cliente|rut|monto(CLP)|fechaEmision(AAAA-MM-DD)|fechaPago|estado|concepto|match (match=el cliente YA existe en la base; SIN=no existe y quedaría huérfana).

Devuelve SOLO un JSON válido (sin markdown ni backticks):
{"resumen":"2-3 frases con totales y estado general","alertas":[{"tipo":"corto","detalle":"qué pasa y por qué","n":cantidad_de_filas}],"clientes_a_crear":["NOMBRE (RUT)"],"recomendacion":"go o no-go y por qué, 1-2 frases"}

Enfócate en: filas SIN cliente (cuántas y agrupar por cliente nuevo), montos negativos o notas de crédito, facturas anuladas, fechas fuera de un rango razonable, RUT mal formateados (espacios), conceptos truncados o ambiguos, y cualquier inconsistencia. En "clientes_a_crear" lista (máx 60) los clientes con estado SIN, sin repetir, formato "NOMBRE (RUT)". NO inventes datos; básate solo en las filas. Sé conciso y útil.

FILAS (${rows.length}):
${muestra}`
      const j = await claudeCall({model:'claude-opus-4-8',max_tokens:2500,messages:[{role:'user',content:prompt}]})
      let txt = (j?.content?.[0]?.text||'').replace(/```json|```/g,'').trim()
      const rep = JSON.parse(txt)
      setIaReport(rep)
    }catch(e){ appAlert('No se pudo analizar con IA: '+e.message) }
    setIaBusy(false)
  }

  // ── render ──
  if(resultado) return (
    <div style={{padding:'20px',textAlign:'center'}}>
      <div style={{fontSize:15,fontWeight:600,color:C.normal,marginBottom:8}}>Importadas {resultado.n} factura{resultado.n!==1?'s':''}</div>
      <div style={{fontSize:12,color:C.muted,marginBottom:18}}>Ya están en Facturación. Asigna las que quedaron sin cliente.{resultado.dups>0&&` ${resultado.dups} omitida${resultado.dups!==1?'s':''} por N° de factura repetido.`}{resultado.errs>0&&` ${resultado.errs} con error.`}</div>
      <button onClick={onClose} style={{padding:'10px 18px',borderRadius:10,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:600,cursor:'pointer'}}>Cerrar</button>
    </div>
  )
  if(!rows) return (
    <div style={{padding:'8px 2px'}}>
      <div style={{fontSize:12,color:C.muted,lineHeight:1.5,marginBottom:14}}>Sube un Excel con tus facturas antiguas. Detecta columnas por nombre: <strong>Cliente</strong> o <strong>RUT</strong>, <strong>N° factura</strong>, <strong>Monto</strong>, <strong>Fecha</strong> (emisión) y <strong>Fecha pago</strong>. Las que traigan fecha de pago entran como <strong>Pagadas</strong>; el resto como Pendientes. Verás un preview antes de guardar.</div>
      <label style={{display:'block',border:`1.5px dashed ${C.accent}`,borderRadius:12,padding:'22px 14px',textAlign:'center',cursor:'pointer',background:C.bgSoft}}>
        <input type='file' accept='.xlsx,.xls' onChange={onFile} style={{display:'none'}}/>
        <div style={{fontSize:13,fontWeight:600,color:C.accent}}>{cargando?'Leyendo…':'Elegir archivo Excel'}</div>
        {fileName&&<div style={{fontSize:11,color:C.muted,marginTop:4}}>{fileName}</div>}
      </label>
      <div style={{textAlign:'center',marginTop:10}}>
        <button onClick={descargarPlantilla} style={{fontSize:12,fontWeight:600,color:C.muted,background:'none',border:'none',cursor:'pointer',textDecoration:'underline'}}>Descargar plantilla de ejemplo</button>
      </div>
    </div>
  )
  const validas = rows.filter(r=>!r.error&&!r.dup&&!r._skip)
  const totalImp = validas.reduce((a,r)=>a+(r.monto||0),0)
  const sinCli = validas.filter(r=>!r.client_id).length
  const stPill = r => r.error?['Error',C.overdue,'#FCEBEB']:r.dup?['Ya existe','#C77F18',C.soonBg]:r._skip?['Omitida',C.muted,C.bgSoft]:r.status==='Pagado'?['Pagada',C.normal,'#E1F5EE']:['Pendiente',C.accent,'#E6EEF1']
  const matches = q.trim()?clients.filter(c=>norm(c.name).includes(norm(q))||normRut(c.rut).includes(normRut(q))||norm(c.razon_social).includes(norm(q))).sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'es')).slice(0,8):[]
  return (
    <div>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:10,gap:8}}>
        <div style={{fontSize:12,color:C.muted}}><strong style={{color:C.text}}>{validas.length}</strong> a importar · {fmt0(totalImp)}{sinCli>0&&<span style={{color:C.soon}}> · {sinCli} sin cliente</span>}</div>
        <button onClick={()=>{setRows(null);setFileName('');setIaReport(null)}} style={{fontSize:11,color:C.muted,background:'none',border:`0.5px solid ${C.border}`,borderRadius:8,padding:'4px 9px',cursor:'pointer'}}>Otro archivo</button>
      </div>
      {/* Revisión con IA (Opus 4.8) — solo audita, no modifica */}
      <button onClick={revisarIA} disabled={iaBusy} style={{width:'100%',marginBottom:10,height:44,borderRadius:10,border:`1px solid ${C.accent}`,background:iaBusy?C.bgSoft:C.azulBg,color:C.accent,fontSize:12,fontWeight:600,cursor:iaBusy?'default':'pointer',display:'flex',alignItems:'center',justifyContent:'center',gap:8}}>{iaBusy?<Spin/>:null}{iaBusy?'Analizando con Opus 4.8…':(iaReport?'Volver a revisar con IA':'Revisar con IA (Opus 4.8)')}</button>
      {iaReport&&(
        <div style={{border:`1px solid ${C.border}`,borderRadius:10,padding:'12px 13px',marginBottom:12,background:C.bgSoft}}>
          <div style={{...SEC_LBL,marginBottom:6}}>Revisión IA · Opus 4.8</div>
          {iaReport.resumen&&<div style={{fontSize:12,color:C.text,lineHeight:1.45,marginBottom:9}}>{iaReport.resumen}</div>}
          {Array.isArray(iaReport.alertas)&&iaReport.alertas.length>0&&<div style={{display:'flex',flexDirection:'column',gap:5,marginBottom:9}}>
            {iaReport.alertas.map((a,i)=>(
              <div key={i} style={{display:'flex',gap:7,fontSize:12,color:C.text,alignItems:'baseline'}}>
                <span style={{color:C.soon,fontWeight:700,flexShrink:0}}>!</span>
                <span><strong style={{fontWeight:600}}>{a.tipo}{a.n?` (${a.n})`:''}:</strong> {a.detalle}</span>
              </div>
            ))}
          </div>}
          {Array.isArray(iaReport.clientes_a_crear)&&iaReport.clientes_a_crear.length>0&&(
            <details style={{marginBottom:9}}>
              <summary style={{fontSize:12,fontWeight:600,color:C.accent,cursor:'pointer'}}>Clientes a crear ({iaReport.clientes_a_crear.length})</summary>
              <div style={{fontSize:11,color:C.muted,marginTop:5,lineHeight:1.6,maxHeight:160,overflowY:'auto'}}>{iaReport.clientes_a_crear.map((c,i)=><div key={i}>{c}</div>)}</div>
            </details>
          )}
          {iaReport.recomendacion&&<div style={{fontSize:12,fontWeight:600,color:C.accent,borderTop:`1px solid ${C.border}`,paddingTop:8}}>{iaReport.recomendacion}</div>}
          <div style={{fontSize:10,color:C.textSoft,marginTop:8}}>La IA solo revisa; no cambia tus datos. Tú decides qué importar.</div>
        </div>
      )}
      <div style={{maxHeight:'52vh',overflowY:'auto',display:'flex',flexDirection:'column',gap:6}}>
        {rows.map(r=>{ const [sl,sc,sb]=stPill(r); return (
          <div key={r.id} style={{border:`0.5px solid ${C.border}`,borderRadius:10,padding:'9px 11px',opacity:(r._skip||r.error||r.dup)?.6:1}}>
            <div style={{display:'flex',justifyContent:'space-between',gap:8,alignItems:'flex-start'}}>
              <div style={{minWidth:0,flex:1}}>
                <div style={{fontSize:13,fontWeight:600,color:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{r.clientName||r.nombre||'(sin cliente)'}{r.fuzzy&&<span style={{color:C.soon,fontWeight:500}}> ·aprox</span>}</div>
                <div style={{fontSize:11,color:C.muted,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{r.factura?`Factura N° ${r.factura} · `:''}{r.concepto} · {fmtD(r.emision)}{r.pago?` · pagada ${fmtD(r.pago)}${r.pagoEstimado?' (estimada)':''}`:''}</div>
              </div>
              <div style={{textAlign:'right',flexShrink:0}}>
                <div style={{fontSize:13,fontWeight:600,color:C.text}}>{fmt0(r.monto)}</div>
                <span style={{fontSize:9.5,fontWeight:700,padding:'2px 8px',borderRadius:20,background:sb,color:sc,whiteSpace:'nowrap'}}>{sl}</span>
              </div>
            </div>
            {r.error&&<div style={{fontSize:11,color:C.overdue,marginTop:4}}>{r.error}</div>}
            {!r.error&&!r.dup&&(
              <div style={{display:'flex',gap:8,marginTop:6,alignItems:'center'}}>
                {!r.client_id&&editRow!==r.id&&<button onClick={()=>{setEditRow(r.id);setQ('')}} style={{fontSize:11,fontWeight:600,color:C.accent,background:C.azulBg,border:'none',borderRadius:8,padding:'4px 10px',cursor:'pointer'}}>+ Asignar cliente</button>}
                {r.client_id&&editRow!==r.id&&<button onClick={()=>{setEditRow(r.id);setQ('')}} style={{fontSize:11,color:C.muted,background:'none',border:`0.5px solid ${C.border}`,borderRadius:8,padding:'4px 9px',cursor:'pointer'}}>Cambiar</button>}
                <button onClick={()=>toggleEx(r.id)} style={{fontSize:11,color:C.muted,background:'none',border:`0.5px solid ${C.border}`,borderRadius:8,padding:'4px 9px',cursor:'pointer',marginLeft:'auto'}}>{r._skip?'Incluir':'Omitir'}</button>
              </div>
            )}
            {editRow===r.id&&(
              <div style={{marginTop:6}}>
                <input autoFocus value={q} onChange={e=>setQ(e.target.value)} placeholder='Buscar cliente…' style={inp}/>
                {matches.length>0&&<div style={{border:`0.5px solid ${C.border}`,borderRadius:8,marginTop:4,overflow:'hidden'}}>
                  {matches.map(c=>(<div key={c.id} onClick={()=>asignar(r.id,c.id)} style={{padding:'8px 11px',cursor:'pointer',borderBottom:`0.5px solid ${C.border}`}}><div style={{fontSize:13,fontWeight:500,color:C.text}}>{c.name}</div>{c.rut&&<div style={{fontSize:10,color:C.muted}}>{fmtRutCL(c.rut)}</div>}</div>))}
                </div>}
              </div>
            )}
          </div>
        )})}
      </div>
      <div style={{display:'flex',gap:8,marginTop:12}}>
        <button onClick={onClose} style={{flex:1,height:44,borderRadius:10,border:`0.5px solid ${C.border}`,background:'#fff',color:C.muted,fontSize:13,fontWeight:600,cursor:'pointer'}}>Cancelar</button>
        <button disabled={importando||validas.length===0} onClick={importar} style={{flex:2,height:44,borderRadius:10,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:700,cursor:(importando||validas.length===0)?'default':'pointer',opacity:(importando||validas.length===0)?.6:1}}>{importando?'Importando…':`Importar ${validas.length}`}</button>
      </div>
    </div>
  )
}

// ─── CONCILIACIÓN DE FACTURAS (v1: barrido de auditoría de dobles conteos) ──
// Detecta cuotas marcadas Pagado SIN N° de factura (una factura pagada real lleva folio): suelen ser
// "fantasma" que duplican una factura real (caso BM Soluciones). Agrupa por cliente, muestra la evidencia
// y deja darlas de baja (soft-delete, reversible) o marcarlas legítimas (la app aprende y no las re-muestra).
function ConciliacionModal({billing=[], setBilling, clients=[], clientEntities=[], sales=[], currentUserName, onClose}){
  const [ignorados,setIgnorados] = useState(null)   // ids marcados "no es duplicado" (learnings)
  const [busy,setBusy] = useState(false)
  const [toast,setToast] = useState(null)
  const [chosenCand,setChosenCand] = useState({})   // {fantasmaId: facturaRealId} candidata elegida a mano
  const [expanded,setExpanded] = useState({})       // {fantasmaId: 'cuotas'|'cand'} sección abierta
  const [resueltas,setResueltas] = useState([])     // log de la sesión: {b, tipo:'baja'|'legit'} para plegar + deshacer
  const [showResueltas,setShowResueltas] = useState(false)
  const [showConc,setShowConc] = useState(false)    // sección plegable de cuotas YA conciliadas (con folio)
  const [concQ,setConcQ] = useState('')             // búsqueda dentro de Conciliadas (por cliente/glosa/folio)
  const [cardFilter,setCardFilter] = useState(null) // null='todas' · 'match' · 'revisar' · 'conc' (filtro por tarjeta de resumen)
  const [pickRS,setPickRS] = useState({})           // {cid: entityId} razón social elegida cuando el cliente tiene varias
  const [dupSigs,setDupSigs] = useState(new Set())  // firmas (cliente::glosa) de duplicados confirmados antes → suben la certeza de futuras parecidas
  useEffect(()=>{ supabase.from('learnings').select('key').eq('kind','conciliacion_ok').then(({data})=>{ setIgnorados(new Set((data||[]).map(r=>String(r.key)))) },()=>setIgnorados(new Set())) },[])
  useEffect(()=>{ supabase.from('learnings').select('meta').eq('kind','conciliacion_dup').then(({data})=>{ const s=new Set(); (data||[]).forEach(r=>{ const mm=r.meta||{}; if(mm.client_id&&mm.concept) s.add(`${mm.client_id}::${glosaKey(mm.concept)}`) }); setDupSigs(s) },()=>{}) },[])
  useEffect(()=>{ if(toast){ const t=setTimeout(()=>setToast(null),5000); return ()=>clearTimeout(t) } },[toast])
  const ig = ignorados||new Set()
  const clientById = id => clients.find(c=>String(c.id)===String(id))
  const rutDe = id => { const c=clientById(id); if(c?.rut) return c.rut; const e=(clientEntities||[]).find(x=>x.client_id===id&&x.rut); return e?.rut||'' }
  const saleTitle = sid => sales.find(s=>String(s.id)===String(sid))?.title||''
  // Folio limpio: invoice_no a veces trae la palabra "Factura" (texto). Evita "Factura Factura 261".
  const folio = no => { const s=String(no||'').trim(); return /^\d+$/.test(s)?`Factura ${s}`:s }
  const folioNum = no => String(no||'').replace(/^factura\s*/i,'').trim()||'—'
  // Sospechosas: Pagado sin folio, vivas, no reembolso, no ya marcadas legítimas.
  const sospechosas = (billing||[]).filter(b=>!b.deleted_at && b.billing_type!=='reembolso' && b.status==='Pagado' && !b.invoice_no && !ig.has(String(b.id)))
  const grupos = {}
  sospechosas.forEach(b=>{ const k=String(b.client_id||'__'); (grupos[k]=grupos[k]||[]).push(b) })
  const realesDe = cid => (billing||[]).filter(b=>!b.deleted_at && b.billing_type!=='reembolso' && String(b.client_id)===String(cid) && b.invoice_no && ['Pagado','Pendiente'].includes(b.status))
  // Análisis determinista fantasma↔factura real: por cada candidata, score 0..1 + señales por campo.
  const analizar = (b, reales) => {
    const proy = saleTitle(b.sale_id)
    const cands = reales.map(r=>{
      const montoDelta = (r.amount||0)-(b.amount||0)
      const montoIgual = Math.abs(montoDelta) <= Math.max(1000, (b.amount||0)*0.01)
      const glosaSim = Math.max(simTexto(r.concept,b.concept), simTexto(r.concept,proy))
      const mismoProy = !!(r.sale_id&&b.sale_id&&String(r.sale_id)===String(b.sale_id)) || (!!proy&&simTexto(r.concept,proy)>=0.6)
      const d1=b.paid_at?String(b.paid_at).slice(0,10):'', d2=r.paid_at?String(r.paid_at).slice(0,10):''
      const mismaFecha = !!(d1&&d2&&d1===d2)
      // Razón social / RUT también pesan en el match: misma RS (entity_id), mismo RUT o mismo nombre de receptor.
      const rRut=normRut(r.receptor_rut), bRut=normRut(b.receptor_rut)
      const mismaRS = !!((r.entity_id&&b.entity_id&&String(r.entity_id)===String(b.entity_id)) || (rRut&&bRut&&rRut===bRut) || (r.receptor_name&&b.receptor_name&&_normTxt(r.receptor_name)===_normTxt(b.receptor_name)))
      const montoScore = montoIgual?0.40:Math.max(0,0.40-Math.min(0.40,Math.abs(montoDelta)/Math.max(1,b.amount||1)))
      const score = Math.min(1, montoScore + glosaSim*0.25 + (mismoProy?0.15:0) + (mismaFecha?0.10:0) + (mismaRS?0.10:0))
      return {r, montoDelta, montoIgual, glosaSim, mismoProy, mismaFecha, mismaRS, score}
    }).sort((a,b)=>b.score-a.score)
    return cands
  }
  const dupBoost = b => (b.client_id&&b.concept&&dupSigs.has(`${b.client_id}::${glosaKey(b.concept)}`)) ? 0.15 : 0   // aprendió que esta glosa ya fue duplicado
  const scoreOf = b => { const cs=analizar(b,realesDe(b.client_id)); return Math.min(1,(cs[0]?cs[0].score:0)+dupBoost(b)) }
  const pasaFiltro = b => cardFilter==='match' ? scoreOf(b)>=0.6 : cardFilter==='revisar' ? scoreOf(b)<0.6 : true
  // Suspechosas de ALTA certeza (para acción masiva): score boosteado ≥ 0.85.
  const altaCerteza = () => sospechosas.filter(b=>!ig.has(String(b.id))&&scoreOf(b)>=0.85)
  const veredicto = sc => sc>=0.85?['Muy probable duplicado',C.overdueText,'#FCEBEB']:sc>=0.6?['Probable duplicado','#854F0B',C.soonBg]:sc>=0.4?['Posible duplicado','#854F0B',C.soonBg]:['Poco probable','#537281',C.bgSoft]
  const fmtDelta = d => (d>0?'+':'−')+fmt(Math.abs(d))
  const STOP = new Set(['de','la','el','los','las','y','del','en','por','para','con','cuota','mensual','factura','cobro','servicio','servicios','asesoria','asesoría','permanente'])
  // Resalta en la glosa las palabras que también están en la otra (comparación visual de glosas).
  const diffGlosa = (txt, ref) => { const set=new Set(_normTxt(ref||'').split(/\s+/).filter(w=>w.length>=3&&!STOP.has(w))); return String(txt||'—').split(/(\s+)/).map((w,i)=>{ const t=_normTxt(w); return (set.has(t)&&t.length>=3)?<b key={i} style={{color:C.accent,fontWeight:700}}>{w}</b>:<span key={i}>{w}</span> }) }
  const darDeBaja = async(items)=>{
    const ids=items.map(x=>x.id); if(busy||!ids.length) return; setBusy(true)
    try{
      const now=new Date().toISOString()
      const {error}=await supabase.from('billing').update({deleted_at:now}).in('id',ids)
      if(error) throw error
      if(setBilling) setBilling(p=>p.map(b=>ids.includes(b.id)?{...b,deleted_at:now}:b))
      logEvent('conciliacion','dar_de_baja',{ids,n:ids.length},currentUserName)
      // Aprende del proceso: deja registro auditable de cada duplicado confirmado (concepto/cliente/monto).
      items.forEach(b=>learnPut('conciliacion_dup', b.id, 'dup', {concept:b.concept,client_id:b.client_id,amount:b.amount}))
      setResueltas(p=>[...items.map(b=>({b,tipo:'baja'})),...p])
      setToast(`${ids.length} cuota(s) dada(s) de baja — puedes deshacer en "Ya resueltas"`)
    }catch(e){ appAlert('Error: '+e.message) }
    setBusy(false)
  }
  const deshacerBaja = async(b)=>{
    setBusy(true)
    try{ const {error}=await supabase.from('billing').update({deleted_at:null}).eq('id',b.id); if(error)throw error; if(setBilling) setBilling(p=>p.map(x=>x.id===b.id?{...x,deleted_at:null}:x)); setResueltas(p=>p.filter(r=>!(r.tipo==='baja'&&r.b.id===b.id))); setToast('Cuota restaurada') }catch(e){ appAlert('Error: '+e.message) }
    setBusy(false)
  }
  const noEsDuplicado = (b)=>{
    learnPut('conciliacion_ok', b.id, 'legit', {concept:b.concept,client_id:b.client_id})
    logEvent('conciliacion','marcar_legitima',{id:b.id},currentUserName)
    setIgnorados(p=>new Set([...(p||[]),String(b.id)]))
    setResueltas(p=>[{b,tipo:'legit'},...p])
  }
  const deshacerLegit = async(b)=>{
    try{ await supabase.from('learnings').delete().eq('kind','conciliacion_ok').eq('key',String(b.id)) }catch(e){}
    setIgnorados(p=>{ const n=new Set(p||[]); n.delete(String(b.id)); return n })
    setResueltas(p=>p.filter(r=>!(r.tipo==='legit'&&r.b.id===b.id)))
  }
  const C2 = {muted:C.muted,text:C.text,border:C.border,accent:C.accent,over:C.overdue,green:C.greenText}
  const lbl = {fontSize:9,fontWeight:600,color:C.textSoft,textTransform:'uppercase',letterSpacing:.3}
  if(ignorados===null) return <div style={{padding:30,textAlign:'center',color:C.muted,fontSize:13}}>Cargando…</div>
  const claves = Object.keys(grupos)
  // Fila comparable: valor fantasma | valor real | punto de coincidencia (verde lleno / ámbar vacío).
  const cmpRow = (left,right,ok) => (
    <div style={{display:'grid',gridTemplateColumns:'1fr 1fr 14px',gap:8,padding:'6px 10px',background:ok?'#EDF7F2':'#FFFAF0',alignItems:'flex-start'}}>
      <div style={{fontSize:11,color:C.text,lineHeight:1.35,wordBreak:'break-word'}}>{left}</div>
      <div style={{fontSize:11,color:C.text,lineHeight:1.35,wordBreak:'break-word'}}>{right}</div>
      <span style={{fontSize:11,color:ok?C.greenText:C.soon,lineHeight:1.35}}>{ok?'●':'○'}</span>
    </div>
  )
  const stPillCuota = st => st==='Pagado'?['Pagada',C.greenText,'#E1F5EE']:st==='Programada'?['Programada',C.muted,C.bgSoft]:st==='Pendiente'?['Pendiente',C.accent,'#E6EEF1']:[st,C.muted,C.bgSoft]
  return (
    <div style={{maxWidth:600}}>
      <div style={{fontSize:11,color:C.muted,lineHeight:1.45,marginBottom:8}}>
        Cuotas <b style={{color:C.text}}>Pagadas sin folio</b> que pueden <b style={{color:C.text}}>Duplicar</b> una factura real. Toca una tarjeta para filtrar.
      </div>
      {(()=>{
        let conMatch=0; sospechosas.forEach(b=>{ if(scoreOf(b)>=0.6) conMatch++ })
        const aRev=sospechosas.length-conMatch
        const concCount=(billing||[]).filter(b=>!b.deleted_at&&b.billing_type!=='reembolso'&&b.invoice_no&&b.status==='Pagado').length
        const stat=(key,v,l,col,bg)=>{ const act=cardFilter===key; return (
          <button onClick={()=>{ const nk=act?null:key; setCardFilter(nk); if(nk==='conc') setShowConc(true) }} style={{flex:1,minWidth:68,background:bg,borderRadius:10,padding:'6px 8px',textAlign:'center',border:act?`2px solid ${col}`:'2px solid transparent',cursor:'pointer'}}>
            <div style={{fontSize:16,fontWeight:700,color:col,lineHeight:1.1}}>{v}</div>
            <div style={{...SEC_LBL,marginTop:1}}>{l}</div>
          </button>
        )}
        return (
          <div style={{display:'flex',gap:5,marginBottom:12}}>
            {stat(null,sospechosas.length,'Analizadas',C.text,C.bgSoft)}
            {stat('match',conMatch,'Con match',C.accent,'#E6EEF1')}
            {stat('revisar',aRev,'A revisar',aRev>0?C.overdueText:C.muted,aRev>0?C.overdueBg:C.bgSoft)}
            {stat('conc',concCount,'Conciliadas',C.greenText,'#E1F5EE')}
          </div>
        )
      })()}
      {(()=>{ const alta=altaCerteza(); if(alta.length<2) return null; const tot=alta.reduce((a,b)=>a+(b.amount||0),0); return (
        <button disabled={busy} onClick={async()=>{ if(await appConfirm(`Dar de baja ${alta.length} cuotas de alta certeza (≥85%) por ${fmt(tot)}? Van a Papelera (reversible).`)) darDeBaja(alta) }} style={{width:'100%',marginBottom:12,padding:'9px',borderRadius:10,border:`1px solid ${C.overdue}`,background:C.overdueBg,color:C.overdueText,fontSize:13,fontWeight:600,cursor:'pointer',opacity:busy?.6:1}}>Dar de baja las {alta.length} de alta certeza · {fmt(tot)}</button>
      )})()}
      {claves.length===0 && <div style={{textAlign:'center',color:C.muted,fontSize:13,padding:'28px 0'}}>Sin duplicados sospechosos. Todo en orden.</div>}
      {cardFilter!=='conc' && claves.length>0 && !claves.some(cid=>(grupos[cid]||[]).filter(pasaFiltro).length>0) && <div style={{textAlign:'center',color:C.muted,fontSize:13,padding:'22px 0'}}>Nada en esta categoría.</div>}
      {cardFilter!=='conc' && claves.map(cid=>{
        const grupoAll=(grupos[cid]||[]).filter(pasaFiltro); if(!grupoAll.length) return null
        const rsSel = pickRS[cid]||''   // '' = todas las RS; si se elige una, se filtran las cuotas a esa RS
        let grupo = rsSel ? grupoAll.filter(b=>String(b.entity_id)===String(rsSel)) : grupoAll
        if(cardFilter==='revisar') grupo = [...grupo].sort((a,b)=>scoreOf(a)-scoreOf(b))   // menor certeza primero
        const c=clientById(cid); const reales=realesDe(cid)
        const sumF=grupo.reduce((a,b)=>a+(b.amount||0),0); const sumR=reales.filter(r=>r.status==='Pagado').reduce((a,b)=>a+(b.amount||0),0)
        return (
          <div key={cid} style={{border:`1px solid ${C.border}`,borderRadius:12,overflow:'hidden',marginBottom:14}}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline',padding:'10px 14px',background:C.bgSoft,borderBottom:`1px solid ${C.border}`}}>
              {(()=>{
                const ents=(clientEntities||[]).filter(e=>String(e.client_id)===String(cid))
                const sel=ents.find(e=>String(e.id)===String(rsSel))
                return (<div style={{minWidth:0,flex:1}}>
                  <div style={{...NOMBRE_CLI}}>{c?.name||'Cliente'}</div>
                  {ents.length>1
                    ? <select value={rsSel} onChange={e=>setPickRS(p=>({...p,[cid]:e.target.value}))} style={{fontSize:10,color:rsSel?C.accent:C.muted,fontWeight:rsSel?600:400,border:`0.5px solid ${rsSel?C.accent:C.border}`,borderRadius:6,padding:'2px 6px',background:'#fff',marginTop:2,maxWidth:'100%'}}><option value=''>Todas las razones sociales</option>{ents.map(e=><option key={e.id} value={e.id}>{e.name}{e.rut?` · ${fmtRutCL(e.rut)}`:''}</option>)}</select>
                    : (ents[0]?<div style={{fontSize:10,color:C.textSoft,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{ents[0].name}{ents[0].rut?` | ${ents[0].rut}`:''}</div>:(rutDe(cid)?<div style={{fontSize:10,color:C.textSoft}}>{rutDe(cid)}</div>:null))}
                </div>)
              })()}
              <div style={{textAlign:'right',flexShrink:0}}><div style={lbl}>Sin folio · {grupo.length}</div><div style={{fontSize:13,fontWeight:600,color:C.overdue}}>{fmt(sumF)}</div></div>
            </div>
            {reales.length>0&&<div style={{fontSize:10,color:C.muted,padding:'6px 14px',borderBottom:`1px solid ${C.border}`}}>Facturas reales con folio del cliente: <b style={{color:C.greenText}}>{fmt(sumR)}</b> en {reales.filter(r=>r.status==='Pagado').length} pagada(s)</div>}
            {grupo.length===0&&<div style={{fontSize:11,color:C.muted,textAlign:'center',padding:'14px'}}>Esta razón social no tiene cuotas sin folio. Cambia el selector a "Todas".</div>}
            {grupo.map(b=>{
              const cands=analizar(b,reales)
              const m = chosenCand[b.id] ? (cands.find(x=>String(x.r.id)===String(chosenCand[b.id]))||cands[0]) : cands[0]
              const apr = dupBoost(b)>0   // la app aprendió que esta glosa ya fue duplicado
              const sc = m ? Math.min(1, m.score + dupBoost(b)) : 0
              const [vl,vfg,vbg] = m ? veredicto(sc) : ['Sin candidata clara','#537281',C.bgSoft]
              const otras = (billing||[]).filter(x=>!x.deleted_at&&x.billing_type!=='reembolso'&&String(x.client_id)===String(b.client_id)&&String(x.id)!==String(b.id)).sort((a,c)=>String(c.due||c.paid_at||'').localeCompare(String(a.due||a.paid_at||'')))
              const proyB = saleTitle(b.sale_id)
              return (
                <div key={b.id} style={{borderBottom:`1px solid ${C.border}`,padding:'10px 12px'}}>
                  <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:6,marginBottom:8}}>
                    <span style={{fontSize:11,fontWeight:700,padding:'3px 10px',borderRadius:20,background:vbg,color:vfg}}>{m?`${vl} · ${Math.round(sc*100)}%`:vl}</span>
                    {apr&&<span style={{fontSize:9.5,fontWeight:700,color:C.accent,background:C.azulBg,padding:'2px 8px',borderRadius:20,whiteSpace:'nowrap'}}>aprendido <Sparkle/></span>}
                  </div>
                  {m ? (
                    <div style={{border:`1px solid ${C.border}`,borderRadius:10,overflow:'hidden'}}>
                      <div style={{display:'grid',gridTemplateColumns:'1fr 1fr 14px',gap:8,padding:'7px 10px',borderBottom:`1px solid ${C.border}`}}>
                        <div style={{fontSize:9,fontWeight:700,color:C.overdueText,textTransform:'uppercase',letterSpacing:.3}}>Fantasma · sin folio</div>
                        <div style={{fontSize:9,fontWeight:700,color:C.greenText,textTransform:'uppercase',letterSpacing:.3}}>{folio(m.r.invoice_no)} · folio</div>
                        <span/>
                      </div>
                      {cmpRow(diffGlosa(b.concept,m.r.concept), diffGlosa(m.r.concept,b.concept), m.glosaSim>=0.6)}
                      {cmpRow(<b style={{fontWeight:700}}>{fmt(b.amount)}</b>, <span><b style={{fontWeight:700}}>{fmt(m.r.amount)}</b>{!m.montoIgual&&m.montoDelta!==0&&<span style={{color:C.soon,fontWeight:600}}> ({fmtDelta(m.montoDelta)})</span>}</span>, m.montoIgual)}
                      {cmpRow(b.paid_at?fmtFechaDMY(b.paid_at):'—', m.r.paid_at?fmtFechaDMY(m.r.paid_at):'—', m.mismaFecha)}
                      {cmpRow(proyB||'—', saleTitle(m.r.sale_id)||'—', m.mismoProy)}
                      {(b.receptor_name||m.r.receptor_name||b.receptor_rut||m.r.receptor_rut)&&cmpRow(b.receptor_name||b.receptor_rut||'—', m.r.receptor_name||m.r.receptor_rut||'—', m.mismaRS)}
                    </div>
                  ) : (
                    <div style={{border:`1px solid ${C.border}`,borderRadius:10,padding:'9px 11px',background:'#FFFAF0'}}>
                      <div style={{display:'flex',justifyContent:'space-between',gap:8}}><span style={{fontSize:12,color:C.text}}>{b.concept||'—'}</span><b style={{fontSize:13,fontWeight:600,color:C.text}}>{fmt(b.amount)}</b></div>
                      <div style={{fontSize:10,color:C.textSoft,marginTop:2}}>Pagada {b.paid_at?fmtFechaDMY(b.paid_at):'—'} · sin folio · no encontré una factura real que calce</div>
                    </div>
                  )}
                  <div style={{display:'flex',gap:10,marginTop:8,flexWrap:'wrap'}}>
                    {reales.length>0&&<button onClick={()=>setExpanded(p=>({...p,[b.id]:p[b.id]==='cand'?null:'cand'}))} style={{fontSize:11,color:C.muted,background:'none',border:`0.5px solid ${C.border}`,borderRadius:8,padding:'4px 9px',cursor:'pointer'}}>¿Otra factura? ({reales.length}) {expanded[b.id]==='cand'?<Gl n='chevU'/>:<Gl n='chevD'/>}</button>}
                    {otras.length>0&&<button onClick={()=>setExpanded(p=>({...p,[b.id]:p[b.id]==='cuotas'?null:'cuotas'}))} style={{fontSize:11,color:C.muted,background:'none',border:`0.5px solid ${C.border}`,borderRadius:8,padding:'4px 9px',cursor:'pointer'}}>Otras cuotas del cliente ({otras.length}) {expanded[b.id]==='cuotas'?<Gl n='chevU'/>:<Gl n='chevD'/>}</button>}
                  </div>
                  {expanded[b.id]==='cand'&&(
                    <div style={{border:`0.5px solid ${C.border}`,borderRadius:8,marginTop:6,overflow:'hidden'}}>
                      {cands.map(x=>{ const sel=String((chosenCand[b.id]||(cands[0]&&cands[0].r.id)))===String(x.r.id); return (
                        <div key={x.r.id} onClick={()=>setChosenCand(p=>({...p,[b.id]:x.r.id}))} style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8,padding:'7px 10px',borderBottom:`0.5px solid ${C.border}`,cursor:'pointer',background:sel?C.azulBg:'#fff'}}>
                          <div style={{minWidth:0}}><div style={{fontSize:11,fontWeight:sel?700:500,color:sel?C.accent:C.text}}>{folio(x.r.invoice_no)}</div><div style={{fontSize:10,color:C.textSoft,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{x.r.concept||'—'}</div></div>
                          <div style={{textAlign:'right',flexShrink:0}}><div style={{fontSize:11,fontWeight:600,color:C.text}}>{fmt(x.r.amount)}</div><div style={{fontSize:9,color:x.score>=0.6?C.greenText:C.soon}}>{Math.round(x.score*100)}%</div></div>
                        </div>
                      )})}
                    </div>
                  )}
                  {expanded[b.id]==='cuotas'&&(
                    <div style={{border:`0.5px solid ${C.border}`,borderRadius:8,marginTop:6,overflow:'hidden',maxHeight:'34vh',overflowY:'auto'}}>
                      {otras.map(x=>{ const [sl,sc,sb]=stPillCuota(x.status); const same=Math.abs((x.amount||0)-(b.amount||0))<=Math.max(1000,(b.amount||0)*0.01); return (
                        <div key={x.id} style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8,padding:'7px 10px',borderBottom:`0.5px solid ${C.border}`}}>
                          <div style={{minWidth:0}}><div style={{fontSize:11,color:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{x.concept||'—'}{same&&<span style={{color:C.soon,fontWeight:600}}> · = monto</span>}</div><div style={{fontSize:9,color:C.textSoft}}>{x.invoice_no?`Factura N° ${folioNum(x.invoice_no)} · `:''}{x.status==='Pagado'?`pagada ${x.paid_at?fmtFechaDMY(x.paid_at):''}`:`vence ${x.due?fmtFechaDMY(x.due):'—'}`}</div></div>
                          <div style={{textAlign:'right',flexShrink:0,display:'flex',alignItems:'center',gap:6}}><span style={{fontSize:9.5,fontWeight:700,padding:'2px 8px',borderRadius:20,background:sb,color:sc,whiteSpace:'nowrap'}}>{sl}</span><span style={{fontSize:11,fontWeight:600,color:C.text}}>{fmt(x.amount)}</span></div>
                        </div>
                      )})}
                    </div>
                  )}
                  <div style={{display:'flex',gap:6,marginTop:8}}>
                    <button disabled={busy} onClick={()=>darDeBaja([b])} style={{...chipBtn('primary'),opacity:busy?.6:1}}>Dar de baja la fantasma</button>
                    <button onClick={()=>noEsDuplicado(b)} style={chipBtn('soft')}>No es duplicado</button>
                  </div>
                </div>
              )
            })}
            {grupo.length>1&&<div style={{padding:'10px 14px'}}><button disabled={busy} onClick={()=>darDeBaja(grupo)} style={{...chipBtn('primary'),opacity:busy?.6:1}}>Dar de baja las {grupo.length}</button></div>}
          </div>
        )
      })}
      {(()=>{
        const conc=(billing||[]).filter(b=>!b.deleted_at&&b.billing_type!=='reembolso'&&b.invoice_no&&b.status==='Pagado').sort((a,b)=>String(b.paid_at||'').localeCompare(String(a.paid_at||'')))
        if(conc.length===0) return null
        const totC=conc.reduce((a,b)=>a+(b.amount||0),0)
        const cq=concQ.trim().toLowerCase()
        const concF = cq ? conc.filter(b=>{ const cn=(clientById(b.client_id)?.name||'').toLowerCase(); return cn.includes(cq)||String(b.concept||'').toLowerCase().includes(cq)||String(b.invoice_no||'').toLowerCase().includes(cq) }) : conc
        const gC={}; concF.forEach(b=>{ const k=String(b.client_id||'__'); (gC[k]=gC[k]||[]).push(b) })
        return (
          <div style={{border:`1px solid ${C.border}`,borderRadius:10,overflow:'hidden',marginTop:4,marginBottom:8}}>
            <div onClick={()=>setShowConc(s=>!s)} style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'10px 14px',cursor:'pointer',background:'#EDF7F2'}}>
              <span style={{fontSize:12,color:C.muted}}><b style={{color:C.greenText}}>●</b> Conciliadas · con folio · <b style={{color:C.text}}>{conc.length}</b> · {fmt(totC)}</span>
              <span style={{fontSize:12,color:C.accent,fontWeight:600}}>{showConc?<>Ocultar{" "}<Gl n='chevU'/></>:<>Ver{" "}<Gl n='chevD'/></>}</span>
            </div>
            {showConc&&<div style={{maxHeight:'44vh',overflowY:'auto'}}>
              <div style={{padding:'8px 12px',borderTop:`0.5px solid ${C.border}`,position:'sticky',top:0,background:'#fff',zIndex:1}}><input value={concQ} onChange={e=>setConcQ(e.target.value)} placeholder='Buscar por cliente, glosa o folio…' style={{width:'100%',height:34,border:`1px solid ${C.border}`,borderRadius:8,padding:'0 10px',fontSize:12,color:C.text,background:C.bgSoft,colorScheme:'light',outline:'none',boxSizing:'border-box'}}/></div>
              {Object.keys(gC).length===0&&<div style={{fontSize:12,color:C.muted,textAlign:'center',padding:'16px 0'}}>Sin coincidencias.</div>}
              {Object.keys(gC).map(cid=>{ const list=gC[cid]; const c=clientById(cid); return (
                <div key={cid}>
                  <div style={{fontSize:10,fontWeight:600,color:C.textSoft,textTransform:'uppercase',letterSpacing:.3,padding:'7px 14px 3px',borderTop:`0.5px solid ${C.border}`,background:C.bgPanel}}>{c?.name||'Cliente'} · {list.length}</div>
                  {list.map(x=>(
                    <div key={x.id} style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8,padding:'7px 14px',borderTop:`0.5px solid ${C.border}`}}>
                      <div style={{minWidth:0}}><div style={{fontSize:11,color:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}><b style={{color:C.greenText}}>Factura N° {folioNum(x.invoice_no)}</b> · {x.concept||'—'}</div><div style={{fontSize:9,color:C.textSoft}}>Pagada {x.paid_at?fmtFechaDMY(x.paid_at):'—'}</div></div>
                      <span style={{fontSize:11,fontWeight:600,color:C.text,flexShrink:0}}>{fmt(x.amount)}</span>
                    </div>
                  ))}
                </div>
              )})}
            </div>}
          </div>
        )
      })()}
      {resueltas.length>0&&(
        <div style={{border:`1px solid ${C.border}`,borderRadius:10,overflow:'hidden',marginTop:4}}>
          <div onClick={()=>setShowResueltas(s=>!s)} style={{display:'flex',justifyContent:'space-between',alignItems:'center',padding:'10px 14px',cursor:'pointer',background:C.bgSoft}}>
            <span style={{fontSize:12,color:C.muted}}>Ya resueltas en esta revisión · <b style={{color:C.text}}>{resueltas.length}</b></span>
            <span style={{fontSize:12,color:C.accent,fontWeight:600}}>{showResueltas?<>Ocultar{" "}<Gl n='chevU'/></>:<>Ver / deshacer{" "}<Gl n='chevD'/></>}</span>
          </div>
          {showResueltas&&resueltas.map((rz,i)=>(
            <div key={i} style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8,padding:'8px 14px',borderTop:`0.5px solid ${C.border}`}}>
              <div style={{minWidth:0}}><div style={{fontSize:11,color:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{rz.b.concept||'—'} · {fmt(rz.b.amount)}</div><div style={{fontSize:9,color:C.textSoft}}>{rz.tipo==='baja'?'Dada de baja (en Papelera)':'Marcada legítima'}</div></div>
              <button disabled={busy} onClick={()=>rz.tipo==='baja'?deshacerBaja(rz.b):deshacerLegit(rz.b)} style={{fontSize:11,fontWeight:600,color:C.accent,background:C.azulBg,border:'none',borderRadius:8,padding:'4px 10px',cursor:'pointer',flexShrink:0}}>Deshacer</button>
            </div>
          ))}
        </div>
      )}
      {toast&&<div style={{position:'sticky',bottom:0,background:C.greenText,color:'#fff',fontSize:12,fontWeight:600,padding:'10px 12px',borderRadius:8,marginTop:8}}>{toast}</div>}
    </div>
  )
}

// ─── CENTRO DE APRENDIZAJE: lo que la app aprendió (learnings) — visible y borrable (des-aprender un match errado) ──
// Asistente de redacción legal con IA (claudeCall). Redacta en el FORMATO del estudio; el usuario valida/edita (compuerta humana).
const ESTUDIO_BRIEF = `Eres redactor del estudio jurídico chileno ${BRAND.nombre} (práctica corporativa y tributaria). Socios: ${BRAND.socios}. Membrete/firma del estudio: "${BRAND.direccionFirma}, ${BRAND.ciudad}", "${BRAND.telefono}", "${BRAND.web}". Escribe en español jurídico chileno, formal, claro y preciso. El estudio factura SIEMPRE exento de IVA; los honorarios se expresan en UF. Usa SOLO los datos que entregue el usuario; si falta un dato clave (honorarios, alcance, nombres), déjalo marcado como [completar] en vez de inventarlo. Devuelve solo el documento, sin comentarios ni explicaciones.`
const TIPOS_REDACCION = [
  {k:'propuesta', lbl:'Propuesta de honorarios', max:2600, sys:`${ESTUDIO_BRIEF}\n\nRedacta una PROPUESTA DE SERVICIOS PROFESIONALES con la estructura exacta del estudio:\n· Encabezado: "Propuesta de Servicios Profesionales" + subtítulo con el tipo de asesoría; destinatario(s) y empresa; "PRESENTE"; "Santiago, <fecha>"; "CONFIDENCIAL"; "Ref.: Propuesta de Servicios Legales - <tema>"; "De mi consideración:".\n· Intro: "${BRAND.nombre} tiene el agrado de someter a su consideración la presente propuesta de servicios profesionales. El objeto de nuestro encargo es...".\n· "I. Alcance de los Servicios" (subsecciones A/B e ítems numerados según corresponda).\n· "II. Honorarios Profesionales" (Honorario Fijo / Retainer en UF; Honorario de Éxito / Success Fee como % si aplica).\n· "III. Forma de Pago" (ej. Retainer 50% a la aceptación y 50% al cierre; "la facturación se realizará mediante factura exenta de IVA").\n· "IV. Condiciones y Exclusiones" (no incluye litigios/arbitrajes salvo indicación expresa; un cambio sustancial de alcance requiere revisión de honorarios; los gastos de terceros —derechos notariales, CBR, certificados— son de cargo del cliente).\n· Cierre cordial + firma de un Socio (Cristóbal Liberona o Erasmo Escala), bajo él "Socio" y "${BRAND.nombre}".`},
  {k:'memo', lbl:'Memo', max:2200, sys:`${ESTUDIO_BRIEF}\n\nRedacta un MEMORÁNDUM legal: membrete del estudio ("CONFIDENCIAL", fecha, dirección, teléfono, leabogados.cl), una exposición ordenada de los hechos, el análisis jurídico/tributario aplicable y conclusiones/recomendaciones.`},
  {k:'informe', lbl:'Informe tributario', max:3000, sys:`${ESTUDIO_BRIEF}\n\nRedacta un INFORME / OPINIÓN LEGAL TRIBUTARIA sobre la materia específica que indique el usuario, con la estructura y el estándar del estudio:\n· Encabezado: "Santiago, <fecha>"; destinatario ("Señores <X>", "Presente"); "Ref.: Opinión legal – <materia>"; "De nuestra consideración:".\n· Intro: "En nuestra calidad de asesores legales de <Sociedad>, RUT <X>, ... hemos examinado <la documentación/materia>...".\n· "I. Antecedentes y alcance de la revisión" (hechos, contratos y documentos tenidos a la vista).\n· "II. Marco normativo y análisis" (subsecciones II.1, II.2…; CITA las normas chilenas pertinentes —DL 824 sobre Impuesto a la Renta, DL 825 sobre IVA y sus artículos, Código Tributario, circulares/oficios del SII—; cuando haya requisitos copulativos, analízalos UNO A UNO y cierra cada uno, cuando corresponda, con "Este requisito se encuentra satisfecho").\n· "III. Conclusiones" (numeradas; usa el estándar "en términos jurídicamente razonables").\n· "IV. Reservas y limitaciones" (opinión emitida solo desde una perspectiva jurídica, sobre los antecedentes a la fecha, bajo estándar de razonabilidad jurídica, sin garantía de resultado ni pronunciamiento sobre la actuación futura del SII, en beneficio exclusivo del destinatario).\n· Firma de un Socio (Cristóbal Liberona o Erasmo Escala), "Socio", "${BRAND.nombre}".\nSALVAGUARDA CRÍTICA: NUNCA inventes números de artículos, oficios, circulares ni jurisprudencia. Si no estás seguro de una cita normativa exacta, escríbela como [verificar cita]. Si falta un dato clave (norma, hechos, RUT), márcalo como [completar].`},
  {k:'presentacion', lbl:'Presentación', max:2600, sys:`${ESTUDIO_BRIEF}\n\nRedacta el GUION/ESQUEMA de una PRESENTACIÓN profesional del estudio (para convertir a láminas) sobre la materia que indique el usuario. Estructura: portada (título + cliente + fecha); agenda; luego una lámina por sección con el formato "Lámina N — <título>" y 3-5 viñetas concisas; cierra con conclusiones/próximos pasos y una lámina de contacto del estudio. Si es una presentación de servicios/honorarios, refleja el alcance y la estructura de honorarios (UF, factura exenta de IVA). Marca datos faltantes como [completar].`},
  {k:'plan', lbl:'Plan de acción', max:2400, sys:`${ESTUDIO_BRIEF}\n\nRedacta un PLAN DE ACCIÓN / HOJA DE RUTA para la materia que indique el usuario, con la estructura del estudio:\n· Encabezado: "CONFIDENCIAL"; "Santiago, <fecha>"; destinatario/cliente; "Ref.: Plan de acción – <materia>".\n· "Objetivo": 1-2 frases con el resultado que se busca lograr.\n· "Etapas" numeradas (I, II, III…). Cada etapa con: un título; las acciones concretas (viñetas); el RESPONSABLE de cada acción (Estudio / Cliente / Notaría / SII / Conservador de Bienes Raíces / contador, según corresponda); y un PLAZO o hito estimado.\n· "Consideraciones legales y tributarias clave": requisitos, riesgos y contingencias a tener presentes.\n· "Próximos pasos inmediatos": las primeras 2-3 acciones para arrancar de inmediato.\n· Firma de un Socio (Cristóbal Liberona o Erasmo Escala), "Socio", "${BRAND.nombre}".\nSi falta un dato clave (plazos exactos, montos, normas), márcalo como [completar]. NO inventes cifras, plazos legales ni números de norma; si no estás seguro de una cita, escríbela como [verificar cita].`},
  {k:'minuta', lbl:'Minuta de reunión', max:1600, sys:`${ESTUDIO_BRIEF}\n\nRedacta una MINUTA DE REUNIÓN: encabezado (cliente, fecha, asistentes), puntos tratados numerados, acuerdos/decisiones y próximos pasos con responsables. Concisa y accionable.`},
  {k:'clausula', lbl:'Cláusula', max:1400, sys:`${ESTUDIO_BRIEF}\n\nRedacta la o las CLÁUSULAS contractuales que pida el usuario, precisas y ejecutables bajo derecho chileno. Si aporta valor, ofrece alternativas de redacción.`},
  {k:'correo', lbl:'Correo', max:1100, sys:`${ESTUDIO_BRIEF}\n\nRedacta un CORREO profesional (al cliente o contraparte) en el tono del estudio, claro y cordial. Empieza con "Asunto: ...".`},
]
// Biblioteca de cláusulas: categorías canónicas (la IA debe usar EXACTAMENTE una de estas al extraer).
const CATS_CLAUSULA = ['Confidencialidad','No competencia','Declaraciones y garantías','Honorarios y pago','Pacto de accionistas','Testamentos y sucesorio','Protocolo familiar','Indemnidad y responsabilidad','Resolución de conflictos','General']
// driveGet con auto-refresh: el provider_token de Google vence a la hora; si da 401, limpia el cacheado y reintenta con el de la sesión.
async function driveGetAuth(url){
  let token=await driveToken()
  try{ if(!token) throw new DriveAuthError(); return await driveGet(token,url) }
  catch(e){
    if(e&&e.code===401){
      try{ localStorage.removeItem('drive_token') }catch(_){}
      let t2=null; try{ t2=await getDriveToken() }catch(_){}
      if(t2){ try{ localStorage.setItem('drive_token',t2) }catch(_){}; return await driveGet(t2,url) }
    }
    throw (e&&e.code===401)?new DriveAuthError():e
  }
}
function AsistenteRedaccion({clients=[], sales=[], billing=[], clientEntities=[], onClose}){
  const [tipo,setTipo] = useState('propuesta')
  const isDesk = useIsDesktop()
  const [cliente,setCliente] = useState('')
  const [datos,setDatos] = useState('')
  const [draft,setDraft] = useState('')
  const [loading,setLoading] = useState(false)
  const [err,setErr] = useState(null)
  const [copiado,setCopiado] = useState(false)
  const [siiNov,setSiiNov] = useState([])   // radar SII (capa del BI) para cruzar memos/informes/presentaciones
  const [cruzarSii,setCruzarSii] = useState(true)
  const SII_TIPOS = ['memo','informe','presentacion','plan']
  useEffect(()=>{ supabase.from('sii_novedades').select('tipo,numero,titulo,areas,prioridad,resumen,brief,fecha,vigente').then(({data})=>setSiiNov((data||[]).filter(n=>n.vigente!==false)),()=>{}) },[])
  const [cruzarCliente,setCruzarCliente] = useState(true)
  const cliObj = (clients||[]).find(c=>c.name&&c.name.trim()===cliente.trim()) || (cliente.trim().length>=3 ? (clients||[]).find(c=>c.name&&(c.name||'').toLowerCase().includes(cliente.trim().toLowerCase())) : null)
  const perfilCliente = (c)=>{   // fuente única: ventaHistoricaUF + saldoBill (sin re-implementar fórmulas)
    const cid=c.id
    const rs=rsLabel(cid, clients, clientEntities)
    const ruts=[...new Set((clientEntities||[]).filter(e=>String(e.client_id)===String(cid)).map(e=>e.rut).filter(Boolean))]
    const vts=(sales||[]).filter(s=>String(s.client_id)===String(cid)&&!s.deleted_at&&['Activo','Terminado'].includes(s.status))
    const areas=[...new Set(vts.map(s=>s.area).filter(Boolean))]
    const encargos=[...new Set(vts.map(s=>s.title).filter(Boolean))].slice(0,6)
    const vendidoUF=ventaHistoricaUF(cid, sales)
    const porCobrar=(billing||[]).filter(b=>String(b.client_id)===String(cid)).reduce((a,b)=>a+saldoBill(b),0)
    const parts=[`Cliente: ${c.name}${rs&&rs!==c.name?` (RS: ${rs})`:''}.`]
    if(ruts.length) parts.push(`RUT: ${ruts.join(', ')}.`)
    if(areas.length) parts.push(`Áreas contratadas con el estudio: ${areas.join(', ')}.`)
    if(encargos.length) parts.push(`Encargos: ${encargos.join('; ')}.`)
    if(vendidoUF>0) parts.push(`Vendido histórico al estudio: ${fmtUF(vendidoUF)}.`)
    if(porCobrar>0) parts.push(`Saldo por cobrar actual: ${fmt(porCobrar)}.`)
    return parts.join(' ')
  }
  const [cliDocSel,setCliDocSel]=useState(null); const [cliDocTxt,setCliDocTxt]=useState(''); const [cliDocBusy,setCliDocBusy]=useState(false); const [cliDocErr,setCliDocErr]=useState(null); const [mostrarDocCli,setMostrarDocCli]=useState(false)
  const [cliFolder,setCliFolder]=useState(null); const [guardando,setGuardando]=useState(false); const [guardadoUrl,setGuardadoUrl]=useState(null); const [guardadoErr,setGuardadoErr]=useState(null)
  const usarDocCliente = async(file)=>{   // lee un documento de la carpeta del cliente y lo deja como contexto de la redacción
    setCliDocBusy(true); setCliDocErr(null)
    try{ const txt=(await leerDriveTextoSA(file)).slice(0,8000); setCliDocSel(file); setCliDocTxt(txt); setMostrarDocCli(false) }
    catch(e){ setCliDocErr(/No hay conexión|No autorizado|Failed to fetch|GOOGLE_OAUTH/i.test(e?.message||'')?'Conecta Drive desde el menú ☰ para leer el documento.':(e?.message||'No se pudo leer el documento.')) }
    setCliDocBusy(false)
  }
  const [precKw,setPrecKw]=useState(''); const [precBusy,setPrecBusy]=useState(false); const [precErr,setPrecErr]=useState(null)
  const [precFiles,setPrecFiles]=useState(null); const [precSel,setPrecSel]=useState(null); const [precTxt,setPrecTxt]=useState(''); const [precReading,setPrecReading]=useState(false)
  const [precFromIndex,setPrecFromIndex]=useState(false); const [idxBusy,setIdxBusy]=useState(false); const [idxMsg,setIdxMsg]=useState(null); const [precNeedAuth,setPrecNeedAuth]=useState(false)
  const [clauMode,setClauMode]=useState('usar'); const [clauLib,setClauLib]=useState(null); const [clauCat,setClauCat]=useState(''); const [clauKw,setClauKw]=useState(''); const [clauBusy,setClauBusy]=useState(false); const [clauDocs,setClauDocs]=useState(null); const [extrBusy,setExtrBusy]=useState(null); const [extrMsg,setExtrMsg]=useState(null)
  useEffect(()=>{ setPrecFiles(null); setPrecSel(null); setPrecTxt(''); setPrecErr(null) },[tipo])   // no arrastrar un precedente de otro tipo
  useEffect(()=>{ setCliDocSel(null); setCliDocTxt(''); setMostrarDocCli(false); setCliDocErr(null); setGuardadoUrl(null); setGuardadoErr(null)   // reset + busca la carpeta del cliente al cambiar
    let alive=true; if(!cliObj){ setCliFolder(null); return ()=>{alive=false} }
    if(cliObj.drive_folder_id){ setCliFolder({id:cliObj.drive_folder_id,name:cliObj.name}); return ()=>{alive=false} }   // carpeta de la ficha (fuente única)
    ;(async()=>{ try{ const {data}=await supabase.from('client_drive').select('folder_id,folder_name').eq('client_id',String(cliObj.id)).maybeSingle(); if(alive) setCliFolder(data&&data.folder_id?{id:data.folder_id,name:data.folder_name}:null) }catch(_){ if(alive) setCliFolder(null) } })()
    return ()=>{alive=false}
  },[cliObj&&cliObj.id])
  useEffect(()=>{ try{ const d=JSON.parse(localStorage.getItem('redaccion_draft')||'null'); if(d&&(Date.now()-(d.ts||0))<10*60*1000){ if(d.tipo)setTipo(d.tipo); if(d.cliente!=null)setCliente(d.cliente); if(d.datos!=null)setDatos(d.datos) } localStorage.removeItem('redaccion_draft') }catch(_){} },[])   // volver de Reconectar Drive sin perder lo escrito
  const MIMES_PREC="(mimeType='application/pdf' or mimeType='application/vnd.openxmlformats-officedocument.wordprocessingml.document' or mimeType='application/vnd.google-apps.document')"
  const manejarDriveErr = (e)=>{ const m=e?.message||''; if((e&&e.code===401)||/drive_auth|No hay conexión|No autorizado|GOOGLE_OAUTH|configurar|Failed to fetch|NetworkError|Error 40|Error 50/i.test(m)){ setPrecNeedAuth(true); setPrecErr(null) } else { setPrecErr(m||'No se pudo conectar con Drive.') } }
  const reconectarDrive = ()=>{ try{ localStorage.setItem('redaccion_draft', JSON.stringify({tipo,cliente,datos,ts:Date.now()})) }catch(_){}; connectDrivePermanente() }
  const buscarPrecLive = async()=>{   // Fase 1: búsqueda en vivo en el Drive (fallback si el índice está vacío/no existe)
    const folder = PREC_FOLDERS[tipo]; if(!folder) return
    const kw=(precKw.trim()||cliente.trim()).replace(/['\\]/g,' ').trim()
    const filt = kw ? ` and (fullText contains '${kw}' or name contains '${kw}')` : ''
    const q = `'${folder}' in parents and trashed=false and ${MIMES_PREC}${filt}`
    const data = await driveCall({action:'search', q, pageSize:20})
    setPrecFiles(data.files||[]); setPrecFromIndex(false)
  }
  const buscarPrec = async()=>{   // Fase 2: índice primero (instantáneo, ordenado por usos); si no hay, cae a la búsqueda en vivo
    if(!PREC_FOLDERS[tipo]||precBusy) return
    setPrecBusy(true); setPrecErr(null); setPrecNeedAuth(false); setPrecFiles(null)
    try{
      const kw=(precKw.trim()||cliente.trim()).toLowerCase()
      let rows=null
      try{
        const {data,error}=await supabase.from('precedentes_index').select('file_id,title,mime_type,modified_time,usos').eq('tipo',tipo).order('usos',{ascending:false}).order('modified_time',{ascending:false}).limit(300)
        if(!error&&data&&data.length) rows=data
      }catch(_){}
      if(rows){
        const mapped=rows.map(r=>({id:r.file_id,name:r.title,mimeType:r.mime_type,modifiedTime:r.modified_time,usos:r.usos}))
        const filt = kw ? mapped.filter(r=>(r.name||'').toLowerCase().includes(kw)) : mapped
        setPrecFiles(filt.slice(0,30)); setPrecFromIndex(true)
      } else {
        await buscarPrecLive()
      }
    }catch(e){ manejarDriveErr(e) }
    setPrecBusy(false)
  }
  const indexarPrecedentes = async()=>{   // recorre las carpetas-biblioteca y puebla precedentes_index (upsert, conserva usos)
    if(idxBusy) return
    setIdxBusy(true); setPrecErr(null); setPrecNeedAuth(false); setIdxMsg(null)
    try{
      let total=0
      for(const tp of Object.keys(PREC_FOLDERS)){
        const folder=PREC_FOLDERS[tp]; let pageToken=null
        do{
          const q=encodeURIComponent(`'${folder}' in parents and trashed=false and ${MIMES_PREC}`)
          const url=`https://www.googleapis.com/drive/v3/files?q=${q}&fields=nextPageToken,files(id,name,mimeType,modifiedTime)&orderBy=modifiedTime+desc&pageSize=100${pageToken?`&pageToken=${encodeURIComponent(pageToken)}`:''}`
          const data=await driveGetAuth(url)
          const rows=(data.files||[]).map(f=>({file_id:f.id,title:f.name,tipo:tp,mime_type:f.mimeType,modified_time:f.modifiedTime,updated_at:new Date().toISOString()}))
          if(rows.length){ const {error}=await supabase.from('precedentes_index').upsert(rows,{onConflict:'file_id'}); if(error) throw error; total+=rows.length }
          pageToken=data.nextPageToken||null
        } while(pageToken)
      }
      setIdxMsg(`Índice actualizado: ${total} documentos.`)
      await buscarPrec()
    }catch(e){ manejarDriveErr(e) }
    setIdxBusy(false)
  }
  const elegirPrec = async(file)=>{
    if(precReading) return
    setPrecReading(true); setPrecErr(null); setPrecNeedAuth(false)
    try{
      const txt = (await leerDriveTextoSA(file)).slice(0,7000)
      setPrecSel(file); setPrecTxt(txt)
      // aprende: el precedente que usas sube en el ranking (se ofrece primero la próxima vez)
      try{ if(precFromIndex&&file.usos!=null) await supabase.from('precedentes_index').update({usos:(file.usos||0)+1}).eq('file_id',file.id) }catch(e){registrarError({origen:'accion',vista:'precedentes_index',err:e})}
    }catch(e){ manejarDriveErr(e) }
    setPrecReading(false)
  }
  const cargarClausulas = async()=>{
    setClauBusy(true); setPrecErr(null)
    try{ const {data}=await supabase.from('clausulas').select('id,titulo,categoria,texto,usos').order('usos',{ascending:false}).order('titulo').limit(300); setClauLib(data||[]) }
    catch(_){ setClauLib([]) }
    setClauBusy(false)
  }
  useEffect(()=>{ if(tipo==='clausula'&&clauLib===null) cargarClausulas() },[tipo])   // carga la biblioteca al entrar a Cláusula
  const usarClausula = (c)=>{ setPrecSel({name:c.titulo}); setPrecTxt(c.texto||''); try{ supabase.from('clausulas').update({usos:(c.usos||0)+1}).eq('id',c.id) }catch(e){registrarError({origen:'accion',vista:'clausulas',err:e})} }
  const buscarDocClausula = async()=>{
    if(clauBusy) return
    setClauBusy(true); setPrecErr(null); setPrecNeedAuth(false); setExtrMsg(null); setClauDocs(null)
    try{
      const kw=(clauKw.trim()||cliente.trim()).replace(/['\\]/g,' ').trim()
      if(!kw) throw new Error('Escribe qué documento buscar (cliente, materia…).')
      const q=`trashed=false and (fullText contains '${kw}' or name contains '${kw}') and ${MIMES_PREC}`
      const data=await driveCall({action:'search', q, pageSize:20})
      setClauDocs(data.files||[])
    }catch(e){ manejarDriveErr(e) }
    setClauBusy(false)
  }
  const extraerClausulas = async(file)=>{
    if(extrBusy) return
    setExtrBusy(file.id); setPrecErr(null); setExtrMsg(null)
    try{
      const txt = await leerDriveTextoSA(file)
      if(!txt||txt.length<200) throw new Error('El documento no tiene texto suficiente.')
      const sys = `Eres abogado chileno. Del documento legal extrae las CLÁUSULAS REUTILIZABLES (no los datos del caso). Devuelve SOLO un JSON array, sin markdown ni backticks, de objetos {titulo, categoria, texto}. titulo: nombre corto de la cláusula. categoria: EXACTAMENTE una de: ${CATS_CLAUSULA.join(' | ')}. texto: la cláusula redactada de forma reutilizable, reemplazando nombres/RUT/montos/fechas específicos del caso por marcadores [PARTE], [SOCIEDAD], [MONTO], [PLAZO], [FECHA]; conserva la redacción jurídica. Omite recitales y datos puramente del caso. Máximo 12 cláusulas.`
      const data = await claudeCall({model:'claude-opus-4-8',max_tokens:3500,system:sys,messages:[{role:'user',content:txt.slice(0,14000)}]})
      const out = data?.content?.[0]?.text||''
      const m = out.match(/\[[\s\S]*\]/); let arr=[]; try{ arr = m?JSON.parse(m[0]):[] }catch(_){ arr=[] }
      const rows = (Array.isArray(arr)?arr:[]).filter(c=>c&&c.titulo&&c.texto).map(c=>{ const cat=CATS_CLAUSULA.includes(c.categoria)?c.categoria:'General'; return { clave:`${cat}::${String(c.titulo).slice(0,80)}`.toLowerCase(), titulo:String(c.titulo).slice(0,120), categoria:cat, texto:String(c.texto), fuente:file.name, file_id:file.id, updated_at:new Date().toISOString() } })
      if(!rows.length) throw new Error('No se encontraron cláusulas reutilizables en ese documento.')
      const {error}=await supabase.from('clausulas').upsert(rows,{onConflict:'clave'}); if(error) throw error
      setExtrMsg(`${rows.length} cláusulas guardadas desde "${file.name}".`); await cargarClausulas()
    }catch(e){ if(e&&(e.code===401||/drive_auth/.test(e.message||''))) setPrecNeedAuth(true); else setPrecErr(e?.message||'No se pudo extraer.') }
    setExtrBusy(null)
  }
  const generar = async()=>{
    if(!datos.trim()||loading) return
    setLoading(true); setErr(null)
    try{
      const t=TIPOS_REDACCION.find(x=>x.k===tipo)
      const hoy=new Date().toLocaleDateString('es-CL',{day:'numeric',month:'long',year:'numeric'})
      let content=`Fecha de hoy: ${hoy}.\n${cliente.trim()?`Destinatario/cliente: ${cliente.trim()}\n`:''}Datos e instrucciones para el documento:\n${datos.trim()}`
      if(cruzarCliente&&cliObj){ content+=`\n\nPERFIL DEL CLIENTE (de nuestra base de datos; úsalo para contextualizar y personalizar, no lo recites textual): ${perfilCliente(cliObj)}` }
      if(cruzarSii&&SII_TIPOS.includes(tipo)&&siiNov.length){
        const PRIO={alta:3,media:2,baja:1}
        const digest=siiNov.slice().sort((a,b)=>(PRIO[b.prioridad]||0)-(PRIO[a.prioridad]||0)).slice(0,18).map(n=>`- ${`${(n.tipo||'').toUpperCase()} ${n.numero||''}`.trim()}: ${n.titulo}${n.areas&&n.areas.length?` (áreas: ${n.areas.join('/')})`:''}${(n.brief||n.resumen)?` — ${(n.brief||n.resumen).slice(0,160)}`:''}`).join('\n')
        content+=`\n\nRADAR SII VIGENTE DEL ESTUDIO (contexto normativo actual, del módulo BI). Incorpora y CITA (tipo N° número) SOLO las novedades realmente pertinentes a este documento; ignora las que no apliquen. No inventes citas fuera de esta lista ni de la ley aplicable:\n${digest}`
      }
      if(precTxt&&precSel){ content+=`\n\nPRECEDENTE DEL ESTUDIO (documento real "${precSel.name}"): sigue su ESTRUCTURA, tono y cláusulas como modelo, pero ADAPTA todo al caso actual — NO copies datos, montos ni nombres del precedente.\n---\n${precTxt}\n---` }
      if(cliDocTxt&&cliDocSel){ content+=`\n\nDOCUMENTO DEL CLIENTE ("${cliDocSel.name}", de su carpeta en Drive): úsalo como fuente de datos y contexto REAL de este caso (partes, RUT, montos, fechas, cláusulas). Extrae lo pertinente; no lo copies textual.\n---\n${cliDocTxt}\n---` }
      const data=await claudeCall({model:'claude-opus-4-8',max_tokens:t.max,system:t.sys,messages:[{role:'user',content}]})
      setDraft(data?.content?.[0]?.text||'(sin respuesta)')
      logActividad('redaccion.generado',{detalle:{title:(TIPOS_REDACCION.find(t=>t.k===tipo)?.lbl||tipo),name:cliente||null}})
    }catch(e){ setErr(e?.message||'No se pudo generar.') }
    setLoading(false)
  }
  const copiar = ()=>{ try{ navigator.clipboard.writeText(draft); setCopiado(true); setTimeout(()=>setCopiado(false),1500) }catch(_){} }
  const mdToHtml = (md)=>{   // markdown del borrador → HTML para Word (.doc)
    const esc = s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    const inline = s=>{ let x=esc(s); x=x.replace(/\*\*([^*]+)\*\*/g,'<b>$1</b>'); x=x.replace(/\*([^*\n]+)\*/g,'<i>$1</i>'); return x }
    let html='', inUl=false, inOl=false
    const close=()=>{ if(inUl){html+='</ul>';inUl=false} if(inOl){html+='</ol>';inOl=false} }
    for(const raw of String(md||'').split('\n')){
      const l=raw.replace(/\s+$/,''); let m
      if(/^\s*---+\s*$/.test(l)){ close(); html+='<hr/>'; continue }
      if(m=l.match(/^###\s+(.*)/)){ close(); html+='<h3>'+inline(m[1])+'</h3>'; continue }
      if(m=l.match(/^##\s+(.*)/)){ close(); html+='<h2>'+inline(m[1])+'</h2>'; continue }
      if(m=l.match(/^#\s+(.*)/)){ close(); html+='<h1>'+inline(m[1])+'</h1>'; continue }
      if(m=l.match(/^\s*[-*•]\s+(.*)/)){ if(inOl){html+='</ol>';inOl=false} if(!inUl){html+='<ul>';inUl=true} html+='<li>'+inline(m[1])+'</li>'; continue }
      if(m=l.match(/^\s*\d+[.)]\s+(.*)/)){ if(inUl){html+='</ul>';inUl=false} if(!inOl){html+='<ol>';inOl=true} html+='<li>'+inline(m[1])+'</li>'; continue }
      if(l.trim()===''){ close(); html+='<p></p>'; continue }
      close(); html+='<p>'+inline(l)+'</p>'
    }
    close(); return html
  }
  const parseSlides = (md)=>{   // "Lámina N — título" / "## título" delimitan láminas; viñetas y párrafos van al cuerpo
    const isTitle = l => /^#{1,3}\s+\S/.test(l) || /^#{0,3}\s*L[áa]mina\b/i.test(l)
    const clean = s => s.replace(/^#{1,3}\s+/,'').replace(/^#{0,3}\s*L[áa]mina\s*\d*\s*[—–:.-]*\s*/i,'').replace(/\*\*/g,'').replace(/\*/g,'').trim()
    const slides=[]; let cur=null
    for(const raw of String(md||'').split('\n')){
      const l=raw.replace(/\s+$/,''); if(!l.trim()||/^\s*---+\s*$/.test(l)) continue
      if(isTitle(l)){ cur={title:clean(l),bullets:[]}; slides.push(cur); continue }
      const b=l.replace(/^\s*[-*•]\s+/,'').replace(/\*\*/g,'').replace(/\*/g,'').trim()
      if(!cur){ cur={title:b,bullets:[]}; slides.push(cur); continue }
      cur.bullets.push(b)
    }
    return slides.filter(s=>s.title||s.bullets.length)
  }
  const descargarPPTX = async()=>{
    logActividad('redaccion.pptx',{detalle:{title:(TIPOS_REDACCION.find(t=>t.k===tipo)?.lbl||tipo),name:cliente||null}})
    if(!draft) return
    const P = (await import('https://cdn.jsdelivr.net/npm/pptxgenjs@3.12.0/+esm')).default
    const pptx = new P(); pptx.layout='LAYOUT_WIDE'
    const NAVY='003C50', GRAF='3D3D3D'
    parseSlides(draft).forEach((s,i)=>{
      const sl=pptx.addSlide()
      sl.addText(s.title||'', {x:0.6,y:0.5,w:12,h:1,fontSize:i===0?30:22,bold:true,color:NAVY,fontFace:'Calibri'})
      if(s.bullets.length) sl.addText(s.bullets.map(b=>({text:b,options:{bullet:true,fontSize:16,color:GRAF,paraSpaceAfter:8}})),{x:0.9,y:1.7,w:11.5,h:5.3,fontFace:'Calibri',valign:'top'})
    })
    const fn=(`Presentación${cliente.trim()?' - '+cliente.trim():''}`).replace(/[^\w\sáéíóúñÁÉÍÓÚÑ.\-]/g,'').trim()||'Presentación'
    await pptx.writeFile({fileName:fn+'.pptx'})
  }
  const descargarWord = ()=>{
    logActividad('redaccion.word',{detalle:{title:(TIPOS_REDACCION.find(t=>t.k===tipo)?.lbl||tipo),name:cliente||null}})
    if(!draft) return
    const t=TIPOS_REDACCION.find(x=>x.k===tipo)
    const html=`<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'><head><meta charset='utf-8'><style>@page{margin:2.5cm} body{font-family:Calibri,Arial,sans-serif;font-size:11pt;color:#1a1a1a;line-height:1.45} h1{font-size:15pt;margin:14pt 0 6pt} h2{font-size:13pt;margin:12pt 0 5pt} h3{font-size:12pt;margin:10pt 0 4pt} p{margin:0 0 8pt} ul,ol{margin:0 0 8pt 18pt} hr{border:none;border-top:1px solid #999;margin:10pt 0}</style></head><body>${mdToHtml(draft)}</body></html>`
    const blob=new Blob(['﻿',html],{type:'application/msword'})
    const url=URL.createObjectURL(blob)
    const fn=(`${t?.lbl||'Documento'}${cliente.trim()?' - '+cliente.trim():''}`).replace(/[^\w\sáéíóúñÁÉÍÓÚÑ.\-]/g,'').trim()||'Documento'
    const a=document.createElement('a'); a.href=url; a.download=fn+'.doc'; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),1500)
  }
  const guardarEnDrive = async()=>{
    if(!draft||!cliFolder||guardando) return
    setGuardando(true); setGuardadoUrl(null); setGuardadoErr(null)
    try{
      const t=TIPOS_REDACCION.find(x=>x.k===tipo)
      const html=`<html><head><meta charset='utf-8'></head><body style="font-family:Calibri,Arial,sans-serif;font-size:11pt;color:#1a1a1a">${mdToHtml(draft)}</body></html>`
      const name=(`${t?.lbl||'Documento'}${cliente.trim()?' - '+cliente.trim():''}`).replace(/[^\w\sáéíóúñÁÉÍÓÚÑ.\-]/g,'').trim()||'Documento'
      const d=await driveCall({action:'upload', folderId:cliFolder.id, name, html})
      setGuardadoUrl(d.url||null)
      logActividad('redaccion.drive',{detalle:{title:(TIPOS_REDACCION.find(t=>t.k===tipo)?.lbl||tipo),name:cliente||null}})
    }catch(e){ const m=e?.message||''; setGuardadoErr(/No hay conexión|No autorizado|Failed to fetch|GOOGLE_OAUTH/i.test(m)?'Conecta Drive desde el menú ☰ para guardar.':(m||'No se pudo guardar en Drive.')) }
    setGuardando(false)
  }
  const inp = {width:'100%',border:`1px solid ${C.border}`,borderRadius:8,padding:'9px 11px',fontSize:13,color:C.text,outline:'none',boxSizing:'border-box',fontFamily:'inherit'}
  return (
    <div style={{padding:'2px 2px 6px',...(isDesk?{display:'flex',alignItems:'flex-start',gap:18}:{})}}>
    <div style={isDesk?{width:420,flexShrink:0}:undefined}>
      <div style={{fontSize:11,color:C.muted,marginBottom:12,lineHeight:1.5}}>La IA redacta en el formato de la oficina. <b>Tú validas y editas</b> antes de usarlo — nada se envía solo.</div>
      <div style={{display:'flex',flexWrap:'wrap',gap:6,marginBottom:12}}>
        {TIPOS_REDACCION.map(t=>(<button key={t.k} onClick={()=>setTipo(t.k)} style={{fontSize:12,fontWeight:600,padding:'5px 12px',borderRadius:20,border:`1px solid ${tipo===t.k?C.accent:C.border}`,background:tipo===t.k?C.azulBg:'#fff',color:tipo===t.k?C.accent:C.muted,cursor:'pointer'}}>{t.lbl}</button>))}
      </div>
      <input value={cliente} onChange={e=>setCliente(e.target.value)} placeholder='Cliente / destinatario (opcional)' style={{...inp,marginBottom:8}} list='red-cli'/>
      <datalist id='red-cli'>{(clients||[]).map(c=><option key={c.id} value={c.name}/>)}</datalist>
      <textarea value={datos} onChange={e=>setDatos(e.target.value)} placeholder='Datos e instrucciones: de qué se trata, alcance, honorarios (UF), hechos clave…' rows={4} style={{...inp,resize:'vertical',marginBottom:10}}/>
      {cliObj&&(
        <label style={{display:'flex',alignItems:'center',gap:7,fontSize:12,color:C.muted,margin:'0 2px 10px',cursor:'pointer'}}>
          <input type='checkbox' checked={cruzarCliente} onChange={e=>setCruzarCliente(e.target.checked)} style={{accentColor:C.accent,width:15,height:15}}/>
          Cruzar con la ficha de <span style={{color:C.azulInfo,fontWeight:600,margin:'0 3px'}}>{cliObj.name}</span> (ventas, áreas, por cobrar)
        </label>
      )}
      {cliObj&&(cliDocSel&&cliDocTxt
        ? <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',fontSize:11,color:C.normal,margin:'0 2px 10px'}}><span>Con documento del cliente: <b>{cliDocSel.name}</b></span><button type='button' onClick={()=>{setCliDocSel(null);setCliDocTxt('')}} style={{fontSize:10,color:C.azulInfo,background:'none',border:'none',cursor:'pointer',padding:0}}>Quitar</button></div>
        : <div style={{margin:'0 2px 10px'}}>
            <button type='button' onClick={()=>setMostrarDocCli(v=>!v)} style={{fontSize:12,color:C.azulInfo,background:'none',border:'none',cursor:'pointer',padding:0}}>{mostrarDocCli?'Ocultar documentos':`+ Traer un documento de ${cliObj.name}`}</button>
            {cliDocBusy&&<div style={{fontSize:11,color:C.muted,marginTop:6}}>Leyendo el documento…</div>}
            {cliDocErr&&<div style={{fontSize:11,color:C.overdueText,marginTop:6}}>{cliDocErr}</div>}
            {mostrarDocCli&&!cliDocBusy&&<div style={{border:`1px solid ${C.border}`,borderRadius:10,padding:'9px 10px',marginTop:6}}><DocumentosDrive client={cliObj} onPick={usarDocCliente}/></div>}
          </div>
      )}
      {SII_TIPOS.includes(tipo)&&siiNov.length>0&&(
        <label style={{display:'flex',alignItems:'center',gap:7,fontSize:12,color:C.muted,margin:'0 2px 10px',cursor:'pointer'}}>
          <input type='checkbox' checked={cruzarSii} onChange={e=>setCruzarSii(e.target.checked)} style={{accentColor:C.accent,width:15,height:15}}/>
          Cruzar con el radar SII de la oficina <span style={{color:C.azulInfo,fontWeight:600}}>({siiNov.length} novedades vigentes)</span>
        </label>
      )}
      {PREC_FOLDERS[tipo]&&(
        <div style={{border:`1px solid ${C.border}`,borderRadius:10,padding:'9px 10px',margin:'0 0 10px'}}>
          <div style={{display:'flex',gap:6,alignItems:'center'}}>
            <input value={precKw} onChange={e=>setPrecKw(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();buscarPrec()}}} placeholder='Precedentes en tu Drive (cliente, tema…)' style={{...inp,flex:1,padding:'6px 9px',fontSize:12,marginBottom:0}}/>
            <button type='button' onClick={buscarPrec} disabled={precBusy} style={{fontSize:12,fontWeight:600,color:'#fff',background:precBusy?C.done:C.muted,border:'none',borderRadius:8,padding:'7px 11px',cursor:'pointer',whiteSpace:'nowrap'}}>{precBusy?'Buscando…':'Buscar'}</button>
          </div>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginTop:5}}>
            <span style={{fontSize:10,color:C.muted}}>{precFromIndex?'desde tu índice':precFiles?'búsqueda en vivo':''}</span>
            <button type='button' onClick={indexarPrecedentes} disabled={idxBusy} style={{fontSize:10,color:C.azulInfo,background:'none',border:'none',cursor:'pointer',padding:0}}>{idxBusy?'Indexando…':'↻ Indexar Drive'}</button>
          </div>
          {idxMsg&&<div style={{fontSize:10,color:C.normal,marginTop:3}}>{idxMsg}</div>}
          {precNeedAuth&&<div style={{fontSize:11,color:C.text,marginTop:7,background:C.ambarBg,borderRadius:8,padding:'7px 9px',lineHeight:1.4}}>Tu acceso a Drive expiró. <button type='button' onClick={reconectarDrive} style={{fontSize:11,fontWeight:700,color:C.accent,background:'none',border:'none',cursor:'pointer',padding:0,textDecoration:'underline'}}>Reconectar Drive</button> <span style={{color:C.muted}}>— te lleva a Google y vuelve; guardamos lo que escribiste.</span></div>}
          {precErr&&<div style={{fontSize:11,color:C.overdueText,marginTop:6}}>{precErr}</div>}
          {precFiles&&precFiles.length===0&&<div style={{fontSize:11,color:C.muted,marginTop:6}}>Sin resultados en la carpeta.</div>}
          {precFiles&&precFiles.length>0&&(
            <div style={{display:'flex',flexDirection:'column',gap:4,maxHeight:170,overflowY:'auto',marginTop:7}}>
              {precFiles.map(f=>{ const sel=precSel&&precSel.id===f.id; return (
                <button key={f.id} type='button' onClick={()=>elegirPrec(f)} disabled={precReading} style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8,padding:'6px 9px',borderRadius:8,border:`1px solid ${sel?C.accent:C.border}`,background:sel?C.azulBg:'#fff',cursor:'pointer',textAlign:'left'}}>
                  <span style={{fontSize:12,fontWeight:sel?700:500,color:sel?C.accent:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{sel?<><Gl n='tick'/>{" "}</>:''}{f.name}</span>
                  <span style={{fontSize:10,color:C.muted,flexShrink:0}}>{fmtFechaDMY(isoLocal(f.modifiedTime))}</span>
                </button>
              )})}
            </div>
          )}
          {precReading&&<div style={{fontSize:11,color:C.muted,marginTop:6}}>Leyendo el documento…</div>}
          {precSel&&precTxt&&!precReading&&<div style={{fontSize:11,color:C.normal,marginTop:6}}>Usando de base: <b>{precSel.name}</b></div>}
        </div>
      )}
      {tipo==='clausula'&&(
        <div style={{border:`1px solid ${C.border}`,borderRadius:10,padding:'9px 10px',margin:'0 0 10px'}}>
          <div style={{display:'flex',gap:6,marginBottom:8}}>
            {[['usar','Usar guardadas'],['extraer','Extraer de un documento']].map(([k,l])=>(<button key={k} type='button' onClick={()=>setClauMode(k)} style={{fontSize:12,fontWeight:600,padding:'4px 10px',borderRadius:8,border:`1px solid ${clauMode===k?C.accent:C.border}`,background:clauMode===k?C.azulBg:'#fff',color:clauMode===k?C.accent:C.muted,cursor:'pointer'}}>{l}</button>))}
          </div>
          {clauMode==='usar'?(
            <>
              <div style={{display:'flex',flexWrap:'wrap',gap:4,marginBottom:7}}>
                {['',...CATS_CLAUSULA].map(cat=>(<button key={cat||'todas'} type='button' onClick={()=>setClauCat(cat)} style={{fontSize:10,fontWeight:600,padding:'2px 8px',borderRadius:20,border:`1px solid ${clauCat===cat?C.accent:C.border}`,background:clauCat===cat?C.azulBg:'#fff',color:clauCat===cat?C.accent:C.muted,cursor:'pointer'}}>{cat||'Todas'}</button>))}
              </div>
              <input value={clauKw} onChange={e=>setClauKw(e.target.value)} placeholder='Buscar en tus cláusulas…' style={{...inp,padding:'6px 9px',fontSize:12,marginBottom:7}}/>
              {clauLib===null?<div style={{fontSize:11,color:C.muted}}>Cargando…</div>:(()=>{ const f=(clauLib||[]).filter(c=>(!clauCat||c.categoria===clauCat)&&(!clauKw.trim()||((c.titulo||'')+' '+(c.texto||'')).toLowerCase().includes(clauKw.toLowerCase()))); return f.length?(
                <div style={{display:'flex',flexDirection:'column',gap:4,maxHeight:200,overflowY:'auto'}}>{f.slice(0,40).map(c=>{ const sel=precSel&&precSel.name===c.titulo; return (
                  <button key={c.id} type='button' onClick={()=>usarClausula(c)} style={{textAlign:'left',padding:'6px 9px',borderRadius:8,border:`1px solid ${sel?C.accent:C.border}`,background:sel?C.azulBg:'#fff',cursor:'pointer'}}>
                    <div style={{fontSize:12,fontWeight:600,color:sel?C.accent:C.text}}>{sel?<><Gl n='tick'/>{" "}</>:''}{c.titulo} <span style={{fontSize:9,fontWeight:600,color:C.muted}}>· {c.categoria}</span></div>
                    <div style={{fontSize:10,color:C.muted,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{c.texto}</div>
                  </button>)})}</div>
              ):<div style={{fontSize:11,color:C.muted}}>Sin cláusulas guardadas{clauCat?` en ${clauCat}`:''}. Usa "Extraer de un documento".</div> })()}
            </>
          ):(
            <>
              <div style={{display:'flex',gap:6}}>
                <input value={clauKw} onChange={e=>setClauKw(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();buscarDocClausula()}}} placeholder='Documento del Drive (cliente, materia…)' style={{...inp,flex:1,padding:'6px 9px',fontSize:12,marginBottom:0}}/>
                <button type='button' onClick={buscarDocClausula} disabled={clauBusy} style={{fontSize:12,fontWeight:600,color:'#fff',background:clauBusy?C.done:C.muted,border:'none',borderRadius:8,padding:'7px 11px',cursor:'pointer'}}>{clauBusy?'…':'Buscar'}</button>
              </div>
              {clauDocs&&clauDocs.length>0&&<div style={{display:'flex',flexDirection:'column',gap:4,maxHeight:170,overflowY:'auto',marginTop:7}}>{clauDocs.map(f=>(
                <div key={f.id} style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:8,padding:'6px 9px',borderRadius:8,border:`1px solid ${C.border}`}}>
                  <span style={{fontSize:12,color:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{f.name}</span>
                  <button type='button' onClick={()=>extraerClausulas(f)} disabled={!!extrBusy} style={{fontSize:10,fontWeight:700,color:C.accent,background:'none',border:`1px solid ${C.accent}`,borderRadius:6,padding:'3px 8px',cursor:'pointer',whiteSpace:'nowrap'}}>{extrBusy===f.id?'Extrayendo…':'Extraer'}</button>
                </div>))}</div>}
              {clauDocs&&clauDocs.length===0&&<div style={{fontSize:11,color:C.muted,marginTop:6}}>Sin resultados.</div>}
              {extrMsg&&<div style={{fontSize:10,color:C.normal,marginTop:6}}>{extrMsg}</div>}
            </>
          )}
          {precNeedAuth&&<div style={{fontSize:11,color:C.text,marginTop:7,background:C.ambarBg,borderRadius:8,padding:'7px 9px',lineHeight:1.4}}>Tu acceso a Drive expiró. <button type='button' onClick={reconectarDrive} style={{fontSize:11,fontWeight:700,color:C.accent,background:'none',border:'none',cursor:'pointer',padding:0,textDecoration:'underline'}}>Reconectar Drive</button></div>}
          {precErr&&<div style={{fontSize:11,color:C.overdueText,marginTop:6}}>{precErr}</div>}
          {precSel&&precTxt&&clauMode==='usar'&&<div style={{fontSize:11,color:C.normal,marginTop:6}}>Redactando sobre: <b>{precSel.name}</b></div>}
        </div>
      )}
      <button onClick={generar} disabled={loading||!datos.trim()} style={{width:'100%',height:44,background:(loading||!datos.trim())?C.done:C.accent,color:'#fff',border:'none',borderRadius:10,fontSize:13,fontWeight:600,cursor:(loading||!datos.trim())?'default':'pointer'}}>{loading?'Redactando…':<><Sparkle/> Generar borrador</>}</button>
      {err&&<div style={{fontSize:11,color:C.overdueText,marginTop:8}}>{err}</div>}
    </div>
    <div style={isDesk?{flex:1,minWidth:0,display:'flex',flexDirection:'column',gap:12}:{marginTop:14,display:'flex',flexDirection:'column',gap:12}}>
      {!draft&&isDesk&&<div style={{border:`1px dashed ${C.border}`,borderRadius:12,padding:'40px 20px',textAlign:'center',fontSize:12.5,color:C.muted}}>{loading?'Redactando…':'El borrador aparece aquí. Tú validas y editas antes de usarlo.'}</div>}
      {draft&&<div>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:6}}>
          <span style={{fontSize:10,fontWeight:700,color:C.muted,textTransform:'uppercase',letterSpacing:.4}}>Borrador · edítalo</span>
          <div style={{display:'flex',gap:8}}>
            <button onClick={generar} disabled={loading} style={{fontSize:11,color:C.muted,background:'none',border:`1px solid ${C.border}`,borderRadius:8,padding:'3px 9px',cursor:'pointer'}}>Regenerar</button>
            {tipo==='presentacion'&&<button onClick={descargarPPTX} style={{fontSize:11,color:C.muted,background:'none',border:`1px solid ${C.border}`,borderRadius:8,padding:'3px 9px',cursor:'pointer'}}>PPTX</button>}
            <button onClick={descargarWord} style={{fontSize:11,color:C.muted,background:'none',border:`1px solid ${C.border}`,borderRadius:8,padding:'3px 9px',cursor:'pointer'}}>Word</button>
            <button onClick={copiar} style={{fontSize:11,color:'#fff',background:C.accent,border:'none',borderRadius:8,padding:'3px 11px',cursor:'pointer'}}>{copiado?<>Copiado{" "}<Gl n='tick'/></>:'Copiar'}</button>
          </div>
        </div>
        <textarea value={draft} onChange={e=>setDraft(e.target.value)} rows={isDesk?26:16} style={{...inp,resize:'vertical',fontSize:13,lineHeight:1.5}}/>
        {cliFolder&&<div style={{marginTop:8,display:'flex',alignItems:'center',gap:10,flexWrap:'wrap'}}>
          <button type='button' onClick={guardarEnDrive} disabled={guardando} style={{fontSize:11,fontWeight:600,color:'#fff',background:guardando?C.done:C.accent,border:'none',borderRadius:8,padding:'5px 11px',cursor:guardando?'default':'pointer'}}>{guardando?'Guardando…':`Guardar en la carpeta de ${cliFolder.name}`}</button>
          {guardadoUrl&&<a href={guardadoUrl} target='_blank' rel='noopener' style={{fontSize:11,color:C.normal,fontWeight:600}}>Guardado <Gl n='tick'/> · abrir en Drive</a>}
          {guardadoErr&&<span style={{fontSize:11,color:C.overdueText}}>{guardadoErr}</span>}
        </div>}
      </div>}
      <BitacoraLista prefijo='redaccion.' titulo='Redactados' etiquetas={{'redaccion.generado':'Borrador generado','redaccion.word':'Descargado en Word','redaccion.pptx':'Descargado en PPTX','redaccion.drive':'Guardado en el Drive del cliente'}} limite={8}/>
    </div>
    </div>
  )
}
// Calendario de plazos y obligaciones: extrae de un contrato del Drive (IA) y los agenda por urgencia.
const PLAZO_TIPO_COL = { 'plazo':C.azulInfo, 'obligación':C.soonText||C.soon, 'hito':C.normal }
function PlazosModal({clients=[], onClose, onOpenClientFicha}){
  const [rows,setRows]=useState(null)
  const isDesk=useIsDesktop()
  const [cliente,setCliente]=useState('')
  const cliObj=(clients||[]).find(c=>c.name&&c.name.trim()===cliente.trim())||(cliente.trim().length>=3?(clients||[]).find(c=>c.name&&(c.name||'').toLowerCase().includes(cliente.trim().toLowerCase())):null)
  const [mostrarPicker,setMostrarPicker]=useState(false)
  const [extBusy,setExtBusy]=useState(false); const [extErr,setExtErr]=useState(null)
  const [extracted,setExtracted]=useState(null); const [saving,setSaving]=useState(false)
  const [openB,setOpenB]=useState(()=>new Set(['vencidos','prox']))
  const [mManual,setMManual]=useState(false); const [mF,setMF]=useState({titulo:'',fecha:'',tipo:'plazo'}); const [mSaving,setMSaving]=useState(false)
  const togB=k=>setOpenB(p=>{const s=new Set(p); s.has(k)?s.delete(k):s.add(k); return s})
  const cargar=async()=>{ try{ const {data}=await supabase.from('plazos').select('*').order('fecha',{ascending:true,nullsFirst:false}); setRows(data||[]) }catch(_){ setRows([]) } }
  useEffect(()=>{ cargar() },[])
  const cn=id=>clients.find(c=>String(c.id)===String(id))?.name||''
  const fmtF=f=>{ try{ return fmtFechaDMY(f) }catch(_){ return f||'' } }
  const extraerPlazos=async(file)=>{
    setExtBusy(true); setExtErr(null); setMostrarPicker(false)
    try{
      const txt=(await leerDriveTextoSA(file)).slice(0,14000)
      if(!txt||txt.length<100) throw new Error('El documento no tiene texto suficiente.')
      const sys=`Eres abogado chileno. Del documento extrae los PLAZOS, VENCIMIENTOS y OBLIGACIONES con relevancia de agenda (renovaciones, hitos, obligaciones periódicas, vencimientos, prescripciones). Devuelve SOLO un JSON array, sin markdown, de {titulo, fecha, descripcion, tipo}. fecha en formato YYYY-MM-DD SOLO si es una fecha cierta; si es relativa ("30 días desde la firma") o no hay fecha, deja fecha="" y explícalo en descripcion. tipo = una de: plazo | obligación | hito. NO inventes fechas.`
      const data=await claudeCall({model:'claude-opus-4-8',max_tokens:2500,system:sys,messages:[{role:'user',content:txt}]})
      const out=data?.content?.[0]?.text||''; const m=out.match(/\[[\s\S]*\]/); let arr=[]; try{ arr=m?JSON.parse(m[0]):[] }catch(_){ arr=[] }
      const items=(Array.isArray(arr)?arr:[]).filter(x=>x&&x.titulo).map(x=>({titulo:String(x.titulo).slice(0,200), fecha:/^\d{4}-\d{2}-\d{2}$/.test(x.fecha||'')?x.fecha:null, descripcion:String(x.descripcion||''), tipo:['plazo','obligación','hito'].includes(x.tipo)?x.tipo:'plazo'}))
      if(!items.length) throw new Error('No encontré plazos u obligaciones en ese documento.')
      setExtracted({file,items})
    }catch(e){ setExtErr(/No hay conexión|Failed to fetch|No autorizado|GOOGLE_OAUTH/i.test(e?.message||'')?'Conecta Drive desde el menú ☰ para leer el documento.':(e?.message||'No se pudo extraer.')) }
    setExtBusy(false)
  }
  const guardarExtraidos=async()=>{
    if(!extracted||!cliObj||saving) return
    setSaving(true); setExtErr(null)
    try{
      const ins=extracted.items.map(x=>({client_id:String(cliObj.id),titulo:x.titulo,descripcion:x.descripcion||null,tipo:x.tipo,fecha:x.fecha,fuente:extracted.file.name,file_id:extracted.file.id}))
      const {error}=await supabase.from('plazos').insert(ins); if(error) throw error
      logActividad('plazos.extraidos',{detalle:{name:cliObj.name,title:`${ins.length} plazos de ${extracted.file.name}`}})
      setExtracted(null); await cargar()
    }catch(e){ setExtErr(/relation .*plazos.*does not exist|Could not find the table/i.test(e?.message||'')?'Falta crear la tabla: corre docs/sql_plazos.sql en Supabase.':(e?.message||'No se pudo guardar.')) }
    setSaving(false)
  }
  const marcar=async(p)=>{ const nv=p.estado==='cumplido'?'pendiente':'cumplido'; try{ if(!okDB(await supabase.from('plazos').update({estado:nv}).eq('id',p.id),'actualizar el plazo')) return; logActividad(nv==='cumplido'?'plazos.cumplido':'plazos.reabierto',{tabla:'plazos',id:p.id,detalle:{title:p.titulo,name:cn(p.client_id)}}) }catch(e){registrarError({origen:'accion',vista:'plazos',err:e})}; setRows(rs=>(rs||[]).map(x=>x.id===p.id?{...x,estado:nv}:x)) }
  const borrar=async(p)=>{ if(!(await appConfirm('¿Borrar este plazo?'))) return; try{ if(!okDB(await supabase.from('plazos').delete().eq('id',p.id),'borrar el plazo')) return; logActividad('plazos.borrado',{detalle:{title:p.titulo,name:cn(p.client_id)}}) }catch(e){registrarError({origen:'accion',vista:'plazos',err:e})}; setRows(rs=>(rs||[]).filter(x=>x.id!==p.id)) }
  const agregarManual=async()=>{
    if(!mF.titulo.trim()||mSaving) return
    setMSaving(true); setExtErr(null)
    try{
      const {error}=await supabase.from('plazos').insert({client_id:cliObj?String(cliObj.id):null, titulo:mF.titulo.trim(), tipo:mF.tipo, fecha:/^\d{4}-\d{2}-\d{2}$/.test(mF.fecha)?mF.fecha:null, fuente:'manual'})
      if(error) throw error
      logActividad('plazos.agregado',{detalle:{title:mF.titulo.trim(),name:cliObj?.name||null}})
      setMF({titulo:'',fecha:'',tipo:'plazo'}); setMManual(false); await cargar()
    }catch(e){ setExtErr(/relation .*plazos.*does not exist|Could not find the table/i.test(e?.message||'')?'Falta crear la tabla: corre docs/sql_plazos.sql.':(e?.message||'No se pudo agregar.')) }
    setMSaving(false)
  }
  const buckets=useMemo(()=>{ if(!rows) return null
    const hoy=new Date().toISOString().slice(0,10), en30=new Date(Date.now()+30*864e5).toISOString().slice(0,10)
    const B={vencidos:[],prox:[],futuro:[],sinfecha:[],cumplidos:[]}
    rows.forEach(p=>{ if(p.estado==='cumplido') B.cumplidos.push(p); else if(!p.fecha) B.sinfecha.push(p); else if(p.fecha<hoy) B.vencidos.push(p); else if(p.fecha<=en30) B.prox.push(p); else B.futuro.push(p) })
    return B
  },[rows])
  const BUCK=[['vencidos','Vencidos',C.overdue],['prox','Próximos 30 días',C.soonText||C.soon],['futuro','Más adelante',C.text],['sinfecha','Sin fecha cierta',C.muted],['cumplidos','Cumplidos',C.normal]]
  const inp={width:'100%',border:`1px solid ${C.border}`,borderRadius:8,padding:'8px 10px',fontSize:13,color:C.text,outline:'none',boxSizing:'border-box'}
  const Fila=({p})=>(
    <div style={{display:'flex',alignItems:'flex-start',gap:8,padding:'8px 4px',borderTop:`0.5px solid ${C.border}`}}>
      <button type='button' onClick={()=>marcar(p)} title={p.estado==='cumplido'?'Marcar pendiente':'Marcar cumplido'} style={{flexShrink:0,width:16,height:16,marginTop:1,borderRadius:4,border:`1.5px solid ${p.estado==='cumplido'?C.normal:C.border}`,background:p.estado==='cumplido'?C.normal:'#fff',cursor:'pointer',color:'#fff',fontSize:11,lineHeight:'13px'}}>{p.estado==='cumplido'?<Gl n='tick'/>:''}</button>
      <div style={{flex:1,minWidth:0}}>
        <div style={{fontSize:13,color:C.text,textDecoration:p.estado==='cumplido'?'line-through':'none'}}>{p.titulo}</div>
        <div style={{fontSize:11,color:C.muted,marginTop:1,display:'flex',flexWrap:'wrap',gap:6,alignItems:'center'}}>
          {p.fecha&&<span style={{fontWeight:600,color:C.text}}>{fmtF(p.fecha)}</span>}
          <span style={{color:PLAZO_TIPO_COL[p.tipo]||C.muted,fontWeight:600}}>{p.tipo}</span>
          {p.client_id&&<span>· <span onClick={()=>onOpenClientFicha&&onOpenClientFicha(p.client_id)} style={{color:C.accent,fontWeight:600,cursor:onOpenClientFicha?'pointer':'default'}}>{cn(p.client_id)}</span></span>}
          {p.fuente&&<span>· {p.fuente}</span>}
        </div>
        {p.descripcion&&<div style={{fontSize:11,color:C.muted,marginTop:2,lineHeight:1.35}}>{p.descripcion}</div>}
      </div>
      <button type='button' onClick={()=>borrar(p)} title='Borrar' style={{flexShrink:0,fontSize:14,color:C.muted,background:'none',border:'none',cursor:'pointer',padding:'0 2px'}}><Gl n='x'/></button>
    </div>
  )
  const foto=buckets&&(()=>{ const v=buckets.vencidos.length, pr=buckets.prox.length; const ir=k=>setOpenB(new Set([k])); return (
    <div style={{background:v>0?C.overdueBg:pr>0?C.soonBg:C.greenBg,borderRadius:12,padding:'12px 14px',marginBottom:12}}>
      <div onClick={()=>v>0&&ir('vencidos')} style={{cursor:v>0?'pointer':'default'}}><div style={{fontSize:10,fontWeight:700,textTransform:'uppercase',letterSpacing:.5,color:v>0?C.overdueText:pr>0?C.soonText:C.greenText}}>{v>0?'Vencidos':pr>0?'Próximos 30 días':'Al día'}</div><div style={{fontSize:24,fontWeight:800,letterSpacing:-.4,color:v>0?C.overdueText:pr>0?C.soonText:C.greenText,fontVariantNumeric:'tabular-nums'}}>{v>0?v:pr>0?pr:'Sin plazos vencidos'}</div></div>
      <div style={{display:'flex',flexWrap:'wrap',gap:'4px 14px',marginTop:4,fontSize:11.5,color:C.muted}}>
        {[['prox','Próximos 30 días'],['futuro','Más adelante'],['sinfecha','Sin fecha cierta'],['cumplidos','Cumplidos']].filter(([k])=>buckets[k].length&&!(k==='prox'&&v===0)).map(([k,l])=><span key={k} onClick={()=>ir(k)} style={{cursor:'pointer'}}>{l} <b style={{color:C.text}}>{buckets[k].length}</b></span>)}
      </div>
    </div>) })()
  const altaBox=(
      <div style={{border:`1px solid ${C.border}`,borderRadius:12,padding:'10px 12px',background:C.card}}>
        <div style={{fontSize:11,color:C.muted,marginBottom:7}}>Extrae los plazos y obligaciones de un contrato del cliente — la IA los lee y tú los agendas.</div>
        <div style={{position:'relative',marginBottom:7}}>
          <input value={cliente} onChange={e=>setCliente(e.target.value)} placeholder='Buscar cliente…' style={inp}/>
          {cliente.trim().length>=1 && !(clients||[]).some(c=>c.name===cliente) && (()=>{
            const ms=(clients||[]).filter(c=>_normTxt(c.name).includes(_normTxt(cliente))).slice(0,6)
            if(!ms.length) return null
            return <div style={{position:'absolute',top:'100%',left:0,right:0,zIndex:6,background:'#fff',border:`1px solid ${C.border}`,borderRadius:8,marginTop:2,overflow:'hidden',boxShadow:'0 6px 20px rgba(0,0,0,.12)'}}>
              {ms.map(c=><div key={c.id} onClick={()=>setCliente(c.name)} style={{padding:'8px 11px',fontSize:13,color:C.text,cursor:'pointer',borderTop:`1px solid ${C.bgSoft}`}}>{c.name}</div>)}
            </div>
          })()}
        </div>
        <div style={{marginBottom:2}}>
          <button type='button' onClick={()=>setMManual(v=>!v)} style={{fontSize:11,color:C.azulInfo,background:'none',border:'none',cursor:'pointer',padding:0}}>{mManual?'Ocultar':'+ Agregar un plazo a mano'}</button>
          {mManual&&<div style={{marginTop:7,display:'flex',flexDirection:'column',gap:6}}>
            <input value={mF.titulo} onChange={e=>setMF(f=>({...f,titulo:e.target.value}))} placeholder='Título (ej. Renovación de contrato)' style={{...inp,padding:'6px 9px',fontSize:12}}/>
            <div style={{display:'flex',gap:6}}>
              <input type='date' value={mF.fecha} onChange={e=>setMF(f=>({...f,fecha:e.target.value}))} style={{...inp,padding:'6px 9px',fontSize:12,flex:1}}/>
              <select value={mF.tipo} onChange={e=>setMF(f=>({...f,tipo:e.target.value}))} style={{...inp,padding:'6px 9px',fontSize:12,flex:1}}>{['plazo','obligación','hito'].map(t=><option key={t} value={t}>{t}</option>)}</select>
            </div>
            <div style={{display:'flex',gap:8,alignItems:'center'}}>
              <button type='button' onClick={agregarManual} disabled={mSaving||!mF.titulo.trim()} style={{fontSize:12,fontWeight:600,color:'#fff',background:(mSaving||!mF.titulo.trim())?C.done:C.accent,border:'none',borderRadius:8,padding:'6px 12px',cursor:'pointer'}}>{mSaving?'Agregando…':'Agregar'}</button>
              <span style={{fontSize:10,color:C.muted}}>{cliObj?`para ${cliObj.name}`:'sin cliente asignado'}</span>
            </div>
          </div>}
        </div>
        {cliObj&&!extracted&&<>
          <button type='button' onClick={()=>setMostrarPicker(v=>!v)} style={{fontSize:12,color:C.azulInfo,background:'none',border:'none',cursor:'pointer',padding:0}}>{mostrarPicker?'Ocultar':`+ Elegir un contrato de ${cliObj.name}`}</button>
          {extBusy&&<div style={{fontSize:11,color:C.muted,marginTop:6}}>Leyendo y extrayendo plazos…</div>}
          {extErr&&<div style={{fontSize:11,color:C.overdueText,marginTop:6}}>{extErr}</div>}
          {mostrarPicker&&!extBusy&&<div style={{border:`1px solid ${C.border}`,borderRadius:8,padding:'8px 9px',marginTop:6}}><DocumentosDrive client={cliObj} onPick={extraerPlazos}/></div>}
        </>}
        {extracted&&<div style={{marginTop:8}}>
          <div style={{fontSize:11,fontWeight:600,color:C.text,marginBottom:5}}>{extracted.items.length} encontrados en "{extracted.file.name}":</div>
          <div style={{display:'flex',flexDirection:'column',maxHeight:180,overflowY:'auto',border:`1px solid ${C.border}`,borderRadius:8,padding:'2px 8px'}}>{extracted.items.map((x,i)=><div key={i} style={{fontSize:12,color:C.text,padding:'5px 0',borderTop:i?`0.5px solid ${C.border}`:'none'}}><b>{x.fecha?fmtF(x.fecha):'sin fecha'}</b> · <span style={{color:PLAZO_TIPO_COL[x.tipo]||C.muted}}>{x.tipo}</span> — {x.titulo}</div>)}</div>
          <div style={{display:'flex',gap:8,marginTop:8}}>
            <button type='button' onClick={guardarExtraidos} disabled={saving} style={{fontSize:12,fontWeight:600,color:'#fff',background:saving?C.done:C.accent,border:'none',borderRadius:8,padding:'6px 12px',cursor:'pointer'}}>{saving?'Guardando…':`Agendar los ${extracted.items.length}`}</button>
            <button type='button' onClick={()=>setExtracted(null)} style={{fontSize:12,color:C.muted,background:'none',border:`1px solid ${C.border}`,borderRadius:8,padding:'6px 12px',cursor:'pointer'}}>Descartar</button>
          </div>
          {extErr&&<div style={{fontSize:11,color:C.overdueText,marginTop:6}}>{extErr}</div>}
        </div>}
      </div>
  )
  return (
    <div style={{padding:'2px 2px 6px'}}>
      {foto}
      <div style={isDesk?{display:'flex',alignItems:'flex-start',gap:18}:{display:'flex',flexDirection:'column',gap:12}}>
        <div style={{flex:1,minWidth:0}}>
      {buckets===null?<div style={{fontSize:12,color:C.muted,textAlign:'center',padding:16}}>Cargando…</div>
       :BUCK.every(([k])=>!buckets[k].length)?<div style={{fontSize:12,color:C.muted,textAlign:'center',padding:16}}>No hay plazos agendados. Agrega uno a mano o extráelo de un contrato.</div>
       :BUCK.filter(([k])=>buckets[k].length).map(([k,lbl,col])=>{ const op=openB.has(k); return (
        <div key={k} style={{marginBottom:8,border:`1px solid ${C.border}`,borderRadius:10,overflow:'hidden'}}>
          <div onClick={()=>togB(k)} style={{display:'flex',alignItems:'center',gap:8,padding:'9px 11px',cursor:'pointer',background:op?C.bgPanel:'transparent'}}>
            <span style={{width:8,height:8,borderRadius:'50%',background:col,flexShrink:0}}/>
            <span style={{flex:1,fontSize:12,fontWeight:700,color:C.text}}>{lbl}</span>
            <span style={{fontSize:11,color:C.muted,fontWeight:600}}>{buckets[k].length}</span>
            <svg width='13' height='13' viewBox='0 0 24 24' fill='none' stroke={C.done} strokeWidth='2' strokeLinecap='round' strokeLinejoin='round' style={{transform:op?'rotate(180deg)':'none',transition:'transform .12s'}}><path d='M6 9l6 6 6-6'/></svg>
          </div>
          {op&&<div style={{padding:'0 11px 6px'}}>{buckets[k].map(p=><Fila key={p.id} p={p}/>)}</div>}
        </div>
      )})}
        </div>
        <div style={isDesk?{width:360,flexShrink:0,display:'flex',flexDirection:'column',gap:12}:{display:'flex',flexDirection:'column',gap:12}}>
          {altaBox}
          <BitacoraLista prefijo='plazos.' titulo='Historial de plazos' etiquetas={{'plazos.agregado':'Plazo agregado','plazos.extraidos':'Plazos leídos de un documento','plazos.cumplido':'Plazo cumplido','plazos.reabierto':'Plazo reabierto','plazos.borrado':'Plazo borrado'}} limite={12}/>
        </div>
      </div>
    </div>
  )
}
function LearningCenter({clients=[], onClose}){
  const [rows,setRows] = useState(null)
  const [edId,setEdId] = useState(null), [edVal,setEdVal] = useState(''), [edSub,setEdSub] = useState('')
  const EDITABLES = {costo_oficina:1,gasto_categoria:1,gasto_proyecto:1,cartola_tipo:1}
  useEffect(()=>{
    if(DEMO){ setRows([
      {id:'l1',kind:'cargo_cliente',key:'arriendo notaria pago',value:'c1'},
      {id:'l2',kind:'costo_oficina',key:'arriendo oficina pago',value:'Arriendo',meta:{subcategory:'Local'}},
      {id:'l3',kind:'costo_oficina',key:'cuenta luz oficina',value:'Servicios',meta:{subcategory:'Luz'}},
      {id:'l4',kind:'gasto_categoria',key:'uber notaria lascar',value:'Movilización'},
      {id:'l5',kind:'gasto_cliente',key:'inscripcion conservador',value:'c2'},
      {id:'l6',kind:'dominio_cliente',key:'andesretail.cl',value:'c1'},
    ]); return }
    selectAll(()=>supabase.from('learnings').select('id,kind,key,value,meta,created_at').order('created_at',{ascending:false}).order('id')).then(({data})=>setRows(data||[]),()=>setRows([]))
  },[])
  const cn = id => (clients||[]).find(c=>String(c.id)===String(id))?.name || '—'
  const KINDS = {
    cargo_cliente:   { lbl:'Cargo del banco → cliente',     val:r=>cn(r.value) },
    costo_oficina:   { lbl:'Cargo → costo de oficina',       val:r=>`${r.value}${r.meta&&r.meta.subcategory?` · ${r.meta.subcategory}`:''}` },
    gasto_cliente:   { lbl:'Glosa de gasto → cliente',       val:r=>cn(r.value) },
    gasto_categoria: { lbl:'Glosa de gasto → categoría',     val:r=>r.value },
    gasto_proyecto:  { lbl:'Glosa de gasto → proyecto',      val:r=>r.value },
    cartola_tipo:    { lbl:'Pagador del banco → categoría',  val:r=>r.value },
    dominio_cliente: { lbl:'Dominio de correo → cliente',    val:r=>cn(r.value) },
  }
  const [openG,setOpenG] = useState(()=>new Set())   // grupos colapsados por defecto (acordeón)
  const togG = k => setOpenG(p=>{const s=new Set(p); s.has(k)?s.delete(k):s.add(k); return s})
  const grupos = useMemo(()=>{ if(!rows) return null; const g={}; rows.forEach(r=>{ if(!KINDS[r.kind]) return; (g[r.kind]=g[r.kind]||[]).push(r) }); return Object.keys(KINDS).filter(k=>g[k]).map(k=>({k,...KINDS[k],items:g[k]})) },[rows])
  const keyTxt = r => r.kind==='gasto_proyecto' ? (String(r.key).split('::')[1]||r.key) : r.key
  const olvidar = async r => { if(!DEMO){ try{ await supabase.from('learnings').delete().eq('id',r.id) }catch(e){registrarError({origen:'accion',vista:'learnings',err:e})} } setRows(p=>(p||[]).filter(x=>x.id!==r.id)) }
  const editar = r => { setEdId(r.id); setEdVal(r.value||''); setEdSub(r.meta&&r.meta.subcategory||'') }
  const cancelar = () => { setEdId(null); setEdVal(''); setEdSub('') }
  const guardar = async r => {
    const nv = (edVal||'').trim(); if(!nv) return
    const nm = r.kind==='costo_oficina' ? {...(r.meta||{}), subcategory:(edSub||'').trim()||undefined} : r.meta
    if(!DEMO){ try{ await supabase.from('learnings').update({value:nv,meta:nm,updated_at:new Date().toISOString()}).eq('id',r.id) }catch(e){registrarError({origen:'accion',vista:'learnings',err:e})} }
    setRows(p=>(p||[]).map(x=>x.id===r.id?{...x,value:nv,meta:nm}:x)); cancelar()
  }
  if(grupos===null) return <div style={{padding:30,textAlign:'center',color:C.muted,fontSize:13}}>Cargando…</div>
  const total = grupos.reduce((a,g)=>a+g.items.length,0)
  return (
    <div style={{padding:'2px 2px 8px'}}>
      <div style={{fontSize:11,color:C.muted,marginBottom:14,lineHeight:1.5}}>Cada decisión que tomas (asignar un cliente, clasificar un cargo) la app la recuerda para no volver a preguntar. Acá está todo lo aprendido — si un match quedó mal, tócalo en <b>Olvidar</b> y dejará de sugerirlo.</div>
      {total===0 && <div style={{padding:30,textAlign:'center',color:C.muted,fontSize:13}}>Todavía no hay aprendizajes guardados. Se irán acumulando con el uso.</div>}
      {grupos.map(g=>{ const op=openG.has(g.k); return (
        <div key={g.k} style={{marginBottom:8,border:`1px solid ${C.border}`,borderRadius:10,overflow:'hidden'}}>
          <div onClick={()=>togG(g.k)} style={{display:'flex',alignItems:'center',gap:8,padding:'10px 12px',cursor:'pointer',background:op?C.bgPanel:'transparent'}}>
            <span style={{flex:1,fontSize:10,fontWeight:700,color:C.muted,textTransform:'uppercase',letterSpacing:.4}}>{g.lbl}</span>
            <span style={{fontSize:11,color:C.muted,fontWeight:600}}>{g.items.length}</span>
            <svg width='14' height='14' viewBox='0 0 24 24' fill='none' stroke={C.done} strokeWidth='2' strokeLinecap='round' strokeLinejoin='round' style={{flexShrink:0,transform:op?'rotate(180deg)':'none',transition:'transform .12s'}}><path d='M6 9l6 6 6-6'/></svg>
          </div>
          {op && <div style={{borderTop:`1px solid ${C.border}`}}>
            {g.items.map((r,i)=>(
              <div key={r.id} style={{display:'flex',alignItems:'center',gap:8,padding:'8px 11px',borderTop:i?`0.5px solid ${C.border}`:'none',flexWrap:'wrap'}}>
                {edId===r.id ? (
                  <>
                    <span style={{flexShrink:0,fontSize:12,color:C.muted,maxWidth:'42%',overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{keyTxt(r)} <span style={{color:C.textSoft}}>→</span></span>
                    <input value={edVal} onChange={e=>setEdVal(e.target.value)} autoFocus style={{flex:1,minWidth:90,height:32,fontSize:12,color:C.text,border:`1px solid ${C.border}`,borderRadius:8,padding:'0 8px',outline:'none'}}/>
                    {r.kind==='costo_oficina' && <input value={edSub} onChange={e=>setEdSub(e.target.value)} placeholder='Subcategoría (opcional)' style={{flex:1,minWidth:90,height:32,fontSize:12,color:C.text,border:`1px solid ${C.border}`,borderRadius:8,padding:'0 8px',outline:'none'}}/>}
                    <button onClick={()=>guardar(r)} style={{flexShrink:0,fontSize:11,color:'#fff',background:C.accent,border:`1px solid ${C.accent}`,borderRadius:8,padding:'4px 9px',cursor:'pointer'}}>Guardar</button>
                    <button onClick={cancelar} style={{flexShrink:0,fontSize:11,color:C.muted,background:'none',border:`1px solid ${C.border}`,borderRadius:8,padding:'4px 9px',cursor:'pointer'}}>Cancelar</button>
                  </>
                ) : (
                  <>
                    <div style={{flex:1,minWidth:0,fontSize:12,color:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}><span style={{color:C.muted}}>{keyTxt(r)}</span> <span style={{color:C.textSoft}}>→</span> <b style={{color:C.accent}}>{g.val(r)}</b></div>
                    {EDITABLES[r.kind] && <ActBtn variant='ghost' onClick={()=>editar(r)} title='Corregir el valor' style={{flexShrink:0}}>Editar</ActBtn>}
                    <button onClick={()=>olvidar(r)} title='Dejar de sugerir esto' style={{flexShrink:0,fontSize:11,color:C.overdueText,background:'none',border:`1px solid ${C.border}`,borderRadius:8,padding:'4px 9px',cursor:'pointer'}}>Olvidar</button>
                  </>
                )}
              </div>
            ))}
          </div>}
        </div>
      )})}
    </div>
  )
}

// ─── PAPELERA (soft-delete): ventas, cobros y gastos eliminados; restaurar o borrar definitivo ──
function PapeleraModal({clients=[],onClose,onChanged}){
  const [data,setData] = useState(null)   // {ventas, cobros, gastos}
  const [busy,setBusy] = useState(false)
  const cli = id => clients.find(c=>String(c.id)===String(id))?.name||'—'
  const fmtD = iso => { if(!iso) return ''; const p=String(iso).slice(0,10).split('-'); return p.length===3?`${p[2]}-${p[1]}-${p[0]}`:'' }
  const cargar = async()=>{
    const [v,b,g] = await Promise.all([
      supabase.from('sales').select('*').not('deleted_at','is',null).order('deleted_at',{ascending:false}).then(r=>r.data||[]),
      selectAll(()=>supabase.from('billing').select('*').not('deleted_at','is',null).order('deleted_at',{ascending:false}).order('id')).then(r=>r.data||[]),
      selectAll(()=>supabase.from('expenses').select('*').not('deleted_at','is',null).order('deleted_at',{ascending:false}).order('id')).then(r=>r.data||[]),
    ])
    setData({ventas:v,cobros:b,gastos:g})
  }
  useEffect(()=>{ cargar() },[])
  const restaurar = async(tipo,row)=>{
    setBusy(true)
    try{
      if(tipo==='ventas'){ await supabase.from('sales').update({deleted_at:null}).eq('id',row.id); /* solo las cuotas borradas EN CASCADA con la venta (mismo deleted_at), no las que se borraron por separado antes */ const cq=supabase.from('billing').update({deleted_at:null}).eq('sale_id',row.id); await (row.deleted_at?cq.eq('deleted_at',row.deleted_at):cq) }
      else if(tipo==='cobros'){ await supabase.from('billing').update({deleted_at:null}).eq('id',row.id) }
      else {
        const renderId = row.client_render_id || row.render_id
        let r=null
        if(renderId){ const {data}=await supabase.from('rendiciones').select('total,n_gastos').eq('id',renderId).single(); r=data }
        if(renderId && !r){
          // La rendición ya no existe: restaurar el gasto como PENDIENTE (no dejar un vínculo muerto que lo muestre "rendido").
          await supabase.from('expenses').update({deleted_at:null, client_render_id:null, client_rendered_at:null, render_id:null, rendered_at:null, rendered_by:null}).eq('id',row.id)
        } else {
          await supabase.from('expenses').update({deleted_at:null}).eq('id',row.id)
          // Si el gasto estaba en una rendición viva, reponer su total/contador (handleDeleteExpense los descontó al borrar).
          if(r) await supabase.from('rendiciones').update({total:(r.total||0)+(row.amount||0), n_gastos:(r.n_gastos||0)+1}).eq('id',renderId)
        }
      }
      await cargar(); onChanged&&onChanged()
    }catch(e){appAlert('Error: '+e.message)}
    setBusy(false)
  }
  const purgar = async(tipo,row)=>{
    if(tipo==='cobros'&&conFolioSII(row)){ appAlert(MSG_NO_BORRAR_FOLIO); return }
    if(tipo==='ventas'){ const {data:fs}=await supabase.from('billing').select('id,invoice_no').eq('sale_id',row.id); const n=(fs||[]).filter(conFolioSII).length; if(n){ appAlert(`Esta venta tiene ${n} factura${n===1?'':'s'} con folio del SII. ${MSG_NO_BORRAR_FOLIO}`); return } }
    if(!await appConfirm('Eliminar DEFINITIVAMENTE. Esto no se puede deshacer. ¿Continuar?')) return
    setBusy(true)
    try{
      const ok=r=>{ if(r?.error) throw r.error }
      if(tipo==='ventas'){ ok(await supabase.from('billing').delete().eq('sale_id',row.id)); ok(await supabase.from('sales').delete().eq('id',row.id)) }
      else if(tipo==='cobros'){ ok(await supabase.from('billing').delete().eq('id',row.id)) }
      else { ok(await supabase.from('expenses').delete().eq('id',row.id)) }
      await cargar()
    }catch(e){appAlert('Error: '+e.message)}
    setBusy(false)
  }
  const fmt0 = n => fmt(Number(n)||0)   // formateador CLP único (global fmt): redondeo y signo -$ correctos
  const seccion = (tipo,titulo,rows,label) => (
    <div style={{marginBottom:16}}>
      <div style={{...SEC_LBL,marginBottom:6}}>{titulo} {rows.length>0&&`· ${rows.length}`}</div>
      {rows.length===0?(
        <div style={{fontSize:12,color:C.textSoft,padding:'8px 0'}}>Nada eliminado.</div>
      ):rows.map(r=>(
        <div key={r.id} style={{display:'flex',alignItems:'center',gap:8,padding:'9px 11px',border:`0.5px solid ${C.border}`,borderRadius:10,marginBottom:6}}>
          <div style={{minWidth:0,flex:1}}>
            <div style={{fontSize:13,fontWeight:500,color:C.text,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{label(r)}</div>
            <div style={{fontSize:11,color:C.textSoft}}>Eliminado {fmtD(r.deleted_at)}</div>
          </div>
          <button onClick={()=>restaurar(tipo,r)} disabled={busy} style={{flexShrink:0,height:24,padding:'0 11px',borderRadius:8,border:`1px solid ${C.accent}`,background:C.azulBg,color:C.accent,fontSize:11,fontWeight:600,cursor:'pointer'}}>Restaurar</button>
          <button onClick={()=>purgar(tipo,r)} disabled={busy} title='Eliminar definitivo' style={{flexShrink:0,width:30,height:30,borderRadius:8,border:`0.5px solid ${C.border}`,background:'#fff',color:C.overdue,fontSize:14,cursor:'pointer'}}><Gl n='x'/></button>
        </div>
      ))}
    </div>
  )
  if(!data) return <div style={{padding:'30px 20px',textAlign:'center',color:C.muted,fontSize:13}}>Cargando…</div>
  const total = data.ventas.length+data.cobros.length+data.gastos.length
  return (
    <div>
      {total===0&&<div style={{fontSize:12,color:C.textSoft,textAlign:'center',padding:'16px 0 18px'}}>Vacía. Lo que elimines (ventas, cobros, gastos) aparece acá para restaurar.</div>}
      {seccion('ventas','Ventas',data.ventas,r=>r.title||'Venta')}
      {seccion('cobros','Cobros',data.cobros,r=>`${cli(r.client_id)} · ${r.concept||'Cobro'} · ${fmt0(r.amount)}`)}
      {seccion('gastos','Gastos',data.gastos,r=>`${r.notas||r.concept||'Gasto'} · ${fmt0(r.amount)}`)}
    </div>
  )
}

// Clientes › Causas: todas las causas del estudio (se agregan desde la venta). En tabla primero, por confirmar, sin tabla por Corte.
function CausasEstudio({isDesktop, clients=[], user, onBack, origen, onOpenClientFicha}){
  const D=isDesktop
  const {rows,setRows,recargar}=useCausas()
  const [q,setQ]=useState(''), [corte,setCorte]=useState(''), [abog,setAbog]=useState(''), [busy,setBusy]=useState(false)
  const nom=id=>clients.find(c=>String(c.id)===String(id))?.name||'—'
  const hoy=isoLocal(new Date().toISOString())
  const lista=(rows||[]).filter(c=>(!corte||c.corte_codigo===corte)&&(!abog||c.abogado===abog)&&(!q||_normTxt(`${c.caratula||''} ${c.rol}-${c.anio} ${nom(c.client_id)}`).includes(_normTxt(q))))
  const tab=lista.filter(c=>c.estado==='activa'&&c.ultima_tabla?.fecha>=hoy).sort((a,b)=>a.ultima_tabla.fecha.localeCompare(b.ultima_tabla.fecha))
  // «Sin tabla» solo con la última revisión confirmada por pjud.cl; si falló, va a «No se pudo revisar».
  const err=lista.filter(c=>c.estado==='activa'&&c.ultima_error&&!(c.ultima_tabla?.fecha>=hoy))
  const pc=lista.filter(c=>c.estado==='por_confirmar'), sin=lista.filter(c=>c.estado==='activa'&&!c.ultima_error&&!(c.ultima_tabla?.fecha>=hoy))
  const porCorte={}; sin.forEach(c=>{ (porCorte[c.corte_nombre]=porCorte[c.corte_nombre]||[]).push(c) })
  const revisarTodas=async()=>{ if(busy) return; setBusy(true)
    try{ if(DEMO){ appAlert('Revisión hecha (demo).'); return }
      const {data,error}=await supabase.functions.invoke('causas-tablas',{body:{}}); if(error||data?.error) throw new Error(data?.error||error?.message)
      recargar(); appAlert(`${data.revisadas} causa${data.revisadas!==1?'s':''} revisada${data.revisadas!==1?'s':''}: ${(data.en_tabla||[]).length} en tabla${(data.avisos||[]).length?`, ${data.avisos.filter(a=>a.enviado).length} aviso${data.avisos.filter(a=>a.enviado).length!==1?'s':''} enviado${data.avisos.filter(a=>a.enviado).length!==1?'s':''}${data.avisos.some(a=>!a.enviado)?` y ${data.avisos.filter(a=>!a.enviado).length} NO enviado${data.avisos.filter(a=>!a.enviado).length!==1?'s':''}`:''}`:''}${(data.errores||[]).length?`. ${data.errores.length} no se ${data.errores.length===1?'pudo':'pudieron'} revisar: ${data.errores.map(x=>`${x.causa} (${x.error})`).join('; ')}`:''}.`)
    }catch(err){ appAlert('No se pudieron revisar las causas: '+(err.message||err)) }
    finally{ setBusy(false) } }
  const card={background:C.card,border:`1px solid ${C.border}`,borderRadius:12,overflow:'hidden'}
  const sel={fontSize:12.5,color:C.text,background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:'7px 8px',minWidth:0}
  const fila=c=><CausaFila key={c.id} c={c} isDesktop={D} user={user} cliente={<span onClick={onOpenClientFicha?ev=>{ev.stopPropagation();onOpenClientFicha(c.client_id)}:undefined} style={{color:C.accent,fontWeight:600,cursor:'pointer'}}>{nom(c.client_id)}</span>} onCambio={x=>x?setRows(p=>p.map(y=>y.id===x.id?x:y).filter(y=>y.estado!=='terminada')):recargar()}/>
  const abogados=[...new Set((rows||[]).map(c=>c.abogado).filter(Boolean))].sort()
  const cortes=[...new Set((rows||[]).map(c=>c.corte_codigo))]
  return (<div style={{padding:D?'8px 22px 44px':'6px 12px 30px',maxWidth:D?1100:undefined,margin:'0 auto'}}>
    <PageHeader origen={origen||'Clientes'} onBack={onBack} titulo='Causas' right={<button onClick={revisarTodas} disabled={busy} style={{...chipBtn('soft'),color:C.accent}}>{busy?'Revisando…':D?'Revisar todas ahora':'Revisar todas'}</button>} style={{margin:D?'-12px -20px 12px':'-8px -16px 12px'}}/>
    {rows===null?<div style={{fontSize:12,color:C.muted}}>Cargando…</div>:<div style={{display:'flex',flexDirection:'column',gap:12}}>
      <div style={{...card,display:'grid',gridTemplateColumns:'repeat(3,minmax(0,1fr))'}}>
        {[['Causas activas',(rows||[]).filter(c=>c.estado==='activa').length,C.text,'Cortes de Apelaciones y Suprema'],['En tabla',(rows||[]).filter(c=>c.estado==='activa'&&c.ultima_tabla?.fecha>=hoy).length,C.azulInfo,'próximas vistas'],['Por confirmar',(rows||[]).filter(c=>c.estado==='por_confirmar').length,C.soonText,'se agregan desde la venta']].map(([l,v,col,s],i)=><div key={l} style={{padding:D?'12px 16px':'10px 10px',borderLeft:i?`1px solid ${C.track}`:'none'}}><div style={{...SEC_LBL,fontSize:D?11:9.5,whiteSpace:'nowrap'}}>{l}</div><div style={{fontSize:D?22:17,fontWeight:700,color:col,marginTop:2,fontVariantNumeric:'tabular-nums'}}>{v}</div>{D&&<div style={{fontSize:11.5,color:C.textSoft,marginTop:2,whiteSpace:'nowrap'}}>{s}</div>}</div>)}
      </div>
      <div style={{display:'flex',gap:8,flexWrap:'wrap'}}>
        <div style={{flex:D?'1 1 260px':'1 1 100%',display:'flex',alignItems:'center',gap:6,background:C.bgSoft,border:`1px solid ${C.border}`,borderRadius:8,padding:'7px 10px',minWidth:0}}><SIcon n='search' s={14} c={C.done}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder='Buscar cliente, carátula o rol' style={{border:'none',background:'none',outline:'none',fontSize:12.5,color:C.text,width:'100%',minWidth:0}}/></div>
        {cortes.length>1&&<select value={corte} onChange={e=>setCorte(e.target.value)} style={sel}><option value=''>Todas las Cortes</option>{cortes.map(k=><option key={k} value={k}>{(CORTES_PJUD.find(x=>x[0]===k)||[k,k])[1]}</option>)}</select>}
        {abogados.length>1&&<select value={abog} onChange={e=>setAbog(e.target.value)} style={sel}><option value=''>Todos los abogados</option>{abogados.map(a=><option key={a} value={a}>{a}</option>)}</select>}
      </div>
      {tab.length>0&&<div><div style={{...SEC_LBL,margin:'2px 2px 6px'}}>En tabla · {tab.length}</div><div style={card}>{tab.map(fila)}</div></div>}
      {err.length>0&&<div><div style={{...SEC_LBL,margin:'2px 2px 6px',color:C.overdueText}}>No se pudo revisar · {err.length}</div><div style={card}>{err.map(fila)}</div></div>}
      {pc.length>0&&<div><div style={{...SEC_LBL,margin:'2px 2px 6px'}}>Por confirmar · {pc.length}</div><div style={card}>{pc.map(fila)}</div></div>}
      {Object.keys(porCorte).length>0&&<div><div style={{...SEC_LBL,margin:'2px 2px 6px'}}>Sin tabla · {sin.length}</div><div style={{display:'flex',flexDirection:'column',gap:8}}>{Object.entries(porCorte).map(([k,v])=><div key={k} style={card}><div style={{display:'flex',alignItems:'center',padding:'10px 14px'}}><span style={{fontSize:13.5,fontWeight:700,color:C.accent,flex:1}}>{k}</span><span style={{fontSize:12,color:C.textSoft}}>{v.length} causa{v.length!==1?'s':''}</span></div>{v.map(fila)}</div>)}</div></div>}
      {!lista.length&&<div style={{...card,padding:20,textAlign:'center',fontSize:13,color:C.muted}}>{q||corte||abog?'Ninguna causa con esos filtros.':'Sin causas. Se agregan en la ficha del cliente › Ventas › la venta respectiva.'}</div>}
    </div>}
  </div>)
}

// ─── RED PROFESIONAL: base de contactos de la red (no clientes), por país y categoría ─────────
function RedProfesionalModal({preset=null, onClose, onSaved}){
  const [rows,setRows] = useState(null)
  const [q,setQ] = useState('')
  const [catF,setCatF] = useState('')
  const [paisF,setPaisF] = useState('')
  const [showAdd,setShowAdd] = useState(!!preset)
  const [edit,setEdit] = useState(null)
  const [f,setF] = useState(preset||{nombre:'',email:'',pais:'',categoria:'',descripcion:'',web:'',linkedin:'',origen:''})
  const [saving,setSaving] = useState(false)
  const up=(k,v)=>setF(p=>({...p,[k]:v}))
  const load=()=>supabase.from('red_profesional').select('*').order('created_at',{ascending:false}).then(({data})=>setRows(data||[]),()=>setRows([]))
  useEffect(()=>{ load() },[])
  const ini = n => (n||'?').trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase()
  const inp = {width:'100%',height:36,border:`1px solid ${C.border}`,borderRadius:8,padding:'0 10px',fontSize:13,color:C.text,background:C.bgSoft,boxSizing:'border-box',outline:'none'}
  const catCount={}; (rows||[]).forEach(r=>{ if(r.categoria) catCount[r.categoria]=(catCount[r.categoria]||0)+1 })
  const cats = Object.keys(catCount).sort((a,b)=>catCount[b]-catCount[a])
  const paises = [...new Set((rows||[]).map(r=>r.pais).filter(Boolean))].sort()
  const ql=q.trim().toLowerCase()
  const filtered = (rows||[]).filter(r=> (!ql||(r.nombre||'').toLowerCase().includes(ql)||(r.email||'').toLowerCase().includes(ql)) && (!catF||r.categoria===catF) && (!paisF||r.pais===paisF))
  const grupos={}; filtered.forEach(r=>{ const k=r.pais||'Sin país'; (grupos[k]=grupos[k]||[]).push(r) })
  const resetF=()=>{ setF({nombre:'',email:'',pais:'',categoria:'',descripcion:'',web:'',linkedin:'',origen:''}); setShowAdd(false); setEdit(null) }
  const guardar=async()=>{
    if(!f.nombre.trim()){ return }
    setSaving(true)
    try{
      const payload={nombre:f.nombre.trim(),email:f.email?.trim()||null,pais:f.pais?.trim()||null,categoria:f.categoria?.trim()||null,descripcion:f.descripcion?.trim()||null,web:f.web?.trim()||null,linkedin:f.linkedin?.trim()||null,origen:f.origen?.trim()||null}
      if(edit){ const {data,error}=await supabase.from('red_profesional').update(payload).eq('id',edit.id).select().single(); if(error)throw error; setRows(p=>p.map(x=>x.id===data.id?data:x)) }
      else { const {data,error}=await supabase.from('red_profesional').insert(payload).select().single(); if(error)throw error; setRows(p=>[data,...(p||[])]); onSaved&&onSaved(data) }
      resetF()
    }catch(e){ appAlert('Error: '+e.message) }
    setSaving(false)
  }
  const startEdit=(r)=>{ setEdit(r); setF({nombre:r.nombre||'',email:r.email||'',pais:r.pais||'',categoria:r.categoria||'',descripcion:r.descripcion||'',web:r.web||'',linkedin:r.linkedin||'',origen:r.origen||''}); setShowAdd(true) }
  const eliminar=async(r)=>{ if(!await appConfirm(`¿Eliminar a ${r.nombre} de la red?`)) return; await supabase.from('red_profesional').delete().eq('id',r.id); setRows(p=>p.filter(x=>x.id!==r.id)) }
  const chip = (active) => ({fontSize:11,fontWeight:600,borderRadius:20,padding:'3px 11px',cursor:'pointer',whiteSpace:'nowrap',border:active?'none':`0.5px solid ${C.border}`,background:active?C.accent:C.bgSoft,color:active?'#fff':C.muted})
  return (
    <div style={{maxWidth:560}}>
      {showAdd ? (
        <div>
          <div style={{fontSize:13,fontWeight:700,color:C.accent,marginBottom:12}}>{edit?'Editar contacto':'Nuevo contacto de red'}</div>
          <div style={{display:'grid',gap:8}}>
            <input autoFocus value={f.nombre} onChange={e=>up('nombre',e.target.value)} placeholder='Nombre *' style={inp}/>
            <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:8}}>
              <input value={f.email} onChange={e=>up('email',e.target.value)} placeholder='Email' style={inp}/>
              <input value={f.pais} onChange={e=>up('pais',e.target.value)} placeholder='País' list='rp-paises' style={inp}/>
            </div>
            <datalist id='rp-paises'>{paises.map(p=><option key={p} value={p}/>)}</datalist>
            <input value={f.categoria} onChange={e=>up('categoria',e.target.value)} placeholder='Categoría (la armas tú: abogado, notario, banca…)' list='rp-cats' style={inp}/>
            <datalist id='rp-cats'>{cats.map(c=><option key={c} value={c}/>)}</datalist>
            <div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:8}}>
              <input value={f.web} onChange={e=>up('web',e.target.value)} placeholder='Web' style={inp}/>
              <input value={f.linkedin} onChange={e=>up('linkedin',e.target.value)} placeholder='LinkedIn' style={inp}/>
            </div>
            <input value={f.origen} onChange={e=>up('origen',e.target.value)} placeholder='Dónde lo conocí (origen)' style={inp}/>
            <input value={f.descripcion} onChange={e=>up('descripcion',e.target.value)} placeholder='Descripción breve' style={inp}/>
            <div style={{display:'flex',gap:8,marginTop:2}}>
              <button onClick={preset?onClose:resetF} disabled={saving} style={{flex:1,height:44,borderRadius:10,border:`1px solid ${C.border}`,background:'#fff',color:C.muted,fontSize:13,fontWeight:600,cursor:'pointer'}}>Cancelar</button>
              <button onClick={guardar} disabled={saving||!f.nombre.trim()} style={{flex:2,height:44,borderRadius:10,border:'none',background:C.accent,color:'#fff',fontSize:13,fontWeight:700,cursor:'pointer',opacity:(saving||!f.nombre.trim())?.6:1}}>{saving?'Guardando…':(edit?'Guardar':'Agregar a la red')}</button>
            </div>
          </div>
        </div>
      ) : (
        <div>
          <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:10}}>
            <span style={{fontSize:12,color:C.muted}}><b style={{color:C.text}}>{(rows||[]).length}</b> contacto{(rows||[]).length!==1?'s':''} de red</span>
            <button onClick={()=>{setEdit(null);setShowAdd(true)}} style={{fontSize:12,fontWeight:700,color:'#fff',background:C.accent,border:'none',borderRadius:8,padding:'6px 12px',cursor:'pointer'}}>+ Agregar</button>
          </div>
          <div style={{display:'flex',gap:8,marginBottom:10}}>
            <input value={q} onChange={e=>setQ(e.target.value)} placeholder='Buscar nombre o email…' style={{...inp,flex:1}}/>
            <select value={paisF} onChange={e=>setPaisF(e.target.value)} style={{...inp,width:'auto',color:C.muted}}><option value=''>Todo país</option>{paises.map(p=><option key={p} value={p}>{p}</option>)}</select>
          </div>
          <div style={{display:'flex',gap:6,flexWrap:'wrap',marginBottom:12}}>
            <span onClick={()=>setCatF('')} style={chip(!catF)}>Todos · {(rows||[]).length}</span>
            {cats.map(c=><span key={c} onClick={()=>setCatF(catF===c?'':c)} style={chip(catF===c)}>{c} · {catCount[c]}</span>)}
          </div>
          {rows===null&&<div style={{textAlign:'center',color:C.muted,fontSize:13,padding:'20px'}}>Cargando…</div>}
          {rows!==null&&filtered.length===0&&<div style={{textAlign:'center',color:C.muted,fontSize:13,padding:'24px 0'}}>Sin contactos {q||catF||paisF?'con ese filtro':'aún'}. Toca "+ Agregar".</div>}
          {Object.keys(grupos).sort().map(pais=>(
            <div key={pais} style={{border:`1px solid ${C.border}`,borderRadius:12,overflow:'hidden',marginBottom:10}}>
              <div style={{...SEC_LBL,padding:'8px 14px',background:C.bgPanel}}>{pais} · {grupos[pais].length}</div>
              {grupos[pais].map(r=>(
                <div key={r.id} style={{display:'flex',alignItems:'flex-start',gap:11,padding:'10px 14px',borderTop:`1px solid #F1F3F5`}}>
                  <div style={{width:36,height:36,borderRadius:'50%',background:C.azulBg,color:C.accent,display:'flex',alignItems:'center',justifyContent:'center',fontSize:12,fontWeight:700,flexShrink:0}}>{ini(r.nombre)}</div>
                  <div style={{flex:1,minWidth:0}}>
                    <div style={{fontSize:13,fontWeight:600,color:C.text}}>{r.nombre}{r.categoria&&<span style={{fontSize:9.5,fontWeight:700,color:C.accent,background:C.azulBg,padding:'2px 8px',borderRadius:20,marginLeft:6,whiteSpace:'nowrap'}}>{r.categoria}</span>}</div>
                    {r.email&&<div style={{fontSize:11,color:C.muted,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{r.email}</div>}
                    {(r.web||r.linkedin)&&<div style={{fontSize:11,marginTop:1}}>{r.web&&<a href={/^https?:/.test(r.web)?r.web:`https://${r.web}`} target='_blank' rel='noreferrer' style={{color:C.accent,textDecoration:'none',fontWeight:600}}>{r.web.replace(/^https?:\/\//,'')}</a>}{r.web&&r.linkedin&&<span style={{color:'#CBD5DB'}}> · </span>}{r.linkedin&&<a href={/^https?:/.test(r.linkedin)?r.linkedin:`https://${r.linkedin}`} target='_blank' rel='noreferrer' style={{color:C.accent,textDecoration:'none',fontWeight:600}}>LinkedIn</a>}</div>}
                    {(r.descripcion||r.origen)&&<div style={{fontSize:10,color:C.textSoft,marginTop:1}}>{r.descripcion||''}{r.descripcion&&r.origen?' · ':''}{r.origen?<span><b style={{color:C.muted}}>conocido en</b> {r.origen}</span>:''}</div>}
                  </div>
                  <div style={{display:'flex',flexDirection:'column',gap:4,flexShrink:0}}>
                    <button onClick={()=>startEdit(r)} style={{background:'none',border:'none',color:C.muted,cursor:'pointer',fontSize:11}}>Editar</button>
                    <button onClick={()=>eliminar(r)} style={{background:'none',border:'none',color:C.overdue,cursor:'pointer',fontSize:11}}>Borrar</button>
                  </div>
                </div>
              ))}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

// Escáner Gmail → tareas (modal): usa el helper de arriba. Compuerta humana: crear / editar / descartar.
function GmailTareasModal({clients=[], onCrear, onEditar, onClose}){
  const [phase,setPhase] = useState('idle')
  const [prog,setProg] = useState({done:0,total:0,label:''})
  const [props_,setProps] = useState([])
  const [dismissed,setDismissed] = useState(new Set())
  const [hechas,setHechas] = useState(new Set())
  const [busy,setBusy] = useState('')
  const [err,setErr] = useState('')
  useEffect(()=>{ supabase.from('learnings').select('key').eq('kind','tarea_gmail_descartada').then(({data})=>setDismissed(new Set((data||[]).map(r=>String(r.key)))),()=>{}) },[])
  const clientName = id => clients.find(c=>String(c.id)===String(id))?.name||''
  const fmtVence = iso => { if(!iso) return ''; const p=String(iso).slice(0,10).split('-'); return p.length===3?`${p[2]}-${p[1]}-${p[0]}`:iso }
  const dueCol = iso => { if(!iso) return {bg:C.border,col:C.muted}; const d=Math.round((new Date(iso+'T12:00')-new Date().setHours(0,0,0,0))/86400000); return d<=2?{bg:C.overdueBg,col:C.overdueText}:{bg:C.ambarBg,col:C.soonText} }

  const escanear = async()=>{
    setErr(''); setPhase('scanning'); setProg({done:0,total:0,label:'Buscando no leídos…'})
    try{
      const items = await escanearTareasGmail(clients, (d,t)=>setProg({done:d,total:t,label:'Leyendo asuntos…'}))
      setProps(items.filter(a=>!dismissed.has(a.id)))
      setPhase('review')
    }catch(e){ setErr(e.code===401?'Tu sesión de Google expiró. Cierra sesión y vuelve a entrar.':(e.message||String(e))); setPhase('error') }
  }

  const crear = async(a)=>{ setBusy(a.id); try{ await onCrear({title:a.title, client_id:a.client_id, due:a.due, note:(a.note||'')+(a.note?' · ':'')+'(correo: '+(a.subject||'').slice(0,80)+')'}); setHechas(p=>new Set([...p,a.id])) }catch(e){ appAlert('No se pudo crear: '+e.message) } setBusy('') }
  const descartar = a=>{ learnPut('tarea_gmail_descartada',a.id,'descartada',{}); setDismissed(p=>new Set([...p,a.id])) }
  const visibles = props_.filter(a=>!hechas.has(a.id)&&!dismissed.has(a.id))

  return (
    <div style={{maxWidth:600}}>
      {phase==='idle'&&(
        <div style={{padding:'2px'}}>
          <div style={{display:'flex',alignItems:'center',gap:12,marginBottom:14}}>
            <div style={{width:44,height:44,borderRadius:12,background:C.accent,display:'flex',alignItems:'center',justifyContent:'center',flexShrink:0}}>
              <svg width='22' height='22' viewBox='0 0 24 24' fill='none' stroke='#fff' strokeWidth='2' strokeLinecap='round' strokeLinejoin='round'><path d='M9 11l3 3L22 4'/><path d='M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11'/></svg>
            </div>
            <div style={{minWidth:0}}><div style={{fontSize:15,fontWeight:700,color:C.accent}}>Tareas desde Gmail</div><div style={{fontSize:11,color:C.muted}}>Reviso tus correos no leídos y te propongo tareas</div></div>
          </div>
          <div style={{fontSize:11,color:C.textSoft,marginBottom:12,lineHeight:1.5}}>La IA lee solo el asunto y la vista previa (no el cuerpo completo). Nada se crea solo: tú apruebas, editas o descartas.</div>
          <button onClick={escanear} style={{width:'100%',height:44,borderRadius:12,border:'none',background:C.accent,color:'#fff',fontSize:14,fontWeight:700,cursor:'pointer'}}>Revisar no leídos</button>
        </div>
      )}
      {phase==='scanning'&&(()=>{ const pct=prog.total?Math.round(prog.done/prog.total*100):8; return (
        <div style={{padding:'34px 24px 38px',textAlign:'center'}}>
          <div style={{fontSize:16,fontWeight:700,color:C.accent,marginBottom:4}}>Revisando tu Gmail</div>
          <div style={{fontSize:12,color:C.muted,marginBottom:18}}>{prog.label||'Conectando…'}</div>
          <div style={{height:8,background:C.track,borderRadius:6,overflow:'hidden',maxWidth:340,margin:'0 auto'}}><div style={{height:'100%',width:`${pct}%`,background:C.accent,borderRadius:6,transition:'width .3s'}}/></div>
          <div style={{fontSize:10,color:C.textSoft,marginTop:16,lineHeight:1.5}}>Solo asunto + vista previa a la IA, nunca el cuerpo completo.</div>
        </div>
      )})()}
      {phase==='error'&&(
        <div style={{padding:'24px 10px',textAlign:'center'}}>
          <div style={{fontSize:13,color:C.overdue,marginBottom:14,lineHeight:1.5}}>{err}</div>
          <button onClick={()=>setPhase('idle')} style={{padding:'9px 16px',borderRadius:10,border:`1px solid ${C.border}`,background:'#fff',color:C.muted,fontSize:12,fontWeight:600,cursor:'pointer'}}>Volver</button>
        </div>
      )}
      {phase==='review'&&(
        <div>
          {visibles.length===0
            ? <div style={{textAlign:'center',color:C.muted,fontSize:13,padding:'26px 0'}}>No encontré tareas en tus correos no leídos.</div>
            : <>
              <div style={{fontSize:12,color:C.muted,marginBottom:10}}>{visibles.length} tarea{visibles.length!==1?'s':''} sugerida{visibles.length!==1?'s':''}. Tú decides.</div>
              {visibles.map(a=>{ const dc=dueCol(a.due); return (
                <div key={a.id} style={{border:`1px solid ${C.border}`,borderRadius:10,padding:'10px 12px',marginBottom:8}}>
                  <div style={{fontSize:13,fontWeight:600,color:C.text}}>{a.title}</div>
                  <div style={{fontSize:11,color:C.textSoft,marginTop:2,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>De: {a.fromName} · "{a.subject||'—'}"</div>
                  <div style={{display:'flex',gap:6,flexWrap:'wrap',alignItems:'center',marginTop:7}}>
                    {a.client_id&&<span style={{fontSize:9.5,background:C.azulBg,color:C.accent,borderRadius:20,padding:'2px 8px',fontWeight:700,whiteSpace:'nowrap'}}>{clientName(a.client_id)}</span>}
                    <span style={{fontSize:9.5,background:dc.bg,color:dc.col,borderRadius:20,padding:'2px 8px',fontWeight:700,whiteSpace:'nowrap'}}>{a.due?'Vence '+fmtVence(a.due):'Sin fecha'}</span>
                    <span style={{fontSize:10,color:C.textSoft}}>IA <Sparkle/></span>
                  </div>
                  <div style={{display:'flex',gap:6,marginTop:9}}>
                    <button disabled={busy===a.id} onClick={()=>crear(a)} style={{height:24,padding:'0 12px',borderRadius:8,border:'none',background:C.accent,color:'#fff',fontSize:12,fontWeight:600,cursor:'pointer',opacity:busy===a.id?.6:1}}>Crear tarea</button>
                    <button onClick={()=>{onEditar&&onEditar({title:a.title,client_id:a.client_id,due:a.due,note:a.note});onClose&&onClose()}} style={{height:24,padding:'0 12px',borderRadius:8,border:`0.5px solid ${C.muted}`,background:'#fff',color:C.accent,fontSize:12,cursor:'pointer'}}>Editar</button>
                    <button onClick={()=>descartar(a)} style={{height:24,padding:'0 12px',borderRadius:8,border:`0.5px solid ${C.border}`,background:'#fff',color:C.muted,fontSize:12,cursor:'pointer'}}>Descartar</button>
                  </div>
                </div>
              )})}
            </>}
          <button onClick={()=>setPhase('idle')} style={{width:'100%',height:44,borderRadius:10,border:`1px solid ${C.border}`,background:'#fff',color:C.muted,fontSize:12,fontWeight:600,cursor:'pointer',marginTop:4}}>Volver</button>
        </div>
      )}
    </div>
  )
}
// Clientes › Contactos: personas encontradas en el Gmail del estudio (contactos_candidatos), revisadas por grupos
// (abogado, estado, área, tipo, función, confianza). Confirmar crea el contacto en la ficha con su función;
